window.BOOK={"key":"bidaya","app":"mutoon","lsk":"mutoon_bidaya_v1","title":"بداية الهداية","unitWord":"فقرة","sub":"التزكية والرقائق · أبو حامد الغزالي (ت ٥٠٥هـ) · ٤٧ بابًا","source":"https://shamela.ws/book/12718 (بداية الهداية، تحقيق د. محمد زينهم محمد عزب، مكتبة مدبولي ١٤١٣هـ: أصل النص والعناوين) + تصحيح ما فسد فيه من «مجموعة رسائل الإمام الغزالي»، دار الفكر ١٤١٦هـ https://ketabonline.com/ar/books/16371 + الآيات من api.quran.com (text_imlaei) · قوبل بـ: word-by-word script collation with ketabonline 16371 (Dar al-Fikr); unvocalized — see bidaya-sources.md","note":"النص والعناوين من نشرة زينهم على الشاملة، قوبلت كلمةً كلمةً بسكربت بنشرة دار الفكر (مجموعة رسائل الإمام الغزالي)، وأُخذ من دار الفكر ما فسد في نشرة الشاملة أو سقط منها، وكل ذلك في تقرير المصادر. لم توجد نشرة مشكولة موثوقة على الشبكة، فشُكِّل النص كاملًا بالذكاء الاصطناعي (٢٠٢٦-١١-٠٦) وصُحّحت فيه أغلاط حرفية بشاهد النشرتين، فالتشكيل يحتاج مراجعة.","chapters":[{"id":"bi1","title":"مُقَدِّمَةُ الْمُؤَلِّفِ","units":[{"id":"bi1_1","label":"مُقَدِّمَةُ الْمُؤَلِّفِ · ١","segs":[["matn","بِسْمِ اللَّهِ الرَّحْمَنِ الرَّحِيمِ. قَالَ الشَّيْخُ الْإِمَامُ، الْعَالِمُ الْعَلَّامَةُ، حُجَّةُ الْإِسْلَامِ، وَبَرَكَةُ الْأَنَامِ: أَبُو حَامِدٍ مُحَمَّدُ بْنُ مُحَمَّدِ بْنِ الْغَزَالِيِّ الطُّوسِىُّ؛"]]},{"id":"bi1_2","label":"مُقَدِّمَةُ الْمُؤَلِّفِ · ٢","segs":[["matn","قَدَّسَ اللَّهُ رُوحَهُ، وَنَوَّرَ ضَرِيحَهُ آمِينَ: الْحَمْدُ لِلَّهِ حَقَّ حَمْدِهِ، وَالصَّلَاةُ وَالسَّلَامُ عَلَى خَيْرِ خَلْقِهِ، مُحَمَّدٍ رَسُولِهِ وَعَبْدِهِ، وَعَلَى آلِهِ وَصَحْبِهِ مِنْ بَعْدِهِ."]]},{"id":"bi1_3","label":"مُقَدِّمَةُ الْمُؤَلِّفِ · ٣","segs":[["matn","أَمَّا بَعْدُ: فَاعْلَمْ أَيُّهَا الْحَرِيصُ الْمُقْبِلُ عَلَى اقْتِبَاسِ الْعِلْمِ، الْمُظْهِرُ مِنْ نَفْسِهِ صِدْقَ الرَّغْبَةِ، وَفَرْطَ التَّعَطُّشِ إِلَيْهِ، أَنَّكَ إِنْ كُنْتَ تَقْصِدُ بِالْعِلْمِ الْمُنَافَسَةَ، وَالْمُبَاهَاةَ، وَالتَّقَدُّمَ عَلَى الْأَقْرَانِ، وَاسْتِمَالَةَ وُجُوهِ النَّاسِ إِلَيْكَ، وَجَمْعَ حُطَامِ الدُّنْيَا؛"]]},{"id":"bi1_4","label":"مُقَدِّمَةُ الْمُؤَلِّفِ · ٤","segs":[["matn","فَأَنْتَ سَاعٍ فِي هَدْمِ دِينِكَ، وَإِهْلَاكِ نَفْسِكَ، وَبَيْعِ آخِرَتِكَ بِدُنْيَاكَ؛"]]},{"id":"bi1_5","label":"مُقَدِّمَةُ الْمُؤَلِّفِ · ٥","segs":[["matn","فَصَفْقَتُكَ خَاسِرَةٌ، وَتِجَارَتُكَ بَائِرَةٌ، وَمُعَلِّمُكَ مُعِينٌ لَكَ عَلَى عِصْيَانِكَ، وَشَرِيكٌ لَكَ فِي خُسْرَانِكَ، وَهُوَ كَبَائِعِ سَيْفٍ لِقَاطِعِ طَرِيقٍ، كَمَا قَالَ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: «مَنْ أَعَانَ عَلَى مَعْصِيَةٍ وَلَوْ بِشَطْرِ كَلِمَةٍ كَانَ شَرِيكًا فِيهَا»."]]},{"id":"bi1_6","label":"مُقَدِّمَةُ الْمُؤَلِّفِ · ٦","segs":[["matn","وَإِنْ كَانَتْ نِيَّتُكَ وَقَصْدُكَ، بَيْنَكَ وَبَيْنَ اللَّهِ تَعَالَى، مِنْ طَلَبِ الْعِلْمِ: الْهِدَايَةَ دُونَ مُجَرَّدِ الرِّوَايَةِ؛"]]},{"id":"bi1_7","label":"مُقَدِّمَةُ الْمُؤَلِّفِ · ٧","segs":[["matn","فَأَبْشِرْ؛ فَإِنَّ الْمَلَائِكَةَ تَبْسُطُ لَكَ أَجْنِحَتَهَا إِذَا مَشَيْتَ، وَحِيتَانُ الْبَحْرِ تَسْتَغْفِرُ لَكَ إِذَا سَعَيْتَ."]]},{"id":"bi1_8","label":"مُقَدِّمَةُ الْمُؤَلِّفِ · ٨","segs":[["matn","وَلَكِنْ يَنْبَغِي لَكَ أَنْ تَعْلَمَ، قَبْلَ كُلِّ شَيْءٍ، أَنَّ الْهِدَايَةَ الَّتِي هِيَ ثَمَرَةُ الْعِلْمِ لَهَا بِدَايَةٌ وَنِهَايَةٌ، وَظَاهِرٌ وَبَاطِنٌ، وَلَا وُصُولَ إِلَى نِهَايَتِهَا إِلَّا بَعْدَ إِحْكَامِ بِدَايَتِهَا، وَلَا عُثُورَ عَلَى بَاطِنِهَا إِلَّا بَعْدَ الْوُقُوفِ عَلَى ظَاهِرِهَا."]]},{"id":"bi1_9","label":"مُقَدِّمَةُ الْمُؤَلِّفِ · ٩","segs":[["matn","وَهَأَنَا مُشِيرٌ عَلَيْكَ بِبِدَايَةِ الْهِدَايَةِ؛ لِتُجَرِّبَ بِهَا نَفْسَكَ، وَتَمْتَحِنَ بِهَا قَلْبَكَ، فَإِنْ صَادَفْتَ قَلْبَكَ إِلَيْهَا مَائِلًا، وَنَفْسَكَ بِهَا مُطَاوِعَةً، وَلَهَا قَابِلَةً؛"]]},{"id":"bi1_10","label":"مُقَدِّمَةُ الْمُؤَلِّفِ · ١٠","segs":[["matn","فَدُونَكَ التَّطَلُّعَ إِلَى النِّهَايَاتِ وَالتَّغَلْغُلَ فِي بِحَارِ الْعُلُومِ."]]},{"id":"bi1_11","label":"مُقَدِّمَةُ الْمُؤَلِّفِ · ١١","segs":[["matn","وَإِنْ صَادَفْتَ قَلْبَكَ عِنْدَ مُوَاجَهَتِكَ إِيَّاهَا بِهَا مُسَوِّفًا، وَبِالْعَمَلِ بِمُقْتَضَاهَا مُمَاطِلًا؛"]]},{"id":"bi1_12","label":"مُقَدِّمَةُ الْمُؤَلِّفِ · ١٢","segs":[["matn","فَاعْلَمْ أَنَّ نَفْسَكَ الْمَائِلَةَ إِلَى طَلَبِ الْعِلْمِ هِيَ النَّفْسُ الْأَمَّارَةُ بِالسُّوءِ، وَقَدِ انْتَهَضَتْ مُطِيعَةً لِلشَّيْطَانِ اللَّعِينِ لِيُدَلِّيَكَ بِحَبْلِ غُرُورِهِ؛"]]},{"id":"bi1_13","label":"مُقَدِّمَةُ الْمُؤَلِّفِ · ١٣","segs":[["matn","فَيَسْتَدْرِجَكَ بِمَكِيدَتِهِ إِلَى غَمْرَةِ الْهَلَاكِ، وَقَصْدُهُ أَنْ يُرَوِّجَ عَلَيْكَ الشَّرَّ فِي مَعْرِضِ الْخَيْرِ حَتَّى يُلْحِقَكَ ﴿بِالْأَخْسَرِينَ أَعْمَالًا الَّذِينَ ضَلَّ سَعْيُهُمْ فِي الْحَيَاةِ الدُّنْيَا وَهُمْ يَحْسَبُونَ أَنَّهُمْ يُحْسِنُونَ صُنْعًا﴾."]]},{"id":"bi1_14","label":"مُقَدِّمَةُ الْمُؤَلِّفِ · ١٤","segs":[["matn","وَعِنْدَ ذَلِكَ يَتْلُو عَلَيْكَ الشَّيْطَانُ فَضْلَ الْعِلْمِ وَدَرَجَةَ الْعُلَمَاءِ، وَمَا وَرَدَ فِيهِ مِنَ الْأَخْبَارِ وَالْآثَارِ."]]},{"id":"bi1_15","label":"مُقَدِّمَةُ الْمُؤَلِّفِ · ١٥","segs":[["matn","وَيُلْهِيكَ عَنْ قَوْلِهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: «مَنِ ازْدَادَ عِلْمًا وَلَمْ يَزْدَدْ هُدًى، لَمْ يَزْدَدْ مِنَ اللَّهِ إِلَّا بُعْدًا»، وَعَنْ قَوْلِهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ:"]]},{"id":"bi1_16","label":"مُقَدِّمَةُ الْمُؤَلِّفِ · ١٦","segs":[["matn","«أَشَدُّ النَّاسِ عَذَابًا يَوْمَ الْقِيَامَةِ عَالِمٌ لَمْ يَنْفَعْهُ اللَّهُ بِعِلْمِهِ» وَكَانَ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: «اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ عِلْمٍ لَا يَنْفَعُ، وَقَلْبٍ لَا يَخْشَعُ، وَعَمَلٍ لَا يُرْفَعُ، وَدُعَاءٍ لَا يُسْمَعُ»."]]},{"id":"bi1_17","label":"مُقَدِّمَةُ الْمُؤَلِّفِ · ١٧","segs":[["matn","وَعَنْ قَوْلِهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: «مَرَرْتُ لَيْلَةَ أُسْرِيَ بِي بِأَقْوَامٍ تُقْرَضُ شِفَاهُهُمْ بِمَقَارِيضَ مِنْ نَارٍ، فَقُلْتُ: مَنْ أَنْتُمْ؟"]]},{"id":"bi1_18","label":"مُقَدِّمَةُ الْمُؤَلِّفِ · ١٨","segs":[["matn","قَالُوا: كُنَّا نَأْمُرُ بِالْخَيْرِ وَلَا نَأْتِيهِ وَنَنْهَى عَنِ الشَّرِّ وَنَأْتِيهِ»."]]},{"id":"bi1_19","label":"مُقَدِّمَةُ الْمُؤَلِّفِ · ١٩","segs":[["matn","فَإِيَّاكَ يَا مِسْكِينُ أَنْ تُذْعِنَ لِتَزْوِيرِهِ فَيُدَلِّيَكَ بِحَبْلِ غُرُورِهِ، فَوَيْلٌ لِلْجَاهِلِ حَيْثُ لَمْ يَتَعَلَّمْ مَرَّةً وَاحِدَةً، وَوَيْلٌ لِلْعَالِمِ حَيْثُ لَمْ يَعْمَلْ بِمَا عَلِمَ أَلْفَ مَرَّةٍ."]]},{"id":"bi1_20","label":"مُقَدِّمَةُ الْمُؤَلِّفِ · ٢٠","segs":[["matn","وَاعْلَمْ أَنَّ النَّاسَ فِي طَلَبِ الْعِلْمِ عَلَى ثَلَاثَةِ أَحْوَالٍ: رَجُلٌ طَلَبَ الْعِلْمَ لِيَتَّخِذَهُ زَادَهُ إِلَى الْمَعَادِ، وَلَمْ يَقْصِدْ بِهِ إِلَّا وَجْهَ اللَّهِ وَالدَّارَ الْآخِرَةَ؛"]]},{"id":"bi1_21","label":"مُقَدِّمَةُ الْمُؤَلِّفِ · ٢١","segs":[["matn","فَهَذَا مِنَ الْفَائِزِينَ. وَرَجُلٌ طَلَبَهُ لِيَسْتَعِينَ بِهِ عَلَى حَيَاتِهِ الْعَاجِلَةِ، وَيَنَالَ بِهِ الْعِزَّ وَالْجَاهَ وَالْمَالَ، وَهُوَ عَالِمٌ بِذَلِكَ، مُسْتَشْعِرٌ فِي قَلْبِهِ رَكَاكَةَ حَالِهِ وَخِسَّةَ مَقْصِدِهِ، فَهَذَا مِنَ الْمُخَاطِرِينَ."]]},{"id":"bi1_22","label":"مُقَدِّمَةُ الْمُؤَلِّفِ · ٢٢","segs":[["matn","فَإِنْ عَاجَلَهُ أَجَلُهُ قَبْلَ التَّوْبَةِ خِيفَ عَلَيْهِ مِنْ سُوءِ الْخَاتِمَةِ، وَبَقِيَ أَمْرُهُ فِي خَطَرِ الْمَشِيئَةِ؛"]]},{"id":"bi1_23","label":"مُقَدِّمَةُ الْمُؤَلِّفِ · ٢٣","segs":[["matn","وَإِنْ وُفِّقَ لِلتَّوْبَةِ قَبْلَ حُلُولِ الْأَجَلِ، وَأَضَافَ إِلَى الْعِلْمِ الْعَمَلَ، وَتَدَارَكَ مَا فَرَطَ مِنْهُ مِنَ الْخَلَلِ - الْتَحَقَ بِالْفَائِزِينَ، فَإِنَّ التَّائِبَ مِنَ الذَّنْبِ كَمَنْ لَا ذَنْبَ لَهُ."]]},{"id":"bi1_24","label":"مُقَدِّمَةُ الْمُؤَلِّفِ · ٢٤","segs":[["matn","وَرَجُلٌ ثَالِثٌ اسْتَحْوَذَ عَلَيْهِ الشَّيْطَانُ؛ فَاتَّخَذَ عِلْمَهُ ذَرِيعَةً إِلَى التَّكَاثُرِ بِالْمَالِ، وَالتَّفَاخُرِ بِالْجَاهِ، وَالتَّعَزُّزِ بِكَثْرَةِ الْأَتْبَاعِ، يَدْخُلُ بِعِلْمِهِ كُلَّ مَدْخَلٍ رَجَاءَ أَنْ يَقْضِيَ مِنَ الدُّنْيَا وَطَرَهُ، وَهُوَ مَعَ ذَلِكَ يُضْمِرُ فِي نَفْسِهِ أَنَّهُ عِنْدَ اللَّهِ بِمَكَانَةٍ،"]]},{"id":"bi1_25","label":"مُقَدِّمَةُ الْمُؤَلِّفِ · ٢٥","segs":[["matn","لِاتِّسَامِهِ بِسِمَةِ الْعُلَمَاءِ، وَتَرَسُّمِهِ بِرُسُومِهِمْ فِي الزِّيِّ وَالْمَنْطِقِ، مَعَ تَكَالُبِهِ عَلَى الدُّنْيَا ظَاهِرًا وَبَاطِنًا، فَهَذَا مِنَ الْهَالِكِينَ، وَمِنَ الْحَمْقَى الْمَغْرُورِينَ؛"]]},{"id":"bi1_26","label":"مُقَدِّمَةُ الْمُؤَلِّفِ · ٢٦","segs":[["matn","إِذِ الرَّجَاءُ مُنْقَطِعٌ عَنْ تَوْبَتِهِ لِظَنِّهِ أَنَّهُ مِنَ الْمُحْسِنِينَ، وَهُوَ غَافِلٌ عَنْ قَوْلِهِ تَعَالَى ﴿يَا أَيُّهَا الَّذِينَ آمَنُوا لِمَ تَقُولُونَ مَا لَا تَفْعَلُونَ﴾."]]},{"id":"bi1_27","label":"مُقَدِّمَةُ الْمُؤَلِّفِ · ٢٧","segs":[["matn","وَهُوَ مِمَّنْ قَالَ فِيهِمْ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: «أَنَا مِنْ غَيْرِ الدَّجَّالِ أَخْوَفُ عَلَيْكُمْ مِنَ الدَّجَّالِ» فَقِيلَ: وَمَا هُوَ يَا رَسُولَ اللَّهِ؟، فَقَالَ: «عُلَمَاءُ السُّوءِ»."]]},{"id":"bi1_28","label":"مُقَدِّمَةُ الْمُؤَلِّفِ · ٢٨","segs":[["matn","وَهَذَا لِأَنَّ الدَّجَّالَ غَايَتُهُ الْإِضْلَالُ، وَمِثْلُ هَذَا الْعَالِمِ وَإِنْ صَرَفَ النَّاسَ عَنِ الدُّنْيَا بِلِسَانِهِ وَمَقَالِهِ فَهُوَ دَافِعٌ لَهُمْ إِلَيْهَا بِأَعْمَالِهِ وَأَحْوَالِهِ، وَلِسَانُ الْحَالِ أَفْصَحُ مِنْ لِسَانِ الْمَقَالِ، وَطِبَاعُ النَّاسِ إِلَى الْمُسَاعَدَةِ فِي الْأَعْمَالِ أَمْيَلُ مِنْهَا إِلَى الْمُتَابَعَةِ فِي الْأَقْوَالِ؛"]]},{"id":"bi1_29","label":"مُقَدِّمَةُ الْمُؤَلِّفِ · ٢٩","segs":[["matn","فَمَا أَفْسَدَهُ هَذَا الْمَغْرُورُ بِأَعْمَالِهِ أَكْثَرُ مِمَّا أَصْلَحَهُ بِأَقْوَالِهِ، إِذْ لَا يَسْتَجْرِئُ الْجَاهِلُ عَلَى الرَّغْبَةِ فِي الدُّنْيَا إِلَّا بِاسْتِجْرَاءِ الْعُلَمَاءِ، فَقَدْ صَارَ عِلْمُهُ سَبَبًا لِجُرْأَةِ عِبَادِ اللَّهِ عَلَى مَعَاصِيهِ،"]]},{"id":"bi1_30","label":"مُقَدِّمَةُ الْمُؤَلِّفِ · ٣٠","segs":[["matn","وَنَفْسُهُ الْجَاهِلَةُ مُدِلَّةٌ مَعَ ذَلِكَ تُمَنِّيهِ وَتُرَجِّيهِ، وَتَدْعُوهُ إِلَى أَنْ يَمُنَّ عَلَى اللَّهِ بِعِلْمِهِ، وَتُخَيِّلُ إِلَيْهِ نَفْسُهُ أَنَّهُ خَيْرٌ مِنْ كَثِيرٍ مِنْ عِبَادِ اللَّهِ."]]},{"id":"bi1_31","label":"مُقَدِّمَةُ الْمُؤَلِّفِ · ٣١","segs":[["matn","فَكُنْ أَيُّهَا الطَّالِبُ مِنَ الْفَرِيقِ الْأَوَّلِ، وَاحْذَرْ أَنْ تَكُونَ مِنَ الْفَرِيقِ الثَّانِي، فَكَمْ مِنْ مُسَوِّفٍ عَاجَلَهُ الْأَجَلُ قَبْلَ التَّوْبَةِ فَخَسِرَ، وَإِيَّاكَ ثُمَّ إِيَّاكَ أَنْ تَكُونَ مِنَ الْفَرِيقِ الثَّالِثِ، فَتَهْلِكَ هَلَاكًا لَا يُرْجَى مَعَهُ فَلَاحُكَ، وَلَا يُنْتَظَرُ صَلَاحُكَ."]]},{"id":"bi1_32","label":"مُقَدِّمَةُ الْمُؤَلِّفِ · ٣٢","segs":[["matn","فَإِنْ قُلْتَ: فَمَا بِدَايَةُ الْهِدَايَةِ لِأُجَرِّبَ بِهَا نَفْسِي، فَاعْلَمْ أَنَّ بِدَايَتَهَا ظَاهِرَةُ التَّقْوَى، وَنِهَايَتَهَا بَاطِنَةُ التَّقْوَى؛"]]},{"id":"bi1_33","label":"مُقَدِّمَةُ الْمُؤَلِّفِ · ٣٣","segs":[["matn","فَلَا عَاقِبَةَ إِلَّا بِالتَّقْوَى، وَلَا هِدَايَةَ إِلَّا لِلْمُتَّقِينَ."]]},{"id":"bi1_34","label":"مُقَدِّمَةُ الْمُؤَلِّفِ · ٣٤","segs":[["matn","وَالتَّقْوَى، عِبَارَةٌ عَنِ امْتِثَالِ أَوَامِرِ اللَّهِ تَعَالَى، وَاجْتِنَابِ نَوَاهِيهِ، فَهُمَا قِسْمَانِ، وَهَا أَنَا أُشِيرُ عَلَيْكَ بِجُمَلٍ مُخْتَصَرَةٍ مِنْ ظَاهِرِ عِلْمِ التَّقْوَى فِي الْقِسْمَيْنِ جَمِيعًا، وَأُلْحِقُ قِسْمًا ثَالِثًا لِيَصِيرَ هَذَا الْكِتَابُ جَامِعًا مُغْنِيًا وَاللَّهُ الْمُسْتَعَانُ."]]}]},{"id":"bi2","title":"تَوْطِئَةٌ","units":[{"id":"bi2_1","label":"تَوْطِئَةٌ · ١","segs":[["matn","اعْلَمْ أَنَّ أَوَامِرَ اللَّهِ تَعَالَى فَرَائِضُ وَنَوَافِلُ؛ فَالْفَرْضُ رَأْسُ الْمَالِ، وَهُوَ أَصْلُ التِّجَارَةِ وَبِهِ تَحْصُلُ النَّجَاةُ، وَالنَّفْلُ هُوَ الرِّبْحُ وَبِهِ الْفَوْزُ بِالدَّرَجَاتِ، قَالَ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: «يَقُولُ اللَّهُ تَبَارَكَ وَتَعَالَى: «مَا تَقَرَّبَ إِلَيَّ الْمُتَقَرِّبُونَ بِمِثْلِ أَدَاءِ مَا افْتَرَضْتُ عَلَيْهِمْ،"]]},{"id":"bi2_2","label":"تَوْطِئَةٌ · ٢","segs":[["matn","وَلَا يَزَالُ الْعَبْدُ يَتَقَرَّبُ إِلَيَّ بِالنَّوَافِلِ حَتَّى أُحِبَّهُ، فَإِذَا أَحْبَبْتُهُ كُنْتُ سَمْعَهُ الَّذِي يَسْمَعُ بِهِ، وَبَصَرَهُ الَّذِي يُبْصِرُ بِهِ، وَلِسَانَهُ الَّذِي يَنْطِقُ بِهِ، وَيَدَهُ الَّتِي يَبْطِشُ بِهَا، وَرِجْلَهُ الَّتِي يَمْشِي بِهَا»."]]},{"id":"bi2_3","label":"تَوْطِئَةٌ · ٣","segs":[["matn","وَلَنْ تَصِلَ أَيُّهَا الطَّالِبُ إِلَى الْقِيَامِ بِأَوَامِرِ اللَّهِ تَعَالَى إِلَّا بِمُرَاقَبَةِ قَلْبِكَ وَجَوَارِحِكَ فِي لَحَظَاتِكَ وَأَنْفَاسِكَ، حِينَ تُصْبِحُ إِلَى حِينِ تُمْسِي."]]},{"id":"bi2_4","label":"تَوْطِئَةٌ · ٤","segs":[["matn","فَاعْلَمْ أَنَّ اللَّهَ تَعَالَى مُطَّلِعٌ عَلَى ضَمِيرِكَ، وَمُشْرِفٌ عَلَى ظَاهِرِكَ وَبَاطِنِكَ، وَمُحِيطٌ بِجَمِيعِ لَحَظَاتِكَ، وَخَطَرَاتِكَ، وَخَطَوَاتِكَ، وَسَائِرِ سَكَنَاتِكَ وَحَرَكَاتِكَ؛"]]},{"id":"bi2_5","label":"تَوْطِئَةٌ · ٥","segs":[["matn","وَأَنَّكَ فِي مُخَالَطَتِكَ وَخَلَوَاتِكَ مُتَرَدِّدٌ بَيْنَ يَدَيْهِ؛ فَلَا يَسْكُنُ فِي الْمُلْكِ وَالْمَلَكُوتِ سَاكِنٌ، وَلَا يَتَحَرَّكُ مُتَحَرِّكٌ، إِلَّا وَجَبَّارُ السَّمَوَاتِ وَالْأَرْضِ مُطَّلِعٌ عَلَيْهِ، ﴿يَعْلَمُ خَائِنَةَ الْأَعْيُنِ وَمَا تُخْفِي الصُّدُورُ﴾، وَ﴿يَعْلَمُ السِّرَّ وَأَخْفَى﴾؛"]]},{"id":"bi2_6","label":"تَوْطِئَةٌ · ٦","segs":[["matn","فَتَأَدَّبْ أَيُّهَا الْمِسْكِينُ ظَاهِرًا وَبَاطِنًا بَيْنَ يَدَيِ اللَّهِ تَعَالَى تَأَدُّبَ الْعَبْدِ الذَّلِيلِ الْمُذْنِبِ فِي حَضْرَةِ الْمَلِكِ الْجَبَّارِ الْقَهَّارِ، وَاجْتَهِدْ أَنْ لَا يَرَاكَ مَوْلَاكَ حَيْثُ نَهَاكَ، وَلَا يَفْقِدَكَ حَيْثُ أَمَرَكَ."]]},{"id":"bi2_7","label":"تَوْطِئَةٌ · ٧","segs":[["matn","وَلَنْ تَقْدِرَ عَلَى ذَلِكَ إِلَّا بِأَنْ تُوَزِّعَ أَوْقَاتَكَ، وَتُرَتِّبَ أَوْرَادَكَ مِنْ صَبَاحِكَ إِلَى مَسَائِكَ، فَأَصْغِ إِلَى مَا يُلْقَى إِلَيْكَ مِنْ أَوَامِرِ اللَّهِ تَعَالَى عَلَيْكَ مِنْ حِينِ تَسْتَيْقِظُ مِنْ مَنَامِكَ إِلَى وَقْتِ رُجُوعِكَ إِلَى مَضْجَعِكَ."]]}],"group":"الْقِسْمُ الْأَوَّلُ فِي الطَّاعَاتِ"},{"id":"bi3","title":"فَصْلٌ فِي آدَابِ الِاسْتِيقَاظِ مِنَ النَّوْمِ","units":[{"id":"bi3_1","label":"فَصْلٌ فِي آدَابِ الِاسْتِيقَاظِ مِنَ النَّوْمِ · ١","segs":[["matn","فَإِذَا اسْتَيْقَظْتَ مِنَ النَّوْمِ، فَاجْتَهِدْ أَنْ تَسْتَيْقِظَ قَبْلَ طُلُوعِ الْفَجْرِ، وَلْيَكُنْ أَوَّلُ مَا يَجْرِي عَلَى قَلْبِكَ وَلِسَانِكَ ذِكْرَ اللَّهِ تَعَالَى؛"]]},{"id":"bi3_2","label":"فَصْلٌ فِي آدَابِ الِاسْتِيقَاظِ مِنَ النَّوْمِ · ٢","segs":[["matn","فَقُلْ عِنْدَ ذَلِكَ: الْحَمْدُ لِلَّهِ الَّذِي أَحْيَانَا بَعْدَ مَا أَمَاتَنَا وَإِلَيْهِ النُّشُورُ، أَصْبَحْنَا وَأَصْبَحَ الْمُلْكُ لِلَّهِ، وَالْعَظَمَةُ وَالسُّلْطَانُ لِلَّهِ، وَالْعِزَّةُ وَالْقُدْرَةُ لِلَّهِ رَبِّ الْعَالَمِينَ،"]]},{"id":"bi3_3","label":"فَصْلٌ فِي آدَابِ الِاسْتِيقَاظِ مِنَ النَّوْمِ · ٣","segs":[["matn","أَصْبَحْنَا عَلَى فِطْرَةِ الْإِسْلَامِ، وَعَلَى كَلِمَةِ الْإِخْلَاصِ، وَعَلَى دِينِ نَبِيِّنَا مُحَمَّدٍ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، وَعَلَى مِلَّةِ أَبِينَا إِبْرَاهِيمَ حَنِيفًا مُسْلِمًا وَمَا كَانَ مِنَ الْمُشْرِكِينَ؛"]]},{"id":"bi3_4","label":"فَصْلٌ فِي آدَابِ الِاسْتِيقَاظِ مِنَ النَّوْمِ · ٤","segs":[["matn","اللَّهُمَّ بِكَ أَصْبَحْنَا، وَبِكَ أَمْسَيْنَا، وَبِكَ نَحْيَا، وَبِكَ نَمُوتُ، وَإِلَيْكَ النُّشُورُ؛"]]},{"id":"bi3_5","label":"فَصْلٌ فِي آدَابِ الِاسْتِيقَاظِ مِنَ النَّوْمِ · ٥","segs":[["matn","اللَّهُمَّ إِنَّا نَسْأَلُكَ أَنْ تَبْعَثَنَا فِي هَذَا الْيَوْمِ إِلَى كُلِّ خَيْرٍ، وَنَعُوذُ بِكَ أَنْ نَجْتَرِحَ فِيهِ سُوءًا أَوْ نَجُرَّهُ إِلَى مُسْلِمٍ، أَوْ يَجُرَّهُ أَحَدٌ إِلَيْنَا؛"]]},{"id":"bi3_6","label":"فَصْلٌ فِي آدَابِ الِاسْتِيقَاظِ مِنَ النَّوْمِ · ٦","segs":[["matn","نَسْأَلُكَ خَيْرَ هَذَا الْيَوْمِ وَخَيْرَ مَا فِيهِ وَنَعُوذُ بِكَ مِنْ شَرِّ هَذَا الْيَوْمِ وَشَرِّ مَا فِيهِ."]]},{"id":"bi3_7","label":"فَصْلٌ فِي آدَابِ الِاسْتِيقَاظِ مِنَ النَّوْمِ · ٧","segs":[["matn","فَإِذَا لَبِسْتَ ثِيَابَكَ فَانْوِ بِهِ امْتِثَالَ أَمْرِ اللَّهِ تَعَالَى فِي سَتْرِ عَوْرَتِكَ، وَاحْذَرْ أَنْ يَكُونَ قَصْدُكَ مِنْ لِبَاسِكَ مُرَاءَاةَ الْخَلْقِ فَتَخْسَرَ."]]}],"group":"الْقِسْمُ الْأَوَّلُ فِي الطَّاعَاتِ"},{"id":"bi4","title":"بَابُ آدَابِ دُخُولِ الْخَلَاءِ","units":[{"id":"bi4_1","label":"بَابُ آدَابِ دُخُولِ الْخَلَاءِ · ١","segs":[["matn","فَإِذَا قَصَدْتَ بَيْتَ الْمَاءِ لِقَضَاءِ الْحَاجَةِ، فَقَدِّمْ فِي الدُّخُولِ رِجْلَكَ الْيُسْرَى، وَفِي الْخُرُوجِ رِجْلَكَ الْيُمْنَى، وَلَا تَسْتَصْحِبْ شَيْئًا عَلَيْهِ اسْمُ اللَّهِ تَعَالَى وَرَسُولِهِ."]]},{"id":"bi4_2","label":"بَابُ آدَابِ دُخُولِ الْخَلَاءِ · ٢","segs":[["matn","وَلَا تَدْخُلْ حَاسِرَ الرَّأْسِ، وَلَا حَافِيَ الْقَدَمَيْنِ. وَقُلْ عِنْدَ الدُّخُولِ: بِاسْمِ اللَّهِ، أَعُوذُ بِاللَّهِ مِنَ الرِّجْسِ النَّجِسِ، الْخَبِيثِ الْمُخْبِثِ، الشَّيْطَانِ الرَّجِيمِ."]]},{"id":"bi4_3","label":"بَابُ آدَابِ دُخُولِ الْخَلَاءِ · ٣","segs":[["matn","وَعِنْدَ الْخُرُوجِ: غُفْرَانَكَ، الْحَمْدُ لِلَّهِ الَّذِي أَذْهَبَ عَنِّي مَا يُؤْذِينِي وَأَبْقَى فِيَّ مَا يَنْفَعُنِي."]]},{"id":"bi4_4","label":"بَابُ آدَابِ دُخُولِ الْخَلَاءِ · ٤","segs":[["matn","وَيَنْبَغِي أَنْ تُعِدَّ النُّبَلَ قَبْلَ قَضَاءِ الْحَاجَةِ، وَأَنْ لَا تَسْتَنْجِيَ بِالْمَاءِ فِي مَوْضِعِ قَضَاءِ الْحَاجَةِ، وَأَنْ تَسْتَبْرِئَ مِنَ الْبَوْلِ بِالتَّنَحْنُحِ وَالنَّتْرِ ثَلَاثًا، وَبِإِمْرَارِ الْيَدِ الْيُسْرَى عَلَى أَسْفَلِ الْقَضِيبِ."]]},{"id":"bi4_5","label":"بَابُ آدَابِ دُخُولِ الْخَلَاءِ · ٥","segs":[["matn","وَإِنْ كُنْتَ فِي الصَّحْرَاءِ، فَابْعُدْ عَنْ عُيُونِ النَّاظِرِينَ وَاسْتَتِرْ بِشَيْءٍ إِنْ وَجَدْتَهُ، وَلَا تَكْشِفْ عَوْرَتَكَ قَبْلَ الِانْتِهَاءِ إِلَى مَوْضِعِ الْجُلُوسِ."]]},{"id":"bi4_6","label":"بَابُ آدَابِ دُخُولِ الْخَلَاءِ · ٦","segs":[["matn","وَلَا تَسْتَقْبِلِ الشَّمْسَ وَلَا الْقَمَرَ، وَلَا تَسْتَقْبِلِ الْقِبْلَةَ وَلَا تَسْتَدْبِرْهَا، وَلَا تَجْلِسْ فِي مُتَحَدَّثِ النَّاسِ، وَلَا تَبُلْ فِي الْمَاءِ الرَّاكِدِ وَتَحْتَ الشَّجَرَةِ الْمُثْمِرَةِ، وَلَا فِي الْجُحْرِ، وَاحْذَرِ الْأَرْضَ الصُّلْبَةَ وَمَهَبَّ الرِّيحِ، احْتِرَازًا مِنَ الرَّشَاشِ لِقَوْلِهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: «إِنَّ عَامَّةَ الْوَسْوَاسِ مِنْهُ»."]]},{"id":"bi4_7","label":"بَابُ آدَابِ دُخُولِ الْخَلَاءِ · ٧","segs":[["matn","وَاتَّكِئْ فِي جُلُوسِكَ عَلَى الرِّجْلِ الْيُسْرَى، وَلَا تَبُلْ قَائِمًا إِلَّا عَنْ ضَرُورَةٍ، وَاجْمَعْ فِي الِاسْتِنْجَاءِ بَيْنَ اسْتِعْمَالِ الْحَجَرِ وَالْمَاءِ، فَإِذَا أَرَدْتَ الِاقْتِصَارَ عَلَى أَحَدِهِمَا فَالْمَاءُ أَفْضَلُ، وَإِذَا اقْتَصَرْتَ عَلَى الْحَجَرِ فَعَلَيْكَ أَنْ تَسْتَعْمِلَ ثَلَاثَةَ أَحْجَارٍ طَاهِرَةٍ مُنَشِّفَةٍ لِلْعَيْنِ،"]]},{"id":"bi4_8","label":"بَابُ آدَابِ دُخُولِ الْخَلَاءِ · ٨","segs":[["matn","تَمْسَحُ بِهَا مَحَلَّ النَّجْوِ بِحَيْثُ لَا تَنْقُلُ النَّجَاسَةَ عَنْ مَوْضِعِهَا، وَكَذَلِكَ تَمْسَحُ الْقَضِيبَ فِي ثَلَاثَةِ مَوَاضِعَ مِنْ حَجَرٍ، فَإِنْ لَمْ يَحْصُلِ الْإِنْقَاءُ بِثَلَاثَةٍ فَتَمِّمْ خَمْسَةً أَوْ سَبْعَةً إِلَى أَنْ يَنْقَى بِالْإِيتَارِ؛"]]},{"id":"bi4_9","label":"بَابُ آدَابِ دُخُولِ الْخَلَاءِ · ٩","segs":[["matn","فَالْإِيتَارُ مُسْتَحَبٌّ وَالْإِنْقَاءُ وَاجِبٌ. وَلَا تَسْتَنْجِ إِلَّا بِالْيَدِ الْيُسْرَى."]]},{"id":"bi4_10","label":"بَابُ آدَابِ دُخُولِ الْخَلَاءِ · ١٠","segs":[["matn","وَقُلْ عِنْدَ الْفَرَاغِ مِنَ الِاسْتِنْجَاءِ: اللَّهُمَّ طَهِّرْ قَلْبِي مِنَ النِّفَاقِ وَحَصِّنْ فَرْجِي مِنَ الْفَوَاحِشِ."]]},{"id":"bi4_11","label":"بَابُ آدَابِ دُخُولِ الْخَلَاءِ · ١١","segs":[["matn","وَادْعَكْ يَدَكَ بَعْدَ تَمَامِ الِاسْتِنْجَاءِ بِالْأَرْضِ أَوْ بِحَائِطٍ ثُمَّ اغْسِلْهَا."]]}],"group":"الْقِسْمُ الْأَوَّلُ فِي الطَّاعَاتِ"},{"id":"bi5","title":"بَابُ آدَابِ الْوُضُوءِ","units":[{"id":"bi5_1","label":"بَابُ آدَابِ الْوُضُوءِ · ١","segs":[["matn","فَإِذَا فَرَغْتَ مِنَ الِاسْتِنْجَاءِ، فَلَا تَتْرُكِ السِّوَاكَ؛ فَإِنَّهُ مَطْهَرَةٌ لِلْفَمِ، وَمَرْضَاةٌ لِلرَّبِّ، وَمَسْخَطَةٌ لِلشَّيْطَانِ وَصَلَاةٌ بِسِوَاكٍ أَفْضَلُ مِنْ سَبْعِينَ صَلَاةً بِلَا سِوَاكٍ."]]},{"id":"bi5_2","label":"بَابُ آدَابِ الْوُضُوءِ · ٢","segs":[["matn","وَرُوِيَ عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: «لَوْلَا أَنْ أَشُقَّ عَلَى أُمَّتِي لَأَمَرْتُهُمْ بِالسِّوَاكِ فِي كُلِّ صَلَاةٍ»، وَعَنْهُ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: «أُمِرْتُ بِالسِّوَاكِ حَتَّى خَشِيتُ أَنْ يُكْتَبَ عَلَيَّ»."]]},{"id":"bi5_3","label":"بَابُ آدَابِ الْوُضُوءِ · ٣","segs":[["matn","ثُمَّ اجْلِسْ لِلْوُضُوءِ مُسْتَقْبِلَ الْقِبْلَةِ عَلَى مَوْضِعٍ مُرْتَفِعٍ كَيْ لَا يُصِيبَكَ الرَّشَاشُ، وَقُلْ بِسْمِ اللَّهِ الرَّحْمَنِ الرَّحِيمِ، رَبِّ أَعُوذُ بِكَ مِنْ هَمَزَاتِ الشَّيَاطِينِ وَأَعُوذُ بِكَ رَبِّ أَنْ يَحْضُرُونِ."]]},{"id":"bi5_4","label":"بَابُ آدَابِ الْوُضُوءِ · ٤","segs":[["matn","ثُمَّ اغْسِلْ يَدَيْكَ ثَلَاثًا قَبْلَ أَنْ تُدْخِلَهُمَا الْإِنَاءَ، وَقُلْ: اللَّهُمَّ إِنِّي أَسْأَلُكَ الْيُمْنَ وَالْبَرَكَةَ، وَأَعُوذُ بِكَ مِنَ الشُّؤْمِ وَالْهَلَكَةِ."]]},{"id":"bi5_5","label":"بَابُ آدَابِ الْوُضُوءِ · ٥","segs":[["matn","ثُمَّ انْوِ رَفْعَ الْحَدَثِ وَاسْتِبَاحَةَ الصَّلَاةِ، وَلَا يَنْبَغِي أَنْ تَعْزُبَ نِيَّتُكَ قَبْلَ غَسْلِ الْوَجْهِ، فَلَا يَصِحُّ وُضُوؤُكَ."]]},{"id":"bi5_6","label":"بَابُ آدَابِ الْوُضُوءِ · ٦","segs":[["matn","ثُمَّ خُذْ غُرْفَةً لِفَمِكَ وَتَمَضْمَضْ بِهَا ثَلَاثًا، وَبَالِغْ فِي رَدِّ الْمَاءِ إِلَى الْغَلْصَمَةِ إِلَّا أَنْ تَكُونَ صَائِمًا فَتَرَفَّقْ، وَقُلِ اللَّهُمَّ أَعِنِّي عَلَى تِلَاوَةِ كِتَابِكَ وَكَثْرَةِ الذِّكْرِ لَكَ، وَثَبِّتْنِي بِالْقَوْلِ الثَّابِتِ فِي الْحَيَاةِ الدُّنْيَا وَفِي الْآخِرَةِ."]]},{"id":"bi5_7","label":"بَابُ آدَابِ الْوُضُوءِ · ٧","segs":[["matn","ثُمَّ خُذْ غُرْفَةً لِأَنْفِكَ وَاسْتَنْشِقْ بِهَا ثَلَاثًا، وَاسْتَنْثِرْ مَا فِي الْأَنْفِ مِنْ رُطُوبَةٍ، وَقُلْ فِي الِاسْتِنْشَاقِ: اللَّهُمَّ أَرِحْنِي رَائِحَةَ الْجَنَّةِ وَأَنْتَ عَنِّي رَاضٍ، وَفِي الِاسْتِنْثَارِ: اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ رَوَائِحِ النَّارِ وَسُوءِ الدَّارِ."]]},{"id":"bi5_8","label":"بَابُ آدَابِ الْوُضُوءِ · ٨","segs":[["matn","ثُمَّ خُذْ غُرْفَةً لِوَجْهِكَ، فَاغْسِلْ بِهَا مِنْ مُبْتَدَأِ تَسْطِيحِ الْجَبْهَةِ إِلَى مُنْتَهَى مَا يُقْبِلُ مِنَ الذَّقَنِ فِي الطُّولِ، وَمِنَ الْأُذُنِ إِلَى الْأُذُنِ فِي الْعَرْضِ، وَأَوْصِلِ الْمَاءَ إِلَى مَوْضِعِ التَّحْذِيفِ، وَهُوَ مَا يَعْتَادُ النِّسَاءُ تَنْحِيَةَ الشَّعْرِ عَنْهُ، وَهُوَ مَا بَيْنَ رَأْسِ الْأُذُنِ إِلَى زَاوِيَةِ الْجَبِينِ،"]]},{"id":"bi5_9","label":"بَابُ آدَابِ الْوُضُوءِ · ٩","segs":[["matn","أَعْنِي مَا يَقَعُ مِنْهُ فِي جَبْهَةِ الْوَجْهِ، وَأَوْصِلِ الْمَاءَ إِلَى مَنَابِتِ الشُّعُورِ الْأَرْبَعَةِ: الْحَاجِبَيْنِ، وَالشَّارِبَيْنِ، وَالْأَهْدَابِ، وَالْعِذَارَيْنِ «وَهُمَا مَا يُوَازِيَانِ الْأُذُنَيْنِ، مِنْ مُبْتَدَأِ اللِّحْيَةِ»، وَيَجِبُ إِيصَالُ الْمَاءِ إِلَى مَنَابِتِ الشَّعْرِ مِنَ اللِّحْيَةِ الْخَفِيفَةِ، دُونَ الْكَثِيفَةِ؛"]]},{"id":"bi5_10","label":"بَابُ آدَابِ الْوُضُوءِ · ١٠","segs":[["matn","وَقُلْ عِنْدَ غَسْلِ الْوَجْهِ: اللَّهُمَّ بَيِّضْ وَجْهِي بِنُورِكَ يَوْمَ تَبْيَضُّ وُجُوهُ أَوْلِيَائِكَ، وَلَا تُسَوِّدْ وَجْهِي بِظُلُمَاتِكَ يَوْمَ تَسْوَدُّ وُجُوهُ أَعْدَائِكَ، وَلَا تَتْرُكْ تَخْلِيلَ اللِّحْيَةِ الْكَثِيفَةِ."]]},{"id":"bi5_11","label":"بَابُ آدَابِ الْوُضُوءِ · ١١","segs":[["matn","ثُمَّ اغْسِلْ يَدَكَ الْيُمْنَى، ثُمَّ الْيُسْرَى مَعَ الْمِرْفَقَيْنِ إِلَى أَنْصَافِ الْعَضُدَيْنِ، فَإِنَّ الْحِلْيَةَ فِي الْجَنَّةِ تَبْلُغُ مَوَاضِعَ الْوُضُوءِ."]]},{"id":"bi5_12","label":"بَابُ آدَابِ الْوُضُوءِ · ١٢","segs":[["matn","وَقُلْ عِنْدَ غَسْلِ الْيَدِ الْيُمْنَى: أَعْطِنِي كِتَابِي بِيَمِينِي، وَحَاسِبْنِي حِسَابًا يَسِيرًا، وَعِنْدَ غَسْلِ الشِّمَالِ: اللَّهُمَّ إِنِّي أَعُوذُ بِكَ أَنْ تُعْطِيَنِي كِتَابِي بِشِمَالِي أَوْ مِنْ وَرَاءِ ظَهْرِي."]]},{"id":"bi5_13","label":"بَابُ آدَابِ الْوُضُوءِ · ١٣","segs":[["matn","ثُمَّ اسْتَوْعِبْ رَأْسَكَ بِالْمَسْحِ، بِأَنْ تَبُلَّ يَدَيْكَ وَتُلْصِقَ رُؤُوسَ أَصَابِعِ يَدِكَ الْيُمْنَى بِالْيُسْرَى، وَتَضَعَهُمَا عَلَى مُقَدَّمَةِ الرَّأْسِ، وَتُمَرِّرَهُمَا إِلَى الْقَفَا، ثُمَّ تُرَدِّدَهُمَا إِلَى الْمُقَدَّمَةِ، فَهَذِهِ مَرَّةٌ، تَفْعَلُ ذَلِكَ ثَلَاثَ مَرَّاتٍ،"]]},{"id":"bi5_14","label":"بَابُ آدَابِ الْوُضُوءِ · ١٤","segs":[["matn","وَكَذَلِكَ فِي سَائِرِ الْأَعْضَاءِ، وَقُلْ: اللَّهُمَّ غَشِّنِي بِرَحْمَتِكَ، وَأَنْزِلْ عَلَيَّ مِنْ بَرَكَاتِكَ، وَأَظِلَّنِي تَحْتَ ظِلِّ عَرْشِكَ يَوْمَ لَا ظِلَّ إِلَّا ظِلُّكَ، اللَّهُمَّ حَرِّمْ شَعْرِي وَبَشَرِي عَلَى النَّارِ."]]},{"id":"bi5_15","label":"بَابُ آدَابِ الْوُضُوءِ · ١٥","segs":[["matn","ثُمَّ امْسَحْ أُذُنَيْكَ ظَاهِرَهُمَا وَبَاطِنَهُمَا بِمَاءٍ جَدِيدٍ، وَأَدْخِلْ مُسَبِّحَتَيْكَ فِي صِمَاخَيْ أُذُنَيْكَ، وَامْسَحْ ظَاهِرَ أُذُنَيْكَ بِبَطْنِ إِبْهَامَيْكَ، وَقُلْ: اللَّهُمَّ اجْعَلْنِي مِنَ الَّذِينَ يَسْتَمِعُونَ الْقَوْلَ فَيَتَّبِعُونَ أَحْسَنَهُ، اللَّهُمَّ أَسْمِعْنِي مُنَادِيَ الْجَنَّةِ فِي الْجَنَّةِ مَعَ الْأَبْرَارِ."]]},{"id":"bi5_16","label":"بَابُ آدَابِ الْوُضُوءِ · ١٦","segs":[["matn","ثُمَّ امْسَحْ رَقَبَتَكَ، وَقُلْ: اللَّهُمَّ فُكَّ رَقَبَتِي مِنَ النَّارِ، وَأَعُوذُ بِكَ مِنَ السَّلَاسِلِ وَالْأَغْلَالِ."]]},{"id":"bi5_17","label":"بَابُ آدَابِ الْوُضُوءِ · ١٧","segs":[["matn","ثُمَّ اغْسِلْ رِجْلَكَ الْيُمْنَى ثُمَّ الْيُسْرَى مَعَ الْكَعْبَيْنِ، وَخَلِّلْ بِخِنْصَرِ الْيُسْرَى أَصَابِعَ رِجْلِكَ الْيُمْنَى مُبْتَدِئًا بِخِنْصَرِهَا، حَتَّى تَخْتِمَ بِخِنْصَرِ الْيُسْرَى، وَتُدْخِلَ الْأَصَابِعَ مِنْ أَسْفَلَ، وَقُلْ:"]]},{"id":"bi5_18","label":"بَابُ آدَابِ الْوُضُوءِ · ١٨","segs":[["matn","اللَّهُمَّ ثَبِّتْ قَدَمِي عَلَى الصِّرَاطِ الْمُسْتَقِيمِ مَعَ أَقْدَامِ عِبَادِكَ الصَّالِحِينَ، وَكَذَلِكَ تَقُولُ عِنْدَ غَسْلِ الْيُسْرَى: اللَّهُمَّ إِنِّي أَعُوذُ بِكَ أَنْ تَزِلَّ قَدَمِي عَلَى الصِّرَاطِ فِي النَّارِ يَوْمَ تَزِلُّ أَقْدَامُ الْمُنَافِقِينَ وَالْمُشْرِكِينَ."]]},{"id":"bi5_19","label":"بَابُ آدَابِ الْوُضُوءِ · ١٩","segs":[["matn","وَارْفَعِ الْمَاءَ إِلَى أَنْصَافِ السَّاقَيْنِ، وَرَاعِ التَّكْرَارَ ثَلَاثًا فِي جَمِيعِ أَفْعَالِكَ."]]},{"id":"bi5_20","label":"بَابُ آدَابِ الْوُضُوءِ · ٢٠","segs":[["matn","فَإِذَا فَرَغْتَ فَارْفَعْ بَصَرَكَ إِلَى السَّمَاءِ، وَقُلْ: أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ وَحْدَهُ لَا شَرِيكَ لَهُ، وَأَشْهَدُ أَنَّ مُحَمَّدًا عَبْدُهُ وَرَسُولُهُ، سُبْحَانَكَ اللَّهُمَّ وَبِحَمْدِكَ،"]]},{"id":"bi5_21","label":"بَابُ آدَابِ الْوُضُوءِ · ٢١","segs":[["matn","أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا أَنْتَ، عَمِلْتُ سُوءًا وَظَلَمْتُ نَفْسِي، أَسْتَغْفِرُكَ وَأَتُوبُ إِلَيْكَ فَاغْفِرْ لِي وَتُبْ عَلَيَّ إِنَّكَ أَنْتَ التَّوَّابُ الرَّحِيمُ، اللَّهُمَّ اجْعَلْنِي مِنَ التَّوَّابِينَ؛"]]},{"id":"bi5_22","label":"بَابُ آدَابِ الْوُضُوءِ · ٢٢","segs":[["matn","وَاجْعَلْنِي مِنَ الْمُتَطَهِّرِينَ، وَاجْعَلْنِي مِنْ عِبَادِكَ الصَّالِحِينَ وَاجْعَلْنِي صَبُورًا، شَكُورًا، وَاجْعَلْنِي أَذْكُرُكَ ذِكْرًا كَثِيرًا، وَأُسَبِّحُكَ بُكْرَةً وَأَصِيلًا."]]},{"id":"bi5_23","label":"بَابُ آدَابِ الْوُضُوءِ · ٢٣","segs":[["matn","فَمَنْ قَرَأَ هَذِهِ الدَّعَوَاتِ فِي وُضُوئِهِ خَرَجَتْ خَطَايَاهُ مِنْ جَمِيعِ أَعْضَائِهِ، وَخُتِمَ عَلَى وُضُوئِهِ بِخَاتَمٍ، وَرُفِعَ لَهُ تَحْتَ الْعَرْشِ، فَلَمْ يَزَلْ يُسَبِّحُ اللَّهَ تَعَالَى وَيُقَدِّسُهُ، وَيُكْتَبُ لَهُ ثَوَابُ ذَلِكَ إِلَى يَوْمِ الْقِيَامَةِ."]]},{"id":"bi5_24","label":"بَابُ آدَابِ الْوُضُوءِ · ٢٤","segs":[["matn","وَاجْتَنِبْ فِي وُضُوئِكَ سَبْعًا: لَا تَنْفُضْ يَدَيْكَ فَتَرُشَّ الْمَاءَ، وَلَا تَلْطِمْ وَجْهَكَ وَلَا رَأْسَكَ بِالْمَاءِ لَطْمًا، وَلَا تَتَكَلَّمْ فِي أَثْنَاءِ الْوُضُوءِ، وَلَا تَزِدْ فِي الْغَسْلِ عَلَى ثَلَاثِ مَرَّاتٍ،"]]},{"id":"bi5_25","label":"بَابُ آدَابِ الْوُضُوءِ · ٢٥","segs":[["matn","وَلَا تُكْثِرْ صَبَّ الْمَاءِ مِنْ غَيْرِ حَاجَةٍ بِمُجَرَّدِ الْوَسْوَسَةِ، فَلِلْمُوَسْوِسِينَ شَيْطَانٌ يَضْحَكُ بِهِمْ يُقَالُ لَهُ «الْوَلَهَانُ» وَلَا تَتَوَضَّأْ بِالْمَاءِ الْمُشَمَّسِ وَلَا مِنَ الْأَوَانِي الصُّفْرِيَّةِ، فَهَذِهِ السَّبْعَةُ مَكْرُوهَةٌ فِي الْوُضُوءِ."]]},{"id":"bi5_26","label":"بَابُ آدَابِ الْوُضُوءِ · ٢٦","segs":[["matn","وَفِي الْخَبَرِ أَنَّ: «مَنْ ذَكَرَ اللَّهَ عِنْدَ وُضُوئِهِ طَهَّرَ اللَّهُ جَسَدَهُ كُلَّهُ، وَمَنْ لَمْ يَذْكُرِ اللَّهَ لَمْ يَطْهُرْ مِنْهُ إِلَّا مَا أَصَابَهُ الْمَاءُ»."]]}],"group":"الْقِسْمُ الْأَوَّلُ فِي الطَّاعَاتِ"},{"id":"bi6","title":"آدَابُ الْغُسْلِ","units":[{"id":"bi6_1","label":"آدَابُ الْغُسْلِ · ١","segs":[["matn","فَإِذَا أَصَابَتْكَ جَنَابَةٌ، مِنِ احْتِلَامٍ أَوْ وِقَاعٍ، فَخُذِ الْإِنَاءَ إِلَى الْمُغْتَسَلِ، وَاغْسِلْ يَدَيْكَ أَوَّلًا ثَلَاثًا، وَأَزِلْ مَا عَلَى بَدَنِكَ مِنْ قَذَرٍ، وَتَوَضَّأْ كَمَا سَبَقَ فِي وُضُوئِكَ لِلصَّلَاةِ مَعَ جَمِيعِ الدَّعَوَاتِ،"]]},{"id":"bi6_2","label":"آدَابُ الْغُسْلِ · ٢","segs":[["matn","وَأَخِّرْ غَسْلَ قَدَمَيْكَ، كَيْلَا يَضِيعَ الْمَاءُ فَإِذَا فَرَغْتَ مِنَ الْوُضُوءِ فَصُبَّ الْمَاءَ عَلَى رَأْسِكَ ثَلَاثًا وَأَنْتَ نَاوٍ رَفْعَ الْحَدَثِ مِنَ الْجَنَابَةِ،"]]},{"id":"bi6_3","label":"آدَابُ الْغُسْلِ · ٣","segs":[["matn","ثُمَّ عَلَى شِقِّكَ الْأَيْمَنِ ثَلَاثًا، ثُمَّ عَلَى الْأَيْسَرِ ثَلَاثًا، وَادْعَكْ مَا أَقْبَلَ مِنْ بَدَنِكَ وَمَا أَدْبَرَ ثَلَاثًا، وَخَلِّلْ شَعْرَ رَأْسِكَ وَلِحْيَتِكَ، وَأَوْصِلِ الْمَاءَ إِلَى مَعَاطِفِ الْبَدَنِ وَمَنَابِتِ الشَّعْرِ مَا خَفَّ مِنْهُ وَمَا كَثُفَ."]]},{"id":"bi6_4","label":"آدَابُ الْغُسْلِ · ٤","segs":[["matn","وَاحْذَرْ أَنْ تَمَسَّ ذَكَرَكَ بَعْدَ الْوُضُوءِ فَإِنْ أَصَابَتْهُ يَدُكَ فَأَعِدِ الْوُضُوءَ."]]},{"id":"bi6_5","label":"آدَابُ الْغُسْلِ · ٥","segs":[["matn","وَالْفَرِيضَةُ مِنْ جُمْلَةِ ذَلِكَ كُلِّهِ: النِّيَّةُ، وَإِزَالَةُ النَّجَاسَةِ، وَاسْتِيعَابُ الْبَدَنِ بِالْغَسْلِ."]]},{"id":"bi6_6","label":"آدَابُ الْغُسْلِ · ٦","segs":[["matn","وَفَرْضُ الْوُضُوءِ: غَسْلُ الْوَجْهِ وَالْيَدَيْنِ مَعَ الْمِرْفَقَيْنِ، وَمَسْحُ بَعْضِ الرَّأْسِ، وَغَسْلُ الرِّجْلَيْنِ إِلَى الْكَعْبَيْنِ مَرَّةً، مَعَ النِّيَّةِ وَالتَّرْتِيبِ."]]},{"id":"bi6_7","label":"آدَابُ الْغُسْلِ · ٧","segs":[["matn","وَمَا عَدَاهَا سُنَنٌ مُؤَكَّدَةٌ فَضْلُهَا كَثِيرٌ، وَثَوَابُهَا جَزِيلٌ وَالْمُتَهَاوِنُ بِهَا خَاسِرٌ، بَلْ هُوَ بِأَصْلِ فَرَائِضِهِ مُخَاطِرٌ، فَإِنَّ النَّوَافِلَ جَوَابِرُ لِلْفَرَائِضِ."]]}],"group":"الْقِسْمُ الْأَوَّلُ فِي الطَّاعَاتِ"},{"id":"bi7","title":"آدَابُ التَّيَمُّمِ","units":[{"id":"bi7_1","label":"آدَابُ التَّيَمُّمِ · ١","segs":[["matn","فَإِنْ عَجَزْتَ عَنِ اسْتِعْمَالِ الْمَاءِ لِفَقْدِهِ بَعْدَ الطَّلَبِ، أَوْ لِعُذْرٍ مِنْ مَرَضٍ، أَوْ لِمَانِعٍ مِنَ الْوُصُولِ إِلَيْهِ مِنْ سَبُعٍ أَوْ حَبْسٍ، أَوْ كَانَ الْمَاءُ الْحَاضِرُ تَحْتَاجُ إِلَيْهِ لِعَطَشِكَ أَوْ لِعَطَشِ رَفِيقِكَ،"]]},{"id":"bi7_2","label":"آدَابُ التَّيَمُّمِ · ٢","segs":[["matn","أَوْ كَانَ مِلْكًا لِغَيْرِكَ وَلَمْ يُبَعْ إِلَّا بِأَكْثَرَ مِنْ ثَمَنِ الْمِثْلِ، أَوْ كَانَ بِكَ جِرَاحَةٌ أَوْ مَرَضٌ تَخَافُ مِنْهُ عَلَى نَفْسِكَ - فَاصْبِرْ حَتَّى يَدْخُلَ وَقْتُ الْفَرِيضَةِ، ثُمَّ اقْصِدْ صَعِيدًا طَيِّبًا عَلَيْهِ تُرَابٌ خَالِصٌ طَاهِرٌ لَيِّنٌ،"]]},{"id":"bi7_3","label":"آدَابُ التَّيَمُّمِ · ٣","segs":[["matn","فَاضْرِبْ عَلَيْهِ بِكَفَّيْكَ ضَامًّا بَيْنَ أَصَابِعِكَ، وَانْوِ اسْتِبَاحَةَ فَرْضِ الصَّلَاةِ، وَامْسَحْ بِهِمَا وَجْهَكَ كُلَّهُ مَرَّةً، وَلَا تَتَكَلَّفْ إِيصَالَ الْغُبَارِ إِلَى مَنَابِتِ الشَّعْرِ خَفَّ أَوْ كَثُفَ، ثُمَّ انْزِعْ خَاتَمَكَ،"]]},{"id":"bi7_4","label":"آدَابُ التَّيَمُّمِ · ٤","segs":[["matn","وَاضْرِبْ ضَرْبَةً ثَانِيَةً مُفَرِّجًا مَا بَيْنَ أَصَابِعِكَ، وَامْسَحْ بِهِمَا يَدَيْكَ مَعَ مِرْفَقَيْكَ، فَإِنْ لَمْ تَسْتَوْعِبْهُمَا فَاضْرِبْ ضَرْبَةً أُخْرَى إِلَى أَنْ تَسْتَوْعِبَهُمَا، ثُمَّ امْسَحْ إِحْدَى كَفَّيْكَ بِالْأُخْرَى، وَامْسَحْ مَا بَيْنَ أَصَابِعِكَ بِالتَّخْلِيلِ."]]},{"id":"bi7_5","label":"آدَابُ التَّيَمُّمِ · ٥","segs":[["matn","وَصَلِّ بِهِ فَرْضًا وَاحِدًا وَمَا شِئْتَ مِنَ النَّوَافِلِ، فَإِنْ أَرَدْتَ فَرْضًا ثَانِيًا فَاسْتَأْنِفْ تَيَمُّمًا آخَرَ."]]}],"group":"الْقِسْمُ الْأَوَّلُ فِي الطَّاعَاتِ"},{"id":"bi8","title":"آدَابُ الْخُرُوجِ إِلَى الْمَسْجِدِ","units":[{"id":"bi8_1","label":"آدَابُ الْخُرُوجِ إِلَى الْمَسْجِدِ · ١","segs":[["matn","فَإِذَا فَرَغْتَ مِنْ طَهَارَتِكَ فَصَلِّ فِي بَيْتِكَ رَكْعَتَيِ الصُّبْحِ إِنْ كَانَ الْفَجْرُ قَدْ طَلَعَ، كَذَلِكَ كَانَ يَفْعَلُ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ثُمَّ يَتَوَجَّهُ إِلَى الْمَسْجِدِ."]]},{"id":"bi8_2","label":"آدَابُ الْخُرُوجِ إِلَى الْمَسْجِدِ · ٢","segs":[["matn","وَلَا تَدَعِ الصَّلَاةَ فِي الْجَمَاعَةِ، لَا سِيَّمَا الصُّبْحُ «فَصَلَاةُ الْجَمَاعَةِ تَفْضُلُ عَلَى الْفَرْدِ بِسَبْعٍ وَعِشْرِينَ دَرَجَةً» فَإِنْ كُنْتَ تَتَسَاهَلُ فِي مِثْلِ هَذَا الرِّبْحِ فَأَيُّ فَائِدَةٍ لَكَ فِي طَلَبِ الْعِلْمِ؟"]]},{"id":"bi8_3","label":"آدَابُ الْخُرُوجِ إِلَى الْمَسْجِدِ · ٣","segs":[["matn","وَإِنَّمَا ثَمَرَةُ الْعِلْمِ الْعَمَلُ بِهِ. فَإِذَا سَعَيْتَ إِلَى الْمَسْجِدِ، فَامْشِ عَلَى هِينَةٍ وَتُؤَدَةٍ وَسَكِينَةٍ، وَلَا تَعْجَلْ وَقُلْ فِي طَرِيقِكَ: اللَّهُمَّ إِنِّي أَسْأَلُكَ بِحَقِّ السَّائِلِينَ عَلَيْكَ، وَبِحَقِّ الرَّاغِبِينَ إِلَيْكَ، وَبِحَقِّ مَمْشَايَ هَذَا إِلَيْكَ؛"]]},{"id":"bi8_4","label":"آدَابُ الْخُرُوجِ إِلَى الْمَسْجِدِ · ٤","segs":[["matn","فَإِنِّي لَمْ أَخْرُجْ أَشَرًا وَلَا بَطَرًا، وَلَا رِيَاءً، وَلَا سُمْعَةً، بَلْ خَرَجْتُ اتِّقَاءَ سَخَطِكَ، وَابْتِغَاءَ مَرْضَاتِكَ فَأَسْأَلُكَ أَنْ تُنْقِذَنِي مِنَ النَّارِ، وَأَنْ تَغْفِرَ لِي ذُنُوبِي؛ فَإِنَّهُ لَا يَغْفِرُ الذُّنُوبَ إِلَّا أَنْتَ."]]}],"group":"الْقِسْمُ الْأَوَّلُ فِي الطَّاعَاتِ"},{"id":"bi9","title":"آدَابُ دُخُولِ الْمَسْجِدِ","units":[{"id":"bi9_1","label":"آدَابُ دُخُولِ الْمَسْجِدِ · ١","segs":[["matn","فَإِذَا أَرَدْتَ الدُّخُولَ إِلَى الْمَسْجِدِ، فَقَدِّمْ رِجْلَكَ الْيُمْنَى، وَقُلْ: اللَّهُمَّ صَلِّ عَلَى مُحَمَّدٍ وَعَلَى آلِ مُحَمَّدٍ وَصَحْبِهِ وَسَلِّمْ؛"]]},{"id":"bi9_2","label":"آدَابُ دُخُولِ الْمَسْجِدِ · ٢","segs":[["matn","اللَّهُمَّ اغْفِرْ لِي ذُنُوبِي وَافْتَحْ لِي أَبْوَابَ رَحْمَتِكَ."]]},{"id":"bi9_3","label":"آدَابُ دُخُولِ الْمَسْجِدِ · ٣","segs":[["matn","وَمَهْمَا رَأَيْتَ فِي الْمَسْجِدِ مَنْ يَبِيعُ أَوْ يَبْتَاعُ، فَقُلْ: لَا أَرْبَحَ اللَّهُ تِجَارَتَكَ."]]},{"id":"bi9_4","label":"آدَابُ دُخُولِ الْمَسْجِدِ · ٤","segs":[["matn","وَإِذَا رَأَيْتَ فِيهِ مَنْ يَنْشُدُ ضَالَّةً، فَقُلْ: لَا رَدَّ اللَّهُ عَلَيْكَ ضَالَّتَكَ - كَذَلِكَ أَمَرَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ."]]},{"id":"bi9_5","label":"آدَابُ دُخُولِ الْمَسْجِدِ · ٥","segs":[["matn","فَإِذَا دَخَلْتَ الْمَسْجِدَ، فَلَا تَجْلِسْ حَتَّى تُصَلِّيَ رَكْعَتَيِ التَّحِيَّةِ، فَإِنْ لَمْ تَكُنْ عَلَى طَهَارَةٍ أَوْ لَمْ تُرِدْ فِعْلَهَا كَفَتْكَ الْبَاقِيَاتُ الصَّالِحَاتُ ثَلَاثًا، وَقِيلَ أَرْبَعًا، وَقِيلَ ثَلَاثًا لِلْمُحْدِثِ وَوَاحِدَةً لِلْمُتَوَضِّئِ."]]},{"id":"bi9_6","label":"آدَابُ دُخُولِ الْمَسْجِدِ · ٦","segs":[["matn","فَإِنْ لَمْ تَكُنْ صَلَّيْتَ فِي بَيْتِكَ رَكْعَتَيِ الْفَجْرِ، فَيُجْزِئُكَ أَدَاؤُهُمَا عَنِ التَّحِيَّةِ."]]},{"id":"bi9_7","label":"آدَابُ دُخُولِ الْمَسْجِدِ · ٧","segs":[["matn","فَإِذَا فَرَغْتَ مِنَ الرَّكْعَتَيْنِ، فَانْوِ الِاعْتِكَافَ وَادْعُ بِمَا دَعَا بِهِ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بَعْدَ رَكْعَتَيِ الْفَجْرِ، فَقُلْ: «اللَّهُمَّ إِنِّي أَسْأَلُكَ رَحْمَةً مِنْ عِنْدِكَ،"]]},{"id":"bi9_8","label":"آدَابُ دُخُولِ الْمَسْجِدِ · ٨","segs":[["matn","تَهْدِي بِهَا قَلْبِي، وَتَجْمَعُ بِهَا شَمْلِي، وَتَلُمُّ بِهَا شَعَثِي، وَتَرُدُّ بِهَا أُلْفَتِي وَتُصْلِحُ بِهَا دِينِي وَتَحْفَظُ بِهَا غَائِبِي، وَتَرْفَعُ بِهَا شَاهِدِي، وَتُزَكِّي بِهَا عَمَلِي،"]]},{"id":"bi9_9","label":"آدَابُ دُخُولِ الْمَسْجِدِ · ٩","segs":[["matn","وَتُبَيِّضُ بِهَا وَجْهِي، وَتُلْهِمُنِي بِهَا رُشْدِي، وَتَقْضِي لِي بِهَا حَاجَتِي، وَتَعْصِمُنِي بِهَا مِنْ كُلِّ سُوءٍ، اللَّهُمَّ إِنِّي أَسْأَلُكَ إِيمَانًا خَالِصًا دَائِمًا يُبَاشِرُ قَلْبِي، وَيَقِينًا صَادِقًا،"]]},{"id":"bi9_10","label":"آدَابُ دُخُولِ الْمَسْجِدِ · ١٠","segs":[["matn","حَتَّى أَعْلَمَ أَنَّهُ لَنْ يُصِيبَنِي إِلَّا مَا كَتَبْتَهُ عَلَيَّ، وَرَضِّنِي بِمَا قَسَمْتَهُ لِي، اللَّهُمَّ إِنِّي أَسْأَلُكَ إِيمَانًا صَادِقًا، وَيَقِينًا لَيْسَ بَعْدَهُ كُفْرٌ؛"]]},{"id":"bi9_11","label":"آدَابُ دُخُولِ الْمَسْجِدِ · ١١","segs":[["matn","وَأَسْأَلُكَ رَحْمَةً أَنَالُ بِهَا شَرَفَ كَرَامَتِكَ فِي الدُّنْيَا وَالْآخِرَةِ؛"]]},{"id":"bi9_12","label":"آدَابُ دُخُولِ الْمَسْجِدِ · ١٢","segs":[["matn","اللَّهُمَّ إِنِّي أَسْأَلُكَ الْفَوْزَ عِنْدَ اللِّقَاءِ وَالصَّبْرَ عِنْدَ الْقَضَاءِ، وَمَنَازِلَ الشُّهَدَاءِ وَعَيْشَ السُّعَدَاءِ وَالنَّصْرَ عَلَى الْأَعْدَاءِ، وَمُرَافَقَةَ الْأَنْبِيَاءِ؛"]]},{"id":"bi9_13","label":"آدَابُ دُخُولِ الْمَسْجِدِ · ١٣","segs":[["matn","اللَّهُمَّ إِنِّي أُنْزِلُ بِكَ حَاجَتِي، وَإِنْ ضَعُفَ رَأْيِي وَقَصُرَ عَمَلِي، وَافْتَقَرْتُ إِلَى رَحْمَتِكَ فَأَسْأَلُكَ يَا قَاضِيَ الْأُمُورِ وَيَا شَافِيَ الصُّدُورِ، كَمَا تُجِيرُ بَيْنَ الْبُحُورِ أَنْ تُجِيرَنِي مِنْ عَذَابِ السَّعِيرِ، وَمِنْ دَعْوَةِ الثُّبُورِ وَمِنْ فِتْنَةِ الْقُبُورِ؛"]]},{"id":"bi9_14","label":"آدَابُ دُخُولِ الْمَسْجِدِ · ١٤","segs":[["matn","اللَّهُمَّ مَا قَصُرَ عَنْهُ رَأْيِي، وَضَعُفَ عَنْهُ عَمَلِي، وَلَمْ تَبْلُغْهُ نِيَّتِي وَأُمْنِيَّتِي، مِنْ خَيْرٍ وَعَدْتَهُ أَحَدًا مِنْ عِبَادِكَ أَوْ خَيْرٍ أَنْتَ مُعْطِيهِ أَحَدًا مِنْ خَلْقِكَ فَإِنِّي أَرْغَبُ إِلَيْكَ فِيهِ، وَأَسْأَلُكَ إِيَّاهُ يَا رَبَّ الْعَالَمِينَ؛"]]},{"id":"bi9_15","label":"آدَابُ دُخُولِ الْمَسْجِدِ · ١٥","segs":[["matn","اللَّهُمَّ اجْعَلْنَا هَادِينَ مُهْتَدِينَ، غَيْرَ ضَالِّينَ وَلَا مُضِلِّينَ؛"]]},{"id":"bi9_16","label":"آدَابُ دُخُولِ الْمَسْجِدِ · ١٦","segs":[["matn","حَرْبًا لِأَعْدَائِكَ سِلْمًا لِأَوْلِيَائِكَ نُحِبُّ بِحُبِّكَ النَّاسَ، وَنُعَادِي بِعَدَاوَتِكَ مَنْ خَالَفَكَ مِنْ خَلْقِكَ؛"]]},{"id":"bi9_17","label":"آدَابُ دُخُولِ الْمَسْجِدِ · ١٧","segs":[["matn","اللَّهُمَّ هَذَا الدُّعَاءُ وَعَلَيْكَ الْإِجَابَةُ وَهَذَا الْجُهْدُ وَعَلَيْكَ التُّكْلَانُ، وَإِنَّا لِلَّهِ وَإِنَّا إِلَيْهِ رَاجِعُونَ وَلَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللَّهِ الْعَلِيِّ الْعَظِيمِ؛"]]},{"id":"bi9_18","label":"آدَابُ دُخُولِ الْمَسْجِدِ · ١٨","segs":[["matn","اللَّهُمَّ ذَا الْحَبْلِ الشَّدِيدِ، وَالْأَمْرِ الرَّشِيدِ، أَسْأَلُكَ الْأَمْنَ يَوْمَ الْوَعِيدِ، وَالْجَنَّةَ يَوْمَ الْخُلُودِ مَعَ الْمُقَرَّبِينَ الشُّهُودِ، الرُّكَّعِ السُّجُودِ، الْمُوفِينَ لَكَ بِالْعُهُودِ؛"]]},{"id":"bi9_19","label":"آدَابُ دُخُولِ الْمَسْجِدِ · ١٩","segs":[["matn","إِنَّكَ رَحِيمٌ وَدُودٌ وَإِنَّكَ تَفْعَلُ مَا تُرِيدُ سُبْحَانَ مَنْ تَعَطَّفَ بِالْعِزِّ وَقَالَ بِهِ، سُبْحَانَ مَنْ لَبِسَ الْمَجْدَ وَتَكَرَّمَ بِهِ، سُبْحَانَ مَنْ لَا يَنْبَغِي التَّسْبِيحُ إِلَّا لَهُ، سُبْحَانَ ذِي الْفَضْلِ وَالنِّعَمِ، سُبْحَانَ ذِي الْجُودِ وَالْكَرَمِ، سُبْحَانَ الَّذِي أَحْصَى كُلَّ شَيْءٍ بِعِلْمِهِ؛"]]},{"id":"bi9_20","label":"آدَابُ دُخُولِ الْمَسْجِدِ · ٢٠","segs":[["matn","اللَّهُمَّ اجْعَلْ لِي نُورًا فِي قَلْبِي، وَنُورًا فِي قَبْرِي، وَنُورًا فِي سَمْعِي وَنُورًا فِي بَصَرِي وَنُورًا فِي شَعْرِي، وَنُورًا فِي بَشَرِي، وَنُورًا فِي لَحْمِي،"]]},{"id":"bi9_21","label":"آدَابُ دُخُولِ الْمَسْجِدِ · ٢١","segs":[["matn","وَنُورًا فِي دَمِي، وَنُورًا فِي عِظَامِي، وَنُورًا مِنْ بَيْنِ يَدَيَّ، وَنُورًا مِنْ خَلْفِي وَنُورًا مِنْ يَمِينٍ وَنُورًا عَنْ شِمَالِي وَنُورًا مِنْ فَوْقِي وَنُورًا مِنْ تَحْتِي؛"]]},{"id":"bi9_22","label":"آدَابُ دُخُولِ الْمَسْجِدِ · ٢٢","segs":[["matn","اللَّهُمَّ زِدْنِي نُورًا، وَأَعْطِنِي نُورًا أَعْظَمَ نُورٍ، وَاجْعَلْ لِي نُورًا بِرَحْمَتِكَ يَا أَرْحَمَ الرَّاحِمِينَ."]]},{"id":"bi9_23","label":"آدَابُ دُخُولِ الْمَسْجِدِ · ٢٣","segs":[["matn","فَإِذَا فَرَغْتَ مِنَ الدُّعَاءِ، فَلَا تَشْتَغِلْ إِلَى وَقْتِ الْفَرْضِ إِلَّا بِذِكْرٍ أَوْ تَسْبِيحٍ أَوْ قِرَاءَةِ قُرْآنٍ."]]},{"id":"bi9_24","label":"آدَابُ دُخُولِ الْمَسْجِدِ · ٢٤","segs":[["matn","فَإِذَا سَمِعْتَ الْأَذَانَ فِي أَثْنَاءِ ذَلِكَ فَاقْطَعْ مَا أَنْتَ فِيهِ وَاشْتَغِلْ بِجَوَابِ الْمُؤَذِّنِ."]]},{"id":"bi9_25","label":"آدَابُ دُخُولِ الْمَسْجِدِ · ٢٥","segs":[["matn","فَإِذَا قَالَ الْمُؤَذِّنُ: اللَّهُ أَكْبَرُ، اللَّهُ أَكْبَرُ، فَقُلْ مِثْلَ ذَلِكَ، وَكَذَلِكَ فِي كُلِّ كَلِمَةٍ إِلَّا فِي الْحَيْعَلَتَيْنِ فَقُلْ فِيهِمَا: لَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللَّهِ الْعَلِيِّ الْعَظِيمِ."]]},{"id":"bi9_26","label":"آدَابُ دُخُولِ الْمَسْجِدِ · ٢٦","segs":[["matn","فَإِذَا قَالَ: الصَّلَاةُ خَيْرٌ مِنَ النَّوْمِ، فَقُلْ: صَدَقْتَ وَبَرَرْتَ وَأَنَا عَلَى ذَلِكَ مِنَ الشَّاهِدِينَ."]]},{"id":"bi9_27","label":"آدَابُ دُخُولِ الْمَسْجِدِ · ٢٧","segs":[["matn","فَإِذَا سَمِعْتَ الْإِقَامَةَ فَقُلْ مِثْلَ مَا يَقُولُ، إِلَّا فِي قَوْلِهِ: قَدْ قَامَتِ الصَّلَاةُ، فَقُلْ: أَقَامَهَا اللَّهُ وَأَدَامَهَا مَا دَامَتِ السَّمَوَاتُ وَالْأَرْضُ."]]},{"id":"bi9_28","label":"آدَابُ دُخُولِ الْمَسْجِدِ · ٢٨","segs":[["matn","فَإِذَا فَرَغْتَ مِنْ جَوَابِ الْمُؤَذِّنِ فَقُلْ: اللَّهُمَّ إِنِّي أَسْأَلُكَ عِنْدَ حُضُورِ صَلَاتِكَ وَأَصْوَاتِ دُعَاتِكَ، وَإِدْبَارِ لَيْلِكَ، وَإِقْبَالِ نَهَارِكَ: أَنْ تُؤْتِيَ مُحَمَّدًا الْوَسِيلَةَ وَالْفَضِيلَةَ وَالدَّرَجَةَ الرَّفِيعَةَ وَابْعَثْهُ الْمَقَامَ الْمَحْمُودَ الَّذِي وَعَدْتَهُ إِنَّكَ لَا تُخْلِفُ الْمِيعَادَ يَا أَرْحَمَ الرَّاحِمِينَ."]]},{"id":"bi9_29","label":"آدَابُ دُخُولِ الْمَسْجِدِ · ٢٩","segs":[["matn","فَإِذَا سَمِعْتَ الْأَذَانَ وَأَنْتَ فِي الصَّلَاةِ فَتَمِّمِ الصَّلَاةَ، ثُمَّ تَدَارَكِ الْجَوَابَ بَعْدَ السَّلَامِ عَلَى وَجْهِهِ."]]},{"id":"bi9_30","label":"آدَابُ دُخُولِ الْمَسْجِدِ · ٣٠","segs":[["matn","فَإِذَا أَحْرَمَ الْإِمَامُ بِالْفَرْضِ، فَلَا تَشْتَغِلْ إِلَّا بِالِاقْتِدَاءِ بِهِ وَصَلِّ الْفَرْضَ كَمَا سَيُتْلَى عَلَيْكَ فِي كَيْفِيَّةِ الصَّلَاةِ وَآدَابِهَا فَإِذَا فَرَغْتَ فَقُلْ: اللَّهُمَّ صَلِّ عَلَى مُحَمَّدٍ وَعَلَى آلِ مُحَمَّدٍ وَسَلِّمْ، اللَّهُمَّ أَنْتَ السَّلَامُ، وَمِنْكَ السَّلَامُ، وَإِلَيْكَ يَعُودُ السَّلَامُ، فَحَيِّنَا رَبَّنَا بِالسَّلَامِ، وَأَدْخِلْنَا الْجَنَّةَ دَارَ السَّلَامِ؛"]]},{"id":"bi9_31","label":"آدَابُ دُخُولِ الْمَسْجِدِ · ٣١","segs":[["matn","تَبَارَكْتَ يَا ذَا الْجَلَالِ وَالْإِكْرَامِ؛ سُبْحَانَ رَبِّيَ الْعَلِيِّ الْأَعْلَى الْوَهَّابِ، لَا إِلَهَ إِلَّا اللَّهُ وَحْدَهُ لَا شَرِيكَ لَهُ، لَهُ الْمُلْكُ، وَلَهُ الْحَمْدُ، يُحْيِي وَيُمِيتُ، وَهُوَ حَيٌّ لَا يَمُوتُ، بِيَدِهِ الْخَيْرُ،"]]},{"id":"bi9_32","label":"آدَابُ دُخُولِ الْمَسْجِدِ · ٣٢","segs":[["matn","وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ، لَا إِلَهَ إِلَّا اللَّهُ، أَهْلَ النِّعْمَةِ وَالْفَضْلِ وَالثَّنَاءِ الْحَسَنِ، لَا إِلَهَ إِلَّا اللَّهُ، وَلَا نَعْبُدُ إِلَّا إِيَّاهُ مُخْلِصِينَ لَهُ الدِّينَ وَلَوْ كَرِهَ الْكَافِرُونَ."]]},{"id":"bi9_33","label":"آدَابُ دُخُولِ الْمَسْجِدِ · ٣٣","segs":[["matn","ثُمَّ ادْعُ بَعْدَ ذَلِكَ بِالْجَوَامِعِ الْكَوَامِلِ، وَهُوَ مَا عَلَّمَهُ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ - عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا، فَقُلْ: «اللَّهُمَّ إِنِّي أَسْأَلُكَ مِنَ الْخَيْرِ كُلِّهِ عَاجِلِهِ وَآجِلِهِ مَا عَلِمْتُ مِنْهُ وَمَا لَمْ أَعْلَمْ،"]]},{"id":"bi9_34","label":"آدَابُ دُخُولِ الْمَسْجِدِ · ٣٤","segs":[["matn","وَأَعُوذُ بِكَ مِنَ الشَّرِّ كُلِّهِ عَاجِلِهِ وَآجِلِهِ مَا عَلِمْتُ مِنْهُ وَمَا لَمْ أَعْلَمْ، وَأَسْأَلُكَ الْجَنَّةَ وَمَا يُقَرِّبُ إِلَيْهَا مِنْ قَوْلٍ وَعَمَلٍ وَنِيَّةٍ وَاعْتِقَادٍ،"]]},{"id":"bi9_35","label":"آدَابُ دُخُولِ الْمَسْجِدِ · ٣٥","segs":[["matn","وَأَعُوذُ بِكَ مِنَ النَّارِ وَمَا يُقَرِّبُ إِلَيْهَا مِنْ قَوْلٍ وَعَمَلٍ وَنِيَّةٍ وَاعْتِقَادٍ، وَأَسْأَلُكَ مِنْ خَيْرِ مَا سَأَلَكَ مِنْهُ عَبْدُكَ وَنَبِيُّكَ مُحَمَّدٌ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ،"]]},{"id":"bi9_36","label":"آدَابُ دُخُولِ الْمَسْجِدِ · ٣٦","segs":[["matn","وَأَعُوذُ بِكَ مِنْ شَرِّ مَا اسْتَعَاذَكَ مِنْهُ عَبْدُكَ وَنَبِيُّكَ مُحَمَّدٌ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، وَمَا قَضَيْتَ عَلَيَّ مِنْ أَمْرٍ فَاجْعَلْ عَاقِبَتَهُ رَشَدًا»."]]},{"id":"bi9_37","label":"آدَابُ دُخُولِ الْمَسْجِدِ · ٣٧","segs":[["matn","ثُمَّ ادْعُ بِمَا أَوْصَى بِهِ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَاطِمَةَ رَضِيَ اللَّهُ عَنْهَا، فَقُلْ: «يَا حَيُّ يَا قَيُّومُ، يَا ذَا الْجَلَالِ وَالْإِكْرَامِ،"]]},{"id":"bi9_38","label":"آدَابُ دُخُولِ الْمَسْجِدِ · ٣٨","segs":[["matn","لَا إِلَهَ إِلَّا أَنْتَ بِرَحْمَتِكَ أَسْتَغِيثُ، وَمِنْ عَذَابِكَ أَسْتَجِيرُ، لَا تَكِلْنِي إِلَى نَفْسِي، وَلَا إِلَى أَحَدٍ مِنْ خَلْقِكَ طَرْفَةَ عَيْنٍ، وَأَصْلِحْ لِي شَأْنِي كُلَّهُ بِمَا أَصْلَحْتَ بِهِ الصَّالِحِينَ»."]]},{"id":"bi9_39","label":"آدَابُ دُخُولِ الْمَسْجِدِ · ٣٩","segs":[["matn","ثُمَّ قُلْ مَا قَالَهُ عِيسَى عَلَى نَبِيِّنَا وَعَلَيْهِ الصَّلَاةُ وَالسَّلَامُ."]]},{"id":"bi9_40","label":"آدَابُ دُخُولِ الْمَسْجِدِ · ٤٠","segs":[["matn","اللَّهُمَّ إِنِّي أَصْبَحْتُ لَا أَسْتَطِيعُ دَفْعَ مَا أَكْرَهُ، وَلَا أَمْلِكُ نَفْعَ مَا أَرْجُو، وَأَصْبَحَ الْأَمْرُ بِيَدِكَ لَا بِيَدِ غَيْرِكَ، وَأَصْبَحْتُ مُرْتَهَنًا بِعَمَلِي؛"]]},{"id":"bi9_41","label":"آدَابُ دُخُولِ الْمَسْجِدِ · ٤١","segs":[["matn","فَلَا فَقِيرَ أَفْقَرُ مِنِّي إِلَيْكَ، وَلَا غَنِيَّ أَغْنَى مِنْكَ عَنِّي، اللَّهُمَّ لَا تُشْمِتْ بِي عَدُوِّي، وَلَا تَسُؤْ بِي صَدِيقِي، وَلَا تَجْعَلْ مُصِيبَتِي فِي دِينِي، وَلَا تَجْعَلِ الدُّنْيَا أَكْبَرَ هَمِّي وَلَا مَبْلَغَ عِلْمِي، وَلَا تُسَلِّطْ عَلَيَّ بِذَنْبِي مَنْ لَا يَرْحَمُنِي."]]},{"id":"bi9_42","label":"آدَابُ دُخُولِ الْمَسْجِدِ · ٤٢","segs":[["matn","ثُمَّ ادْعُ بِمَا بَدَا لَكَ مِنَ الدَّعَوَاتِ الْمَشْهُورَاتِ، وَاحْفَظْهَا مِمَّا أَوْرَدْنَا فِي كِتَابِ الدَّعَوَاتِ مِنْ كِتَابِ «إِحْيَاءِ عُلُومِ الدِّينِ»."]]},{"id":"bi9_43","label":"آدَابُ دُخُولِ الْمَسْجِدِ · ٤٣","segs":[["matn","وَلْتَكُنْ أَوْقَاتُكَ بَعْدَ الصَّلَاةِ إِلَى طُلُوعِ الشَّمْسِ، مُوَزَّعَةً عَلَى أَرْبَعِ وَظَائِفَ: وَظِيفَةٍ فِي الدَّعَوَاتِ، وَوَظِيفَةٍ فِي الْأَذْكَارِ وَالدَّعَوَاتِ؛"]]},{"id":"bi9_44","label":"آدَابُ دُخُولِ الْمَسْجِدِ · ٤٤","segs":[["matn","وَتُكَرِّرُهَا فِي مِسْبَحَةٍ، وَوَظِيفَةٍ فِي قِرَاءَةِ الْقُرْآنِ، وَوَظِيفَةٍ فِي التَّفَكُّرِ، فَتَفَكَّرْ فِي ذُنُوبِكَ وَخَطَايَاكَ وَتَقْصِيرِكَ فِي عِبَادَةِ مَوْلَاكَ، وَتَعَرُّضِكَ لِعِقَابِهِ الْأَلِيمِ وَسَخَطِهِ الْعَظِيمِ."]]},{"id":"bi9_45","label":"آدَابُ دُخُولِ الْمَسْجِدِ · ٤٥","segs":[["matn","وَتُرَتِّبُ بِتَدْبِيرِكَ أَوْرَادَكَ فِي جَمِيعِ يَوْمِكَ لِتَتَدَارَكَ بِهِ مَا فَرَطَ مِنْ تَقْصِيرِكَ، وَتَحْتَرِزَ مِنَ التَّعَرُّضِ لِسَخَطِ اللَّهِ تَعَالَى الْأَلِيمِ فِي يَوْمِكَ،"]]},{"id":"bi9_46","label":"آدَابُ دُخُولِ الْمَسْجِدِ · ٤٦","segs":[["matn","وَتَنْوِي الْخَيْرَ لِجَمِيعِ الْمُسْلِمِينَ وَتَعْزِمُ أَنْ لَا تَشْتَغِلَ فِي جَمِيعِ نَهَارِكَ إِلَّا بِطَاعَةِ اللَّهِ تَعَالَى، وَتَقْصِدُ فِي قَلْبِكَ الطَّاعَاتِ الَّتِي تَقْدِرُ عَلَيْهَا وَتَخْتَارُ أَفْضَلَهَا، وَتَتَأَمَّلُ تَهْيِئَةَ أَسْبَابِهَا لِتَشْتَغِلَ بِهَا؛"]]},{"id":"bi9_47","label":"آدَابُ دُخُولِ الْمَسْجِدِ · ٤٧","segs":[["matn","وَلَا تَدَعْ عَنْكَ التَّفَكُّرَ فِي قُرْبِ الْأَجَلِ، وَحُلُولِ الْمَوْتِ الْقَاطِعِ لِلْأَمَلِ، وَخُرُوجِ الْأَمْرِ عَنِ الِاخْتِيَارِ، وَحُصُولِ الْحَسْرَةِ وَالنَّدَامَةِ بِطُولِ الِاغْتِرَارِ."]]},{"id":"bi9_48","label":"آدَابُ دُخُولِ الْمَسْجِدِ · ٤٨","segs":[["matn","وَلْيَكُنْ مِنْ تَسَابِيحِكَ، وَأَذْكَارِكَ عَشْرُ كَلِمَاتٍ: إِحْدَاهُنَّ: لَا إِلَهَ إِلَّا اللَّهُ، وَحْدَهُ لَا شَرِيكَ لَهُ، لَهُ الْمُلْكُ، وَلَهُ الْحَمْدُ، يُحْيِي وَيُمِيتُ، وَهُوَ حَيٌّ لَا يَمُوتُ، بِيَدِهِ الْخَيْرُ، وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ."]]},{"id":"bi9_49","label":"آدَابُ دُخُولِ الْمَسْجِدِ · ٤٩","segs":[["matn","الثَّانِيَةُ: لَا إِلَهَ إِلَّا اللَّهُ الْمَلِكُ الْحَقُّ الْمُبِينُ."]]},{"id":"bi9_50","label":"آدَابُ دُخُولِ الْمَسْجِدِ · ٥٠","segs":[["matn","الثَّالِثَةُ: لَا إِلَهَ إِلَّا اللَّهُ الْوَاحِدُ الْقَهَّارُ، رَبُّ السَّمَوَاتِ وَالْأَرْضِ وَمَا بَيْنَهُمَا الْعَزِيزُ الْغَفَّارُ."]]},{"id":"bi9_51","label":"آدَابُ دُخُولِ الْمَسْجِدِ · ٥١","segs":[["matn","الرَّابِعَةُ: سُبْحَانَ اللَّهِ، وَالْحَمْدُ لِلَّهِ، وَلَا إِلَهَ إِلَّا اللَّهُ، وَاللَّهُ أَكْبَرُ، وَلَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللَّهِ الْعَلِيِّ الْعَظِيمِ."]]},{"id":"bi9_52","label":"آدَابُ دُخُولِ الْمَسْجِدِ · ٥٢","segs":[["matn","الْخَامِسَةُ: سُبُّوحٌ قُدُّوسٌ رَبُّ الْمَلَائِكَةِ وَالرُّوحِ. السَّادِسَةُ: سُبْحَانَ اللَّهِ وَبِحَمْدِهِ، سُبْحَانَ اللَّهِ الْعَظِيمِ."]]},{"id":"bi9_53","label":"آدَابُ دُخُولِ الْمَسْجِدِ · ٥٣","segs":[["matn","السَّابِعَةُ: أَسْتَغْفِرُ اللَّهَ الْعَظِيمَ الَّذِي لَا إِلَهَ إِلَّا هُوَ الْحَيُّ الْقَيُّومُ، وَأَسْأَلُهُ التَّوْبَةَ وَالْمَغْفِرَةَ."]]},{"id":"bi9_54","label":"آدَابُ دُخُولِ الْمَسْجِدِ · ٥٤","segs":[["matn","الثَّامِنَةُ: اللَّهُمَّ لَا مَانِعَ لِمَا أَعْطَيْتَ وَلَا مُعْطِيَ لِمَا مَنَعْتَ، وَلَا رَادَّ لِمَا قَضَيْتَ وَلَا يَنْفَعُ ذَا الْجَدِّ مِنْكَ الْجَدُّ."]]},{"id":"bi9_55","label":"آدَابُ دُخُولِ الْمَسْجِدِ · ٥٥","segs":[["matn","التَّاسِعَةُ: اللَّهُمَّ صَلِّ عَلَى مُحَمَّدٍ، وَعَلَى آلِ مُحَمَّدٍ وَصَحْبِهِ وَسَلِّمْ."]]},{"id":"bi9_56","label":"آدَابُ دُخُولِ الْمَسْجِدِ · ٥٦","segs":[["matn","الْعَاشِرَةُ: بِسْمِ اللَّهِ الَّذِي لَا يَضُرُّ مَعَ اسْمِهِ شَيْءٌ فِي الْأَرْضِ وَلَا فِي السَّمَاءِ، وَهُوَ السَّمِيعُ الْعَلِيمُ."]]},{"id":"bi9_57","label":"آدَابُ دُخُولِ الْمَسْجِدِ · ٥٧","segs":[["matn","تُكَرِّرُ كُلَّ وَاحِدَةٍ مِنْ هَذِهِ الْكَلِمَاتِ إِمَّا مِائَةَ مَرَّةٍ أَوْ سَبْعِينَ مَرَّةً، أَوْ عَشْرَ مَرَّاتٍ، وَهُوَ أَقَلُّهُ، لِيَكُونَ الْمَجْمُوعُ مِائَةً."]]},{"id":"bi9_58","label":"آدَابُ دُخُولِ الْمَسْجِدِ · ٥٨","segs":[["matn","وَلَازِمْ هَذِهِ الْأَوْرَادَ، وَلَا تَتَكَلَّمْ قَبْلَ طُلُوعِ الشَّمْسِ؛"]]},{"id":"bi9_59","label":"آدَابُ دُخُولِ الْمَسْجِدِ · ٥٩","segs":[["matn","فَفِي الْخَبَرِ أَنَّ ذَلِكَ أَفْضَلُ مِنْ إِعْتَاقِ ثَمَانِ رِقَابٍ مِنْ وَلَدِ إِسْمَاعِيلَ - عَلَى نَبِيِّنَا وَعَلَيْهِ الصَّلَاةُ وَالسَّلَامُ - أَعْنِي الِاشْتِغَالَ بِالذِّكْرِ إِلَى طُلُوعِ الشَّمْسِ مِنْ غَيْرِ أَنْ يَتَخَلَّلَهُ كَلَامٌ."]]}],"group":"الْقِسْمُ الْأَوَّلُ فِي الطَّاعَاتِ"},{"id":"bi10","title":"آدَابُ مَا بَعْدَ طُلُوعِ الشَّمْسِ إِلَى الزَّوَالِ","units":[{"id":"bi10_1","label":"آدَابُ مَا بَعْدَ طُلُوعِ الشَّمْسِ إِلَى الزَّوَالِ · ١","segs":[["matn","فَإِذَا طَلَعَتِ الشَّمْسُ وَارْتَفَعَتْ قَدْرَ رُمْحٍ، فَصَلِّ رَكْعَتَيْنِ، وَذَلِكَ عِنْدَ زَوَالِ وَقْتِ الْكَرَاهَةِ لِلصَّلَاةِ؛"]]},{"id":"bi10_2","label":"آدَابُ مَا بَعْدَ طُلُوعِ الشَّمْسِ إِلَى الزَّوَالِ · ٢","segs":[["matn","فَإِنَّهَا مَكْرُوهَةٌ مِنْ بَعْدِ فَرِيضَةِ الصُّبْحِ إِلَى ارْتِفَاعِ الشَّمْسِ."]]},{"id":"bi10_3","label":"آدَابُ مَا بَعْدَ طُلُوعِ الشَّمْسِ إِلَى الزَّوَالِ · ٣","segs":[["matn","فَإِذَا أَضْحَى النَّهَارُ، وَمَضَى مِنْهُ قَرِيبٌ مِنْ رُبُعِهِ، صَلِّ صَلَاةَ الضُّحَى أَرْبَعًا أَوْ سِتًّا أَوْ ثَمَانِيًا، مَثْنَى؛"]]},{"id":"bi10_4","label":"آدَابُ مَا بَعْدَ طُلُوعِ الشَّمْسِ إِلَى الزَّوَالِ · ٤","segs":[["matn","فَقَدْ نُقِلَتْ هَذِهِ الْأَعْدَادُ كُلُّهَا عَنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ."]]},{"id":"bi10_5","label":"آدَابُ مَا بَعْدَ طُلُوعِ الشَّمْسِ إِلَى الزَّوَالِ · ٥","segs":[["matn","وَ الصَّلَاةُ خَيْرٌ كُلُّهَا فَمَنْ شَاءَ فَلْيَسْتَكْثِرْ، وَمَنْ شَاءَ فَلْيَسْتَقْلِلْ، فَلَيْسَ بَيْنَ طُلُوعِ الشَّمْسِ وَالزَّوَالِ رَاتِبَةٌ مِنَ الصَّلَاةِ إِلَّا هَذِهِ؛"]]},{"id":"bi10_6","label":"آدَابُ مَا بَعْدَ طُلُوعِ الشَّمْسِ إِلَى الزَّوَالِ · ٦","segs":[["matn","فَمَا فَضَلَ عَنْهَا مِنْ أَوْقَاتِكَ فَلَكَ فِيهِ أَرْبَعُ حَالَاتٍ: الْحَالَةُ الْأُولَى وَهِيَ الْأَفْضَلُ: أَنْ تَصْرِفَهُ فِي طَلَبِ الْعِلْمِ النَّافِعِ فِي الدِّينِ، دُونَ الْفُضُولِ الَّذِي أَكَبَّ النَّاسُ عَلَيْهِ وَسَمَّوْهُ عِلْمًا."]]},{"id":"bi10_7","label":"آدَابُ مَا بَعْدَ طُلُوعِ الشَّمْسِ إِلَى الزَّوَالِ · ٧","segs":[["matn","وَالْعِلْمُ النَّافِعُ هُوَ مَا يَزِيدُ فِي خَوْفِكَ مِنَ اللَّهِ تَعَالَى، وَيَزِيدُ فِي بَصِيرَتِكَ بِعُيُوبِ نَفْسِكَ، وَيَزِيدُ فِي مَعْرِفَتِكَ بِعِبَادَةِ رَبِّكَ، وَيُقَلِّلُ مِنْ رَغْبَتِكَ فِي الدُّنْيَا،"]]},{"id":"bi10_8","label":"آدَابُ مَا بَعْدَ طُلُوعِ الشَّمْسِ إِلَى الزَّوَالِ · ٨","segs":[["matn","وَيَزِيدُ فِي رَغْبَتِكَ فِي الْآخِرَةِ، وَيَفْتَحُ بَصِيرَتَكَ بِآفَاتِ أَعْمَالِكَ حَتَّى تَحْتَرِزَ مِنْهَا، وَيُطْلِعُكَ عَلَى مَكَايِدِ الشَّيْطَانِ وَغُرُورِهِ، وَكَيْفِيَّةِ تَلْبِيسِهِ عَلَى عُلَمَاءِ السُّوءِ، حَتَّى عَرَّضَهُمْ لِمَقْتِ اللَّهِ تَعَالَى وَسَخَطِهِ؛"]]},{"id":"bi10_9","label":"آدَابُ مَا بَعْدَ طُلُوعِ الشَّمْسِ إِلَى الزَّوَالِ · ٩","segs":[["matn","حَيْثُ أَكَلُوا الدُّنْيَا بِالدِّينِ، وَاتَّخَذُوا الْعِلْمَ ذَرِيعَةً وَوَسِيلَةً إِلَى أَخْذِ أَمْوَالِ السَّلَاطِينِ، وَأَكْلِ أَمْوَالِ الْأَوْقَافِ وَالْيَتَامَى وَالْمَسَاكِينِ، وَصَرَفُوا هِمَّتَهُمْ طُولَ نَهَارِهِمْ إِلَى طَلَبِ الْجَاهِ وَالْمَنْزِلَةِ فِي قُلُوبِ الْخَلْقِ، وَاضْطَرَّهُمْ ذَلِكَ إِلَى الْمُرَاءَاةِ وَالْمُمَارَاةِ، وَالْمُنَاقَشَةِ فِي الْكَلَامِ وَالْمُبَاهَاةِ."]]},{"id":"bi10_10","label":"آدَابُ مَا بَعْدَ طُلُوعِ الشَّمْسِ إِلَى الزَّوَالِ · ١٠","segs":[["matn","وَهَذَا الْفَنُّ مِنَ الْعِلْمِ النَّافِعِ، قَدْ جَمَعْنَاهُ فِي كِتَابِ «إِحْيَاءِ عُلُومِ الدِّينِ» فَإِنْ كُنْتَ مِنْ أَهْلِهِ فَحَصِّلْهُ وَاعْمَلْ بِهِ ثُمَّ عَلِّمْهُ وَادْعُ إِلَيْهِ؛"]]},{"id":"bi10_11","label":"آدَابُ مَا بَعْدَ طُلُوعِ الشَّمْسِ إِلَى الزَّوَالِ · ١١","segs":[["matn","فَمَنْ عَلِمَ ذَلِكَ وَعَمِلَ بِهِ، ثُمَّ عَلَّمَهُ وَدَعَا إِلَيْهِ فَذَلِكَ يُدْعَى عَظِيمًا فِي مَلَكُوتِ السَّمَوَاتِ بِشَهَادَةِ عِيسَى عَلَيْهِ السَّلَامُ."]]},{"id":"bi10_12","label":"آدَابُ مَا بَعْدَ طُلُوعِ الشَّمْسِ إِلَى الزَّوَالِ · ١٢","segs":[["matn","فَإِذَا فَرَغْتَ مِنْ ذَلِكَ كُلِّهِ، وَفَرَغْتَ مِنْ إِصْلَاحِ نَفْسِكَ ظَاهِرًا وَبَاطِنًا، وَفَضَلَ شَيْءٌ مِنْ أَوْقَاتِكَ، فَلَا بَأْسَ أَنْ تَشْتَغِلَ بِعِلْمِ الْمَذْهَبِ فِي الْفِقْهِ لِتَعْرِفَ بِهِ الْفُرُوعَ النَّادِرَةَ فِي الْعِبَادَاتِ،"]]},{"id":"bi10_13","label":"آدَابُ مَا بَعْدَ طُلُوعِ الشَّمْسِ إِلَى الزَّوَالِ · ١٣","segs":[["matn","وَطَرِيقَ التَّوَسُّطِ بَيْنَ الْخَلْقِ فِي الْخُصُومَاتِ عِنْدَ انْكِبَابِهِمْ عَلَى الشَّهَوَاتِ، فَذَلِكَ أَيْضًا بَعْدَ الْفَرَاغِ مِنْ هَذِهِ الْمُهِمَّاتِ مِنْ جُمْلَةِ فُرُوضِ الْكِفَايَاتِ."]]},{"id":"bi10_14","label":"آدَابُ مَا بَعْدَ طُلُوعِ الشَّمْسِ إِلَى الزَّوَالِ · ١٤","segs":[["matn","فَإِنْ دَعَتْكَ نَفْسُكَ إِلَى تَرْكِ مَا ذَكَرْنَاهُ مِنَ الْأَوْرَادِ وَالْأَذْكَارِ اسْتِثْقَالًا لِذَلِكَ، فَاعْلَمْ أَنَّ الشَّيْطَانَ اللَّعِينَ قَدْ دَسَّ فِي قَلْبِكَ الدَّاءَ الدَّفِينَ، وَهُوَ حُبُّ الْمَالِ وَالْجَاهِ فَإِيَّاكَ أَنْ تَغْتَرَّ بِهِ، فَتَكُونَ ضُحْكَةً لَهُ، فَيُهْلِكَكَ، ثُمَّ يَسْخَرَ مِنْكَ."]]},{"id":"bi10_15","label":"آدَابُ مَا بَعْدَ طُلُوعِ الشَّمْسِ إِلَى الزَّوَالِ · ١٥","segs":[["matn","فَإِنْ جَرَّبْتَ نَفْسَكَ مُدَّةً فِي الْأَوْرَادِ وَالْعِبَادَاتِ فَكُنْتَ لَا تَسْتَثْقِلُهَا كَسَلًا عَنْهَا، لَكِنْ ظَهَرَتْ رَغْبَتُكَ فِي تَحْصِيلِ الْعِلْمِ النَّافِعِ، وَلَمْ تُرِدْ بِهِ إِلَّا وَجْهَ اللَّهِ تَعَالَى وَالدَّارَ الْآخِرَةَ، فَذَلِكَ أَفْضَلُ مِنْ نَوَافِلِ الْعِبَادَاتِ مَهْمَا صَحَّتِ النِّيَّةُ."]]},{"id":"bi10_16","label":"آدَابُ مَا بَعْدَ طُلُوعِ الشَّمْسِ إِلَى الزَّوَالِ · ١٦","segs":[["matn","وَلَكِنَّ الشَّأْنَ فِي صِحَّةِ النِّيَّةِ فَإِنْ لَمْ تَصِحَّ النِّيَّةُ فَهُوَ مَعْدِنُ غُرُورِ الْجُهَّالِ، وَمَزَلَّةُ أَقْدَامِ الرِّجَالِ."]]},{"id":"bi10_17","label":"آدَابُ مَا بَعْدَ طُلُوعِ الشَّمْسِ إِلَى الزَّوَالِ · ١٧","segs":[["matn","الْحَالَةُ الثَّانِيَةُ: أَنْ لَا تَقْدِرَ عَلَى تَحْصِيلِ الْعِلْمِ النَّافِعِ فِي الدِّينِ، وَلَكِنْ تَشْتَغِلَ بِوَظَائِفِ الْعِبَادَاتِ مِنَ الذِّكْرِ وَالتَّسْبِيحِ وَالْقِرَاءَةِ وَالصَّلَاةِ فَذَلِكَ مِنْ دَرَجَاتِ الْعَابِدِينَ، وَسِيَرِ الصَّالِحِينَ، وَتَكُونُ أَيْضًا بِذَلِكَ مِنَ الْفَائِزِينَ."]]},{"id":"bi10_18","label":"آدَابُ مَا بَعْدَ طُلُوعِ الشَّمْسِ إِلَى الزَّوَالِ · ١٨","segs":[["matn","الْحَالَةُ الثَّالِثَةُ: أَنْ تَشْتَغِلَ بِمَا يَصِلُ مِنْهُ خَيْرٌ إِلَى الْمُسْلِمِينَ، وَيَدْخُلُ بِهِ سُرُورٌ عَلَى قُلُوبِ الْمُؤْمِنِينَ، أَوْ تَتَيَسَّرُ بِهِ الْأَعْمَالُ الصَّالِحَةُ لِلصَّالِحِينَ: كَخِدْمَةِ الْفُقَهَاءِ وَالصُّوفِيَّةِ وَأَهْلِ الدِّينِ،"]]},{"id":"bi10_19","label":"آدَابُ مَا بَعْدَ طُلُوعِ الشَّمْسِ إِلَى الزَّوَالِ · ١٩","segs":[["matn","وَالتَّرَدُّدِ فِي أَشْغَالِهِمْ، وَالسَّعْيِ فِي إِطْعَامِ الْفُقَرَاءِ وَالْمَسَاكِينِ، وَالتَّرَدُّدِ مَثَلًا عَلَى الْمَرْضَى بِالْعِيَادَةِ، وَعَلَى الْجَنَائِزِ بِالتَّشْيِيعِ، فَكُلُّ ذَلِكَ أَفْضَلُ مِنَ النَّوَافِلِ؛"]]},{"id":"bi10_20","label":"آدَابُ مَا بَعْدَ طُلُوعِ الشَّمْسِ إِلَى الزَّوَالِ · ٢٠","segs":[["matn","فَإِنَّ هَذِهِ عِبَادَاتٌ، وَفِيهَا رِفْقٌ لِلْمُسْلِمِينَ. الْحَالَةُ الرَّابِعَةُ: أَلَّا تَقْوَى عَلَى ذَلِكَ، فَاشْتَغِلْ بِحَاجَاتِكَ اكْتِسَابًا عَلَى نَفْسِكَ أَوْ عَلَى عِيَالِكَ، وَقَدْ سَلِمَ الْمُسْلِمُونَ مِنْكَ وَأَمِنُوا مِنْ لِسَانِكَ وَيَدِكَ، وَسَلِمَ لَكَ دِينُكَ، إِذَا لَمْ تَرْتَكِبْ مَعْصِيَةً؛"]]},{"id":"bi10_21","label":"آدَابُ مَا بَعْدَ طُلُوعِ الشَّمْسِ إِلَى الزَّوَالِ · ٢١","segs":[["matn","فَتَنَالُ بِذَلِكَ دَرَجَةَ أَصْحَابِ الْيَمِينِ، إِنْ لَمْ تَكُنْ مِنْ أَهْلِ التَّرَقِّي إِلَى مَقَامَاتِ السَّابِقِينَ."]]},{"id":"bi10_22","label":"آدَابُ مَا بَعْدَ طُلُوعِ الشَّمْسِ إِلَى الزَّوَالِ · ٢٢","segs":[["matn","فَهَذَا أَقَلُّ الدَّرَجَاتِ فِي مَقَامَاتِ الدِّينِ، وَمَا بَعْدَ هَذَا فَهُوَ مِنْ مَرَاتِعِ الشَّيَاطِينِ؛"]]},{"id":"bi10_23","label":"آدَابُ مَا بَعْدَ طُلُوعِ الشَّمْسِ إِلَى الزَّوَالِ · ٢٣","segs":[["matn","وَذَلِكَ بِأَنْ تَشْتَغِلَ - وَالْعِيَاذُ بِاللَّهِ - بِمَا يَهْدِمُ دِينَكَ، أَوْ تُؤْذِيَ بِهِ عَبْدًا مِنْ عِبَادِ اللَّهِ تَعَالَى؛"]]},{"id":"bi10_24","label":"آدَابُ مَا بَعْدَ طُلُوعِ الشَّمْسِ إِلَى الزَّوَالِ · ٢٤","segs":[["matn","فَهَذِهِ رُتْبَةُ الْهَالِكِينَ؛ فَإِيَّاكَ أَنْ تَكُونَ فِي هَذِهِ الطَّبَقَةِ."]]},{"id":"bi10_25","label":"آدَابُ مَا بَعْدَ طُلُوعِ الشَّمْسِ إِلَى الزَّوَالِ · ٢٥","segs":[["matn","وَاعْلَمْ أَنَّ الْعَبْدَ فِي حَقِّ دِينِهِ عَلَى ثَلَاثِ دَرَجَاتٍ: إِمَّا سَالِمٌ، وَهُوَ الْمُقْتَصِرُ عَلَى أَدَاءِ الْفَرَائِضِ وَتَرْكِ الْمَعَاصِي."]]},{"id":"bi10_26","label":"آدَابُ مَا بَعْدَ طُلُوعِ الشَّمْسِ إِلَى الزَّوَالِ · ٢٦","segs":[["matn","أَوْ رَابِحٌ، وَهُوَ الْمُتَطَوِّعُ بِالْقُرُبَاتِ وَالنَّوَافِلِ. أَوْ خَاسِرٌ، وَهُوَ الْمُقَصِّرُ عَلَى اللَّوَازِمِ."]]},{"id":"bi10_27","label":"آدَابُ مَا بَعْدَ طُلُوعِ الشَّمْسِ إِلَى الزَّوَالِ · ٢٧","segs":[["matn","فَإِنْ لَمْ تَقْدِرْ أَنْ تَكُونَ رَابِحًا، فَاجْتَهِدْ أَنْ تَكُونَ سَالِمًا، وَإِيَّاكَ ثُمَّ إِيَّاكَ أَنْ تَكُونَ خَاسِرًا."]]},{"id":"bi10_28","label":"آدَابُ مَا بَعْدَ طُلُوعِ الشَّمْسِ إِلَى الزَّوَالِ · ٢٨","segs":[["matn","وَالْعَبْدُ فِي حَقِّ سَائِرِ الْعِبَادِ لَهُ ثَلَاثُ دَرَجَاتٍ: الْأُولَى: أَنْ يَنْزِلَ فِي حَقِّهِمْ مَنْزِلَةَ الْكِرَامِ الْبَرَرَةِ مِنَ الْمَلَائِكَةِ، وَهُوَ أَنْ يَسْعَى فِي أَغْرَاضِهِمْ؛"]]},{"id":"bi10_29","label":"آدَابُ مَا بَعْدَ طُلُوعِ الشَّمْسِ إِلَى الزَّوَالِ · ٢٩","segs":[["matn","رِفْقًا بِهِمْ، وَإِدْخَالًا لِلسُّرُورِ عَلَى قُلُوبِهِمْ. الثَّانِيَةُ: أَنْ يَنْزِلَ فِي حَقِّهِمْ مَنْزِلَةَ الْبَهَائِمِ وَالْجَمَادَاتِ؛"]]},{"id":"bi10_30","label":"آدَابُ مَا بَعْدَ طُلُوعِ الشَّمْسِ إِلَى الزَّوَالِ · ٣٠","segs":[["matn","فَلَا يَنَالُهُمْ خَيْرُهُ، وَلَكِنْ يَكُفُّ عَنْهُمْ شَرَّهُ. الثَّالِثَةُ: أَنْ يَنْزِلَ فِي حَقِّهِمْ مَنْزِلَةَ الْعَقَارِبِ وَالْحَيَّاتِ وَالسِّبَاعِ الضَّارِيَاتِ، لَا يُرْجَى خَيْرُهُ، وَيُتَّقَى شَرُّهُ."]]},{"id":"bi10_31","label":"آدَابُ مَا بَعْدَ طُلُوعِ الشَّمْسِ إِلَى الزَّوَالِ · ٣١","segs":[["matn","فَإِنْ لَمْ تَقْدِرْ عَلَى أَنْ تَلْتَحِقَ بِأُفُقِ الْمَلَائِكَةِ، فَاحْذَرْ أَنْ تَنْزِلَ عَنْ دَرَجَةِ الْبَهَائِمِ وَالْجَمَادَاتِ إِلَى دَرَجَةِ الْعَقَارِبِ وَالْحَيَّاتِ وَالسِّبَاعِ الضَّارِيَاتِ."]]},{"id":"bi10_32","label":"آدَابُ مَا بَعْدَ طُلُوعِ الشَّمْسِ إِلَى الزَّوَالِ · ٣٢","segs":[["matn","فَإِنْ رَضِيتَ لِنَفْسِكَ النُّزُولَ مِنْ أَعْلَى عِلِّيِّينَ، فَلَا تَرْضَ لَهَا بِالْهُوِىِّ إِلَى أَسْفَلِ سَافِلِينَ، فَلَعَلَّكَ تَنْجُو كَفَافًا لَا لَكَ وَلَا عَلَيْكَ."]]},{"id":"bi10_33","label":"آدَابُ مَا بَعْدَ طُلُوعِ الشَّمْسِ إِلَى الزَّوَالِ · ٣٣","segs":[["matn","فَعَلَيْكَ فِي بَيَاضِ نَهَارِكَ أَنْ لَا تَشْتَغِلَ إِلَّا بِمَا يَنْفَعُكَ فِي مَعَادِكَ أَوْ مَعَاشِكَ الَّذِي لَا تَسْتَغْنِي عَنِ الِاسْتِعَانَةِ بِهِ عَلَى مَعَادِكَ."]]},{"id":"bi10_34","label":"آدَابُ مَا بَعْدَ طُلُوعِ الشَّمْسِ إِلَى الزَّوَالِ · ٣٤","segs":[["matn","فَإِنْ عَجَزْتَ عَنِ الْقِيَامِ بِحَقِّ دِينِكَ مَعَ مُخَالَطَةِ النَّاسِ، وَكُنْتَ لَا تَسْلَمُ، فَالْعُزْلَةُ أَوْلَى، فَعَلَيْكَ بِهَا؛"]]},{"id":"bi10_35","label":"آدَابُ مَا بَعْدَ طُلُوعِ الشَّمْسِ إِلَى الزَّوَالِ · ٣٥","segs":[["matn","فَفِيهَا النَّجَاةُ وَالسَّلَامَةُ. فَإِنْ كَانَتِ الْوَسَاوِسُ فِي الْعُزْلَةِ تُجَاذِبُكَ إِلَى مَا لَا يُرْضِي اللَّهَ تَعَالَى، وَلَمْ تَقْدِرْ عَلَى قَمْعِهَا بِوَظَائِفِ الْعِبَادَاتِ فَعَلَيْكَ بِالنَّوْمِ فَهُوَ أَحْسَنُ أَحْوَالِكَ وَأَحْوَالِنَا إِذَا عَجَزْنَا عَنِ الْغَنِيمَةِ رَضِينَا بِالسَّلَامَةِ فِي الْهَزِيمَةِ."]]},{"id":"bi10_36","label":"آدَابُ مَا بَعْدَ طُلُوعِ الشَّمْسِ إِلَى الزَّوَالِ · ٣٦","segs":[["matn","فَأَخِسَّ بِحَالِ مَنْ سَلَامَةُ دِينِهِ فِي تَعْطِيلِ حَيَاتِهِ إِذِ النَّوْمُ أَخُو الْمَوْتِ، وَهُوَ تَعْطِيلُ الْحَيَاةِ وَالْتِحَاقٌ بِالْجَمَادَاتِ."]]}],"group":"الْقِسْمُ الْأَوَّلُ فِي الطَّاعَاتِ"},{"id":"bi11","title":"آدَابُ الِاسْتِعْدَادِ لِسَائِرِ الصَّلَوَاتِ","units":[{"id":"bi11_1","label":"آدَابُ الِاسْتِعْدَادِ لِسَائِرِ الصَّلَوَاتِ · ١","segs":[["matn","يَنْبَغِي أَنْ تَسْتَعِدَّ لِصَلَاةِ الظُّهْرِ قَبْلَ الزَّوَالِ، فَتُقَدِّمَ الْقَيْلُولَةَ إِنْ كَانَ بِكَ قِيَامٌ فِي اللَّيْلِ، أَوْ سَهَرٌ فِي الْخَيْرِ؛"]]},{"id":"bi11_2","label":"آدَابُ الِاسْتِعْدَادِ لِسَائِرِ الصَّلَوَاتِ · ٢","segs":[["matn","فَإِنَّ فِيهَا مَعُونَةً عَلَى قِيَامِ اللَّيْلِ، كَمَا أَنَّ فِي السُّحُورِ مَعُونَةً عَلَى صِيَامِ النَّهَارِ، وَالْقَيْلُولَةُ مِنْ غَيْرِ قِيَامٍ بِاللَّيْلِ كَالسُّحُورِ مِنْ غَيْرِ صِيَامٍ بِالنَّهَارِ."]]},{"id":"bi11_3","label":"آدَابُ الِاسْتِعْدَادِ لِسَائِرِ الصَّلَوَاتِ · ٣","segs":[["matn","فَإِذَا قِلْتَ، فَاجْتَهِدْ أَنْ تَسْتَيْقِظَ قَبْلَ الزَّوَالِ، وَتَتَوَضَّأَ وَتَحْضُرَ الْمَسْجِدَ، وَتُصَلِّيَ تَحِيَّةَ الْمَسْجِدِ، وَتَنْتَظِرَ الْمُؤَذِّنَ فَتُجِيبَهُ، ثُمَّ تَقُومَ فَتُصَلِّيَ أَرْبَعَ رَكَعَاتٍ عَقِبَ الزَّوَالِ، كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يُطَوِّلُهُنَّ وَيَقُولُ: «هَذَا وَقْتٌ تُفْتَحُ فِيهِ أَبْوَابُ السَّمَاءِ، فَأُحِبُّ أَنْ يُرْفَعَ لِي فِيهِ عَمَلٌ صَالِحٌ»."]]},{"id":"bi11_4","label":"آدَابُ الِاسْتِعْدَادِ لِسَائِرِ الصَّلَوَاتِ · ٤","segs":[["matn","وَهَذِهِ الْأَرْبَعُ قَبْلَ الظُّهْرِ سُنَّةٌ مُؤَكَّدَةٌ؛ فَفِي الْخَبَرِ: «مَنْ صَلَّاهُنَّ فَأَحْسَنَ رُكُوعَهُنَّ وَسُجُودَهُنَّ صَلَّى مَعَهُ سَبْعُونَ أَلْفَ مَلَكٍ يَسْتَغْفِرُونَ لَهُ إِلَى اللَّيْلِ»."]]},{"id":"bi11_5","label":"آدَابُ الِاسْتِعْدَادِ لِسَائِرِ الصَّلَوَاتِ · ٥","segs":[["matn","ثُمَّ صَلِّ الْفَرْضَ مَعَ الْإِمَامِ ثُمَّ صَلِّ بَعْدَ الْفَرْضِ رَكْعَتَيْنِ؛"]]},{"id":"bi11_6","label":"آدَابُ الِاسْتِعْدَادِ لِسَائِرِ الصَّلَوَاتِ · ٦","segs":[["matn","فَهُمَا مِنَ الرَّوَاتِبِ الثَّابِتَةِ. وَلَا تَشْتَغِلْ إِلَى الْعَصْرِ إِلَّا بِتَعَلُّمِ عِلْمٍ أَوْ إِعَانَةِ مُسْلِمٍ، أَوْ قِرَاءَةِ قُرْآنٍ أَوْ سَعْيٍ فِي مَعَاشٍ لِتَسْتَعِينَ بِهِ عَلَى دِينِكَ، ثُمَّ صَلِّ أَرْبَعَ رَكَعَاتٍ قَبْلَ الْعَصْرِ؛"]]},{"id":"bi11_7","label":"آدَابُ الِاسْتِعْدَادِ لِسَائِرِ الصَّلَوَاتِ · ٧","segs":[["matn","فَهِيَ سُنَّةٌ مُؤَكَّدَةٌ؛ فَقَدْ قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: «رَحِمَ اللَّهُ امْرَأً صَلَّى أَرْبَعًا قَبْلَ الْعَصْرِ» فَاجْتَهِدْ أَنْ يَنَالَكَ دُعَاؤُهُ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ."]]},{"id":"bi11_8","label":"آدَابُ الِاسْتِعْدَادِ لِسَائِرِ الصَّلَوَاتِ · ٨","segs":[["matn","وَلَا تَشْتَغِلْ بَعْدَ الْعَصْرِ إِلَّا بِمِثْلِ مَا سَبَقَ قَبْلَهُ، وَلَا يَنْبَغِي أَنْ تَكُونَ أَوْقَاتُكَ مُهْمَلَةً فَتَشْتَغِلَ فِي كُلِّ وَقْتٍ بِمَا اتَّفَقَ كَيْفَ اتَّفَقَ،"]]},{"id":"bi11_9","label":"آدَابُ الِاسْتِعْدَادِ لِسَائِرِ الصَّلَوَاتِ · ٩","segs":[["matn","بَلْ يَنْبَغِي أَنْ تُحَاسِبَ نَفْسَكَ وَتُرَتِّبَ أَوْرَادَكَ فِي لَيْلِكَ وَنَهَارِكَ، وَتُعَيِّنَ لِكُلِّ وَقْتٍ شُغْلًا لَا تَتَعَدَّاهُ، وَلَا تُؤْثِرُ فِيهِ سِوَاهُ فَبِذَلِكَ تَظْهَرُ بَرَكَةُ الْأَوْقَاتِ."]]},{"id":"bi11_10","label":"آدَابُ الِاسْتِعْدَادِ لِسَائِرِ الصَّلَوَاتِ · ١٠","segs":[["matn","فَأَمَّا إِذَا تَرَكْتَ نَفْسَكَ سُدًى مُهْمَلًا إِهْمَالَ الْبَهَائِمِ لَا تَدْرِي بِمَاذَا تَشْتَغِلُ فِي كُلِّ وَقْتٍ، فَيَنْقَضِي أَكْثَرُ أَوْقَاتِكَ ضَائِعًا، وَأَوْقَاتُكَ عُمُرُكَ، وَعُمُرُكَ رَأْسُ مَالِكَ، وَعَلَيْهِ تِجَارَتُكَ، وَبِهِ وُصُولُكَ إِلَى نَعِيمِ دَارِ الْأَبَدِ فِي جِوَارِ اللَّهِ تَعَالَى؛"]]},{"id":"bi11_11","label":"آدَابُ الِاسْتِعْدَادِ لِسَائِرِ الصَّلَوَاتِ · ١١","segs":[["matn","فَكُلُّ نَفَسٍ مِنْ أَنْفَاسِكَ جَوْهَرَةٌ لَا قِيمَةَ لَهَا؛"]]},{"id":"bi11_12","label":"آدَابُ الِاسْتِعْدَادِ لِسَائِرِ الصَّلَوَاتِ · ١٢","segs":[["matn","إِذْ لَا بَدَلَ لَهُ فَإِذَا فَاتَ فَلَا عَوْدَ لَهُ."]]},{"id":"bi11_13","label":"آدَابُ الِاسْتِعْدَادِ لِسَائِرِ الصَّلَوَاتِ · ١٣","segs":[["matn","فَلَا تَكُنْ كَالْحَمْقَى الْمَغْرُورِينَ الَّذِينَ يَفْرَحُونَ كُلَّ يَوْمٍ بِزِيَادَةِ أَمْوَالِهِمْ مَعَ نُقْصَانِ أَعْمَارِهِمْ، فَأَيُّ خَيْرٍ فِي مَالٍ يَزِيدُ وَعُمُرٍ يَنْقُصُ!"]]},{"id":"bi11_14","label":"آدَابُ الِاسْتِعْدَادِ لِسَائِرِ الصَّلَوَاتِ · ١٤","segs":[["matn","وَلَا تَفْرَحْ إِلَّا بِزِيَادَةِ عِلْمٍ أَوْ عَمَلٍ صَالِحٍ؛"]]},{"id":"bi11_15","label":"آدَابُ الِاسْتِعْدَادِ لِسَائِرِ الصَّلَوَاتِ · ١٥","segs":[["matn","فَإِنَّهُمَا رَفِيقَاكَ يَصْحَبَانِكَ فِي الْقَبْرِ حَيْثُ يَتَخَلَّفُ عَنْكَ أَهْلُكَ وَمَالُكَ، وَوَلَدُكَ، وَأَصْدِقَاؤُكَ."]]},{"id":"bi11_16","label":"آدَابُ الِاسْتِعْدَادِ لِسَائِرِ الصَّلَوَاتِ · ١٦","segs":[["matn","ثُمَّ إِذَا اصْفَرَّتِ الشَّمْسُ، فَاجْتَهِدْ أَنْ تَعُودَ إِلَى الْمَسْجِدِ قَبْلَ الْغُرُوبِ، وَتَشْتَغِلَ بِالتَّسْبِيحِ وَالِاسْتِغْفَارِ؛"]]},{"id":"bi11_17","label":"آدَابُ الِاسْتِعْدَادِ لِسَائِرِ الصَّلَوَاتِ · ١٧","segs":[["matn","فَإِنَّ فَضْلَ هَذَا الْوَقْتِ كَفَضْلِ مَا قَبْلَ الطُّلُوعِ، قَالَ اللَّهُ تَعَالَى: ﴿وَسَبِّحْ بِحَمْدِ رَبِّكَ قَبْلَ طُلُوعِ الشَّمْسِ وَقَبْلَ غُرُوبِهَا﴾."]]},{"id":"bi11_18","label":"آدَابُ الِاسْتِعْدَادِ لِسَائِرِ الصَّلَوَاتِ · ١٨","segs":[["matn","وَاقْرَأْ قَبْلَ غُرُوبِ الشَّمْسِ أَرْبَعَ سُوَرٍ مِنَ الْقُرْآنِ هِيَ: وَالشَّمْسِ وَضُحَاهَا وَاللَّيْلِ إِذَا يَغْشَى، وَالْمُعَوِّذَتَيْنِ."]]},{"id":"bi11_19","label":"آدَابُ الِاسْتِعْدَادِ لِسَائِرِ الصَّلَوَاتِ · ١٩","segs":[["matn","وَلْتَغْرُبْ عَلَيْكَ الشَّمْسُ وَأَنْتَ فِي الِاسْتِغْفَارِ، فَإِذَا سَمِعْتَ الْأَذَانَ فَأَجِبْهُ، وَقُلْ بَعْدَهُ: اللَّهُمَّ إِنِّي أَسْأَلُكَ عِنْدَ إِقْبَالِ لَيْلِكَ، وَإِدْبَارِ نَهَارِكَ، وَحُضُورِ صَلَاتِكَ، وَأَصْوَاتِ دُعَاتِكَ: أَنْ تُؤْتِيَ مُحَمَّدًا الْوَسِيلَةَ - وَالْفَضِيلَةَ وَالشَّرَفَ وَالدَّرَجَةَ الرَّفِيعَةَ، وَابْعَثْهُ الْمَقَامَ الْمَحْمُودَ الَّذِي وَعَدْتَهُ إِنَّكَ لَا تُخْلِفُ الْمِيعَادَ."]]},{"id":"bi11_20","label":"آدَابُ الِاسْتِعْدَادِ لِسَائِرِ الصَّلَوَاتِ · ٢٠","segs":[["matn","وَالدُّعَاءُ كَمَا سَبَقَ. ثُمَّ صَلِّ الْفَرْضَ بَعْدَ جَوَابِ الْمُؤَذِّنِ وَالْإِقَامَةِ، وَصَلِّ بَعْدَهُ قَبْلَ أَنْ تَتَكَلَّمَ رَكْعَتَيْنِ، فَهُمَا رَاتِبَتَا الْمَغْرِبِ وَإِنْ صَلَّيْتَ بَعْدَهُمَا أَرْبَعًا تُطِيلُهُنَّ، فَهُنَّ أَيْضًا سُنَّةٌ."]]},{"id":"bi11_21","label":"آدَابُ الِاسْتِعْدَادِ لِسَائِرِ الصَّلَوَاتِ · ٢١","segs":[["matn","وَإِنْ أَمْكَنَكَ أَنْ تَنْوِيَ الِاعْتِكَافَ إِلَى الْعِشَاءِ، وَتُحْيِيَ مَا بَيْنَ الْعِشَاءَيْنِ بِالصَّلَاةِ فَافْعَلْ، فَقَدْ وَرَدَ فِي فَضْلِ ذَلِكَ مَا لَا يُحْصَى، وَهِيَ نَاشِئَةُ اللَّيْلِ؛"]]},{"id":"bi11_22","label":"آدَابُ الِاسْتِعْدَادِ لِسَائِرِ الصَّلَوَاتِ · ٢٢","segs":[["matn","لِأَنَّهَا أَوَّلُ نَشْأَتِهِ، وَهِيَ صَلَاةُ الْأَوَّابِينَ، وَسُئِلَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنْ قَوْلِهِ تَعَالَى: ﴿تَتَجَافَىٰ جُنُوبُهُمْ عَنِ الْمَضَاجِعِ﴾ فَقَالَ: «هِيَ الصَّلَاةُ مَا بَيْنَ الْعِشَاءَيْنِ؛"]]},{"id":"bi11_23","label":"آدَابُ الِاسْتِعْدَادِ لِسَائِرِ الصَّلَوَاتِ · ٢٣","segs":[["matn","فَإِنَّهَا تَذْهَبُ بِمَلَاغِي أَوَّلِ النَّهَارِ». وَتُهَذِّبُ آخِرَهُ وَالْمَلَاغِي جَمْعُ مَلْغَاةٍ وَهِيَ مِنَ اللَّغْوِ."]]},{"id":"bi11_24","label":"آدَابُ الِاسْتِعْدَادِ لِسَائِرِ الصَّلَوَاتِ · ٢٤","segs":[["matn","فَإِذَا دَخَلَ وَقْتُ الْعِشَاءِ، فَصَلِّ أَرْبَعَ رَكَعَاتٍ قَبْلَ الْفَرْضِ إِحْيَاءً لِمَا بَيْنَ الْأَذَانَيْنِ فَفَضْلُ ذَلِكَ كَثِيرٌ وَفِي الْخَبَرِ: «أَنَّ الدُّعَاءَ بَيْنَ الْأَذَانِ وَالْإِقَامَةِ لَا يُرَدُّ»."]]},{"id":"bi11_25","label":"آدَابُ الِاسْتِعْدَادِ لِسَائِرِ الصَّلَوَاتِ · ٢٥","segs":[["matn","ثُمَّ صَلِّ الْفَرْضَ وَصَلِّ الرَّاتِبَةَ رَكْعَتَيْنِ، وَاقْرَأْ فِيهِمَا سُورَةَ ألم السَّجْدَةِ، وَتَبَارَكَ الْمُلْكِ أَوْ سُورَةَ يس، وَالدُّخَانِ فَذَلِكَ مَأْثُورٌ عَنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ."]]},{"id":"bi11_26","label":"آدَابُ الِاسْتِعْدَادِ لِسَائِرِ الصَّلَوَاتِ · ٢٦","segs":[["matn","وَصَلِّ بَعْدَهُمَا أَرْبَعَ رَكَعَاتٍ، فَفِي الْخَبَرِ مَا يَدُلُّ عَلَى عِظَمِ فَضْلِهِنَّ."]]},{"id":"bi11_27","label":"آدَابُ الِاسْتِعْدَادِ لِسَائِرِ الصَّلَوَاتِ · ٢٧","segs":[["matn","ثُمَّ صَلِّ الْوِتْرَ بَعْدَهَا ثَلَاثًا بِتَسْلِيمَتَيْنِ أَوْ بِتَسْلِيمَةٍ وَاحِدَةٍ."]]},{"id":"bi11_28","label":"آدَابُ الِاسْتِعْدَادِ لِسَائِرِ الصَّلَوَاتِ · ٢٨","segs":[["matn","وَكَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقْرَأُ فِيهَا سُورَةَ سَبِّحِ اسْمَ رَبِّكَ الْأَعْلَى، وَقُلْ يَا أَيُّهَا الْكَافِرُونَ، وَالْإِخْلَاصَ وَالْمُعَوِّذَتَيْنِ."]]},{"id":"bi11_29","label":"آدَابُ الِاسْتِعْدَادِ لِسَائِرِ الصَّلَوَاتِ · ٢٩","segs":[["matn","فَإِنْ كُنْتَ عَازِمًا عَلَى قِيَامِ اللَّيْلِ، فَأَخِّرِ الْوِتْرَ، لِيَكُونَ آخِرَ صَلَاتِكَ وِتْرًا."]]},{"id":"bi11_30","label":"آدَابُ الِاسْتِعْدَادِ لِسَائِرِ الصَّلَوَاتِ · ٣٠","segs":[["matn","ثُمَّ اشْتَغِلْ بَعْدَ ذَلِكَ بِمُذَاكَرَةِ عِلْمٍ أَوْ مُطَالَعَةِ كِتَابٍ، وَلَا تَشْتَغِلْ بِاللَّهْوِ وَاللَّعِبِ فَيَكُونَ ذَلِكَ خَاتِمَةَ أَعْمَالِكَ قَبْلَ نَوْمِكَ؛ فَإِنَّمَا الْأَعْمَالُ بِخَوَاتِيمِهَا."]]}],"group":"الْقِسْمُ الْأَوَّلُ فِي الطَّاعَاتِ"},{"id":"bi12","title":"آدَابُ النَّوْمِ","units":[{"id":"bi12_1","label":"آدَابُ النَّوْمِ · ١","segs":[["matn","فَإِذَا أَرَدْتَ النَّوْمَ، فَابْسُطْ فِرَاشَكَ مُسْتَقْبِلَ الْقِبْلَةِ، وَنَمْ عَلَى يَمِينِكَ كَمَا يَضْطَجِعُ الْمَيِّتُ فِي لَحْدِهِ."]]},{"id":"bi12_2","label":"آدَابُ النَّوْمِ · ٢","segs":[["matn","وَاعْلَمْ أَنَّ النَّوْمَ مِثْلُ الْمَوْتِ، وَالْيَقَظَةَ، مِثْلُ الْبَعْثِ."]]},{"id":"bi12_3","label":"آدَابُ النَّوْمِ · ٣","segs":[["matn","وَلَعَلَّ اللَّهَ تَعَالَى يَقْبِضُ رُوحَكَ فِي لَيْلَتِكَ، فَكُنْ مُسْتَعِدًّا لِلِقَائِهِ، بِأَنْ تَنَامَ عَلَى طَهَارَةٍ، وَتَكُونَ وَصِيَّتُكَ مَكْتُوبَةً تَحْتَ رَأْسِكَ، وَتَنَامَ تَائِبًا مِنَ الذُّنُوبِ، مُسْتَغْفِرًا، عَازِمًا عَلَى أَنْ لَا تَعُودَ إِلَى مَعْصِيَةٍ."]]},{"id":"bi12_4","label":"آدَابُ النَّوْمِ · ٤","segs":[["matn","وَاعْزِمْ عَلَى الْخَيْرِ لِجَمِيعِ الْمُسْلِمِينَ إِنْ بَعَثَكَ اللَّهُ تَعَالَى، وَتَذَكَّرْ أَنَّكَ سَتُضْجَعُ فِي اللَّحْدِ كَذَلِكَ وَحِيدًا فَرِيدًا لَيْسَ مَعَكَ إِلَّا عَمَلُكَ، وَلَا تُجْزَى إِلَّا بِسَعْيِكَ."]]},{"id":"bi12_5","label":"آدَابُ النَّوْمِ · ٥","segs":[["matn","وَلَا تَسْتَجْلِبِ النَّوْمَ تَكَلُّفًا بِتَمْهِيدِ الْفُرُشِ الْوَطِيئَةِ؛ فَإِنَّ النَّوْمَ تَعْطِيلٌ لِلْحَيَاةِ، إِلَّا إِذَا كَانَتْ يَقَظَتُكَ وَبَالًا عَلَيْكَ؛"]]},{"id":"bi12_6","label":"آدَابُ النَّوْمِ · ٦","segs":[["matn","فَنَوْمُكَ سَلَامَةٌ لِدِينِكَ. وَاعْلَمْ أَنَّ اللَّيْلَ وَالنَّهَارَ أَرْبَعٌ وَعِشْرُونَ سَاعَةً، فَلَا يَكُنْ نَوْمُكَ بِاللَّيْلِ وَالنَّهَارِ أَكْثَرَ مِنْ ثَمَانِي سَاعَاتٍ، فَيَكْفِيكَ إِنْ عِشْتَ مَثَلًا سِتِّينَ سَنَةً أَنْ تُضَيِّعَ مِنْهَا عِشْرِينَ سَنَةً وَهُوَ ثُلُثُ عُمُرِكَ."]]},{"id":"bi12_7","label":"آدَابُ النَّوْمِ · ٧","segs":[["matn","وَأَعِدَّ عِنْدَ النَّوْمِ سِوَاكَكَ وَطَهُورَكَ، وَاعْزِمْ عَلَى قِيَامِ اللَّيْلِ، أَوْ عَلَى الْقِيَامِ قَبْلَ الصُّبْحِ، فَرَكْعَتَانِ فِي جَوْفِ اللَّيْلِ كَنْزٌ مِنْ كُنُوزِ الْبِرِّ؛"]]},{"id":"bi12_8","label":"آدَابُ النَّوْمِ · ٨","segs":[["matn","فَاسْتَكْثِرْ مِنْ كُنُوزِكَ لِيَوْمِ فَقْرِكَ، فَلَنْ تُغْنِيَ عَنْكَ كُنُوزُ الدُّنْيَا إِذَا مِتَّ."]]},{"id":"bi12_9","label":"آدَابُ النَّوْمِ · ٩","segs":[["matn","وَقُلْ عِنْدَ نَوْمِكَ: بِاسْمِكَ رَبِّي وَضَعْتُ جَنْبِي وَبِاسْمِكَ أَرْفَعُهُ، فَاغْفِرْ لِي ذَنْبِي؛"]]},{"id":"bi12_10","label":"آدَابُ النَّوْمِ · ١٠","segs":[["matn","اللَّهُمَّ قِنِي عَذَابَكَ يَوْمَ تَبْعَثُ عِبَادَكَ، اللَّهُمَّ بِاسْمِكَ أَحْيَا وَأَمُوتُ؛"]]},{"id":"bi12_11","label":"آدَابُ النَّوْمِ · ١١","segs":[["matn","أَعُوذُ بِكَ اللَّهُمَّ مِنْ شَرِّ كُلِّ ذِي شَرٍّ، وَمِنْ شَرِّ كُلِّ دَابَّةٍ أَنْتَ آخِذٌ بِنَاصِيَتِهَا، إِنَّ رَبِّي عَلَى صِرَاطٍ مُسْتَقِيمٍ؛"]]},{"id":"bi12_12","label":"آدَابُ النَّوْمِ · ١٢","segs":[["matn","اللَّهُمَّ أَنْتَ الْأَوَّلُ فَلَيْسَ قَبْلَكَ شَيْءٌ، وَأَنْتَ الْآخِرُ فَلَيْسَ بَعْدَكَ شَيْءٌ، وَأَنْتَ الظَّاهِرُ فَلَيْسَ فَوْقَكَ شَيْءٌ، وَأَنْتَ الْبَاطِنُ فَلَيْسَ دُونَكَ شَيْءٌ، اقْضِ عَنِّي الدَّيْنَ، وَأَغْنِنِي مِنَ الْفَقْرِ؛"]]},{"id":"bi12_13","label":"آدَابُ النَّوْمِ · ١٣","segs":[["matn","اللَّهُمَّ أَنْتَ خَلَقْتَ نَفْسِي وَأَنْتَ تَتَوَفَّاهَا، لَكَ مَمَاتُهَا وَمَحْيَاهَا، إِنْ أَمَتَّهَا فَاغْفِرْ لَهَا، وَإِنْ أَحْيَيْتَهَا فَاحْفَظْهَا بِمَا تَحْفَظُ بِهِ عِبَادَكَ الصَّالِحِينَ؛"]]},{"id":"bi12_14","label":"آدَابُ النَّوْمِ · ١٤","segs":[["matn","اللَّهُمَّ إِنِّي أَسْأَلُكَ الْعَفْوَ وَالْعَافِيَةَ فِي الدِّينِ وَالدُّنْيَا وَالْآخِرَةِ؛"]]},{"id":"bi12_15","label":"آدَابُ النَّوْمِ · ١٥","segs":[["matn","اللَّهُمَّ أَيْقِظْنِي فِي أَحَبِّ السَّاعَاتِ إِلَيْكَ، وَاسْتَعْمِلْنِي بِأَحَبِّ الْأَعْمَالِ إِلَيْكَ، لِتُقَرِّبَنِي إِلَيْكَ زُلْفَى، وَتُبْعِدَنِي عَنْ سَخَطِكَ بُعْدًا، أَسْأَلُكَ فَتُعْطِينِي، وَأَسْتَغْفِرُكَ فَتَغْفِرُ لِي، وَأَدْعُوكَ فَتَسْتَجِيبُ لِي."]]},{"id":"bi12_16","label":"آدَابُ النَّوْمِ · ١٦","segs":[["matn","ثُمَّ اقْرَأْ آيَةَ الْكُرْسِيِّ، وَآمَنَ الرَّسُولُ إِلَى آخِرِ السُّورَةِ، وَالْإِخْلَاصَ، وَالْمُعَوِّذَتَيْنِ، وَتَبَارَكَ الْمُلْكِ."]]},{"id":"bi12_17","label":"آدَابُ النَّوْمِ · ١٧","segs":[["matn","وَيَأْخُذُكَ النَّوْمُ وَأَنْتَ عَلَى ذِكْرِ اللَّهِ وَعَلَى الطَّهَارَةِ."]]},{"id":"bi12_18","label":"آدَابُ النَّوْمِ · ١٨","segs":[["matn","فَمَنْ فَعَلَ ذَلِكَ عُرِجَ بِرُوحِهِ إِلَى الْعَرْشِ، وَكُتِبَ مُصَلِّيًا إِلَى أَنْ يَسْتَيْقِظَ."]]},{"id":"bi12_19","label":"آدَابُ النَّوْمِ · ١٩","segs":[["matn","فَإِذَا اسْتَيْقَظْتَ، فَارْجِعْ إِلَى مَا عَرَّفْتُكَ أَوَّلًا، وَدَاوِمْ عَلَى هَذَا التَّرْتِيبِ بَقِيَّةَ عُمُرِكَ."]]},{"id":"bi12_20","label":"آدَابُ النَّوْمِ · ٢٠","segs":[["matn","فَإِنْ شَقَّتْ عَلَيْكَ الْمُدَاوَمَةُ، فَاصْبِرْ صَبْرَ الْمَرِيضِ عَلَى مَرَارَةِ الدَّوَاءِ انْتِظَارًا لِلشِّفَاءِ، وَتَفَكَّرْ فِي قِصَرِ عُمُرِكَ، وَإِنْ عِشْتَ مَثَلًا مِائَةَ سَنَةٍ فَهِيَ قَلِيلَةٌ بِالْإِضَافَةِ إِلَى مُقَامِكَ فِي الدَّارِ الْآخِرَةِ وَهِيَ أَبَدُ الْآبَادِ،"]]},{"id":"bi12_21","label":"آدَابُ النَّوْمِ · ٢١","segs":[["matn","وَتَأَمَّلْ أَنَّكَ كَيْفَ تَتَحَمَّلُ الْمَشَقَّةَ وَالذُّلَّ فِي طَلَبِ الدُّنْيَا شَهْرًا أَوْ سَنَةً رَجَاءَ أَنْ تَسْتَرِيحَ بِهَا عِشْرِينَ سَنَةً مَثَلًا، فَكَيْفَ لَا تَتَحَمَّلُ ذَلِكَ أَيَّامًا قَلَائِلَ رَجَاءَ الِاسْتِرَاحَةِ أَبَدَ الْآبَادِ!"]]},{"id":"bi12_22","label":"آدَابُ النَّوْمِ · ٢٢","segs":[["matn","وَلَا تُطَوِّلْ أَمَلَكَ فَيَثْقُلَ عَلَيْكَ عَمَلُكَ، وَقَدِّرْ قُرْبَ الْمَوْتِ، وَقُلْ فِي نَفْسِكَ: إِنِّي أَتَحَمَّلُ الْمَشَقَّةَ الْيَوْمَ فَلَعَلِّي أَمُوتُ اللَّيْلَةَ، وَأَصْبِرُ اللَّيْلَةَ فَلَعَلِّي أَمُوتُ غَدًا؛"]]},{"id":"bi12_23","label":"آدَابُ النَّوْمِ · ٢٣","segs":[["matn","فَإِنَّ الْمَوْتَ لَا يَهْجُمُ فِي وَقْتٍ مَخْصُوصٍ، وَحَالٍ مَخْصُوصٍ، فَلَا بُدَّ مِنْ هُجُومِهِ؛"]]},{"id":"bi12_24","label":"آدَابُ النَّوْمِ · ٢٤","segs":[["matn","فَالِاسْتِعْدَادُ لَهُ أَوْلَى مِنَ الِاسْتِعْدَادِ لِلدُّنْيَا، وَأَنْتَ تَعْلَمُ أَنَّكَ لَا تَبْقَى فِيهَا إِلَّا مُدَّةً يَسِيرَةً، وَلَعَلَّهُ لَمْ يَبْقَ مِنْ أَجَلِكَ إِلَّا يَوْمٌ وَاحِدٌ، أَوْ نَفَسٌ وَاحِدٌ؛"]]},{"id":"bi12_25","label":"آدَابُ النَّوْمِ · ٢٥","segs":[["matn","فَقَدِّرْ هَذَا فِي قَلْبِكَ كُلَّ يَوْمٍ، وَكَلِّفْ نَفْسَكَ الصَّبْرَ عَلَى طَاعَةِ اللَّهِ يَوْمًا فَيَوْمًا، فَإِنَّكَ لَوْ قَدَّرْتَ الْبَقَاءَ خَمْسِينَ سَنَةً، وَأَلْزَمْتَهَا الصَّبْرَ عَلَى طَاعَةِ اللَّهِ تَعَالَى نَفَرَتْ وَاسْتَعْصَتْ عَلَيْكَ."]]},{"id":"bi12_26","label":"آدَابُ النَّوْمِ · ٢٦","segs":[["matn","فَإِنْ فَعَلْتَ ذَلِكَ فَرِحْتَ عِنْدَ الْمَوْتِ فَرَحًا لَا آخِرَ لَهُ."]]},{"id":"bi12_27","label":"آدَابُ النَّوْمِ · ٢٧","segs":[["matn","وَإِنْ سَوَّفْتَ وَتَسَاهَلْتَ جَاءَكَ الْمَوْتُ فِي وَقْتٍ لَا تَحْتَسِبُهُ، وَتَحَسَّرْتَ تَحَسُّرًا لَا آخِرَ لَهُ، وَعِنْدَ الصَّبَاحِ يَحْمَدُ الْقَوْمُ السُّرَى، وَعِنْدَ الْمَوْتِ يَأْتِيكَ الْخَبَرُ الْيَقِينُ، وَلَتَعْلَمُنَّ نَبَأَهُ بَعْدَ حِينٍ."]]},{"id":"bi12_28","label":"آدَابُ النَّوْمِ · ٢٨","segs":[["matn","وَإِذَا أَرْشَدْنَاكَ إِلَى تَرْتِيبِ الْأَوْرَادِ، فَلْنَذْكُرْ لَكَ كَيْفِيَّةَ الصَّلَاةِ وَالصَّوْمِ وَآدَابَهُمَا، وَآدَابَ الْإِمَامَةِ وَالْقُدْوَةِ وَالْجُمُعَةِ."]]}],"group":"الْقِسْمُ الْأَوَّلُ فِي الطَّاعَاتِ"},{"id":"bi13","title":"آدَابُ الصَّلَاةِ","units":[{"id":"bi13_1","label":"آدَابُ الصَّلَاةِ · ١","segs":[["matn","فَإِذَا فَرَغْتَ مِنْ طَهَارَةِ الْحَدَثِ، وَطَهَارَةِ الْخَبَثِ، فِي الْبَدَنِ، وَالثِّيَابِ، وَالْمَكَانِ وَمِنْ سَتْرِ الْعَوْرَةِ مِنَ السُّرَّةِ إِلَى الرُّكْبَةِ، فَاسْتَقْبِلِ الْقِبْلَةَ قَائِمًا مُزَاوِجًا بَيْنَ قَدَمَيْكَ لَا تَضُمُّهُمَا، وَاسْتَوِ قَائِمًا، وَاقْرَأْ ﴿قُلْ أَعُوذُ بِرَبِّ النَّاسِ﴾ تَحَصُّنًا بِهَا مِنَ الشَّيْطَانِ الرَّجِيمِ."]]},{"id":"bi13_2","label":"آدَابُ الصَّلَاةِ · ٢","segs":[["matn","وَأَحْضِرْ قَلْبَكَ مَا أَنْتَ فِيهِ، وَفَرِّغْهُ مِنَ الْوَسْوَاسِ، وَانْظُرْ بَيْنَ يَدَيْ مَنْ تَقُومُ، وَمَنْ تُنَاجِي، وَاسْتَحِ أَنْ تُنَاجِيَ مَوْلَاكَ بِقَلْبٍ غَافِلٍ، وَصَدْرٍ مَشْحُونٍ بِوَسَاوِسِ الدُّنْيَا وَخَبَائِثِ الشَّهَوَاتِ."]]},{"id":"bi13_3","label":"آدَابُ الصَّلَاةِ · ٣","segs":[["matn","وَاعْلَمْ أَنَّهُ تَعَالَى مُطَّلِعٌ عَلَى سَرِيرَتِكَ وَنَاظِرٌ إِلَى قَلْبِكَ، فَإِنَّمَا يَتَقَبَّلُ اللَّهُ مِنْ صَلَاتِكَ بِقَدْرِ خُشُوعِكَ وَخُضُوعِكَ وَتَوَاضُعِكَ وَتَضَرُّعِكَ، وَاعْبُدْهُ فِي صَلَاتِكَ كَأَنَّكَ تَرَاهُ؛"]]},{"id":"bi13_4","label":"آدَابُ الصَّلَاةِ · ٤","segs":[["matn","فَإِنْ لَمْ تَكُنْ تَرَاهُ فَإِنَّهُ يَرَاكَ. فَإِنْ لَمْ يَحْضُرْ قَلْبُكَ وَلَمْ تَسْكُنْ جَوَارِحُكَ لِقُصُورِ مَعْرِفَتِكَ بِجَلَالِ اللَّهِ تَعَالَى،"]]},{"id":"bi13_5","label":"آدَابُ الصَّلَاةِ · ٥","segs":[["matn","فَقَدِّرْ أَنَّ رَجُلًا صَالِحًا مِنْ وُجُوهِ أَهْلِ بَيْتِكَ يَنْظُرُ إِلَيْكَ لِيَعْلَمَ كَيْفَ صَلَاتُكَ، فَعِنْدَ ذَلِكَ يَحْضُرُ قَلْبُكَ وَتَسْكُنُ جَوَارِحُكَ، ثُمَّ ارْجِعْ إِلَى نَفْسِكَ وَقُلْ:"]]},{"id":"bi13_6","label":"آدَابُ الصَّلَاةِ · ٦","segs":[["matn","يَا نَفْسَ السُّوءِ أَلَا تَسْتَحِينَ مِنْ خَالِقِكِ وَمَوْلَاكِ،"]]},{"id":"bi13_7","label":"آدَابُ الصَّلَاةِ · ٧","segs":[["matn","إِذْ قَدَّرْتِ اطِّلَاعَ عَبْدٍ ذَلِيلٍ مِنْ عِبَادِهِ عَلَيْكِ، وَلَيْسَ بِيَدِهِ ضَرُّكِ وَلَا نَفْعُكِ خَشَعَتْ جَوَارِحُكِ وَحَسُنَتْ صَلَاتُكِ، ثُمَّ إِنَّكِ تَعْلَمِينَ أَنَّهُ مُطَّلِعٌ عَلَيْكِ، وَلَا تَخْشَعِينَ لِعَظَمَتِهِ، أَهُوَ - تَعَالَى - عِنْدَكِ أَقَلُّ مِنْ عَبْدٍ مِنْ عِبَادِهِ؟!"]]},{"id":"bi13_8","label":"آدَابُ الصَّلَاةِ · ٨","segs":[["matn","فَمَا أَشَدَّ طُغْيَانَكِ وَجَهْلَكِ وَمَا أَعْظَمَ عَدَاوَتَكِ لِنَفْسِكِ."]]},{"id":"bi13_9","label":"آدَابُ الصَّلَاةِ · ٩","segs":[["matn","وَعَالِجْ قَلْبَكَ بِهَذِهِ الْحِيَلِ فَعَسَى أَنْ يَحْضُرَ مَعَكَ فِي صَلَاتِكَ؛"]]},{"id":"bi13_10","label":"آدَابُ الصَّلَاةِ · ١٠","segs":[["matn","فَإِنَّهُ لَيْسَ لَكَ مِنْ صَلَاتِكَ إِلَّا مَا عَقَلْتَ مِنْهَا، وَأَمَّا مَا أَتَيْتَ مَعَ الْغَفْلَةِ وَالسَّهْوِ فَهُوَ إِلَى الِاسْتِغْفَارِ وَالتَّكْفِيرِ أَحْوَجُ."]]},{"id":"bi13_11","label":"آدَابُ الصَّلَاةِ · ١١","segs":[["matn","فَإِذَا حَضَرَ قَلْبُكَ، فَلَا تَتْرُكِ الْإِقَامَةَ، وَإِنْ كُنْتَ وَحْدَكَ."]]},{"id":"bi13_12","label":"آدَابُ الصَّلَاةِ · ١٢","segs":[["matn","وَإِنِ انْتَظَرْتَ حُضُورَ جَمَاعَةٍ فَأَذِّنْ، ثُمَّ أَقِمْ. فَإِذَا أَقَمْتَ فَانْوِ وَقُلْ فِي قَلْبِكَ: أُؤَدِّي فَرْضَ الظُّهْرِ لِلَّهِ تَعَالَى، وَلْيَكُنْ ذَلِكَ حَاضِرًا فِي قَلْبِكَ عِنْدَ تَكْبِيرِكَ."]]},{"id":"bi13_13","label":"آدَابُ الصَّلَاةِ · ١٣","segs":[["matn","وَلَا تَغْرُبْ عَنْكَ النِّيَّةُ قَبْلَ الْفَرَاغِ مِنَ التَّكْبِيرِ، وَارْفَعْ يَدَيْكَ عِنْدَ التَّكْبِيرِ - بَعْدَ إِرْسَالِهِمَا أَوَّلًا - إِلَى حَذْوِ مَنْكِبَيْكَ وَهُمَا مَبْسُوطَتَانِ، وَأَصَابِعُهُمَا مَنْشُورَةٌ،"]]},{"id":"bi13_14","label":"آدَابُ الصَّلَاةِ · ١٤","segs":[["matn","وَلَا تَتَكَلَّفْ ضَمَّهُمَا وَلَا تَفْرِيجَهُمَا، بِحَيْثُ تُحَاذِي بِإِبْهَامَيْكَ شَحْمَتَيْ أُذُنَيْكَ، وَبِرُءُوسِ أَصَابِعِكَ أَعْلَى أُذُنَيْكَ، وَبِكَفَّيْكَ مَنْكِبَيْكَ، فَإِذَا اسْتَقَرَّتَا فِي مَقَرِّهِمَا فَكَبِّرْ، ثُمَّ أَرْسِلْهُمَا بِرِفْقٍ."]]},{"id":"bi13_15","label":"آدَابُ الصَّلَاةِ · ١٥","segs":[["matn","وَلَا تَدْفَعْ يَدَيْكَ عِنْدَ الرَّفْعِ وَالْإِرْسَالِ إِلَى قُدَّامٍ دَفْعًا، وَلَا إِلَى خَلْفٍ رَفْعًا، وَلَا تَنْفُضْهُمَا يَمِينًا وَلَا شِمَالًا."]]},{"id":"bi13_16","label":"آدَابُ الصَّلَاةِ · ١٦","segs":[["matn","فَإِذَا أَرْسَلْتَهُمَا فَاسْتَأْنِفْ رَفْعَهُمَا إِلَى صَدْرِكَ، وَأَكْرِمِ الْيُمْنَى بِوَضْعِهَا عَلَى الْيُسْرَى، وَانْشُرْ أَصَابِعَ الْيُمْنَى عَلَى طُولِ ذِرَاعِكَ الْيُسْرَى، وَاقْبِضْ بِهَا عَلَى كُوعِهَا."]]},{"id":"bi13_17","label":"آدَابُ الصَّلَاةِ · ١٧","segs":[["matn","وَقُلْ بَعْدَ التَّكْبِيرِ: اللَّهُ أَكْبَرُ كَبِيرًا، وَالْحَمْدُ لِلَّهِ كَثِيرًا، وَسُبْحَانَ اللَّهِ بُكْرَةً وَأَصِيلًا، ثُمَّ اقْرَأْ: وَجَّهْتُ وَجْهِيَ لِلَّذِي فَطَرَ السَّمَوَاتِ وَالْأَرْضَ حَنِيفًا مُسْلِمًا وَمَا أَنَا مِنَ الْمُشْرِكِينَ، إِنَّ صَلَاتِي وَنُسُكِي وَمَحْيَايَ وَمَمَاتِي لِلَّهِ رَبِّ الْعَالَمِينَ لَا شَرِيكَ لَهُ وَبِذَلِكَ أُمِرْتُ وَأَنَا مِنَ الْمُسْلِمِينَ."]]},{"id":"bi13_18","label":"آدَابُ الصَّلَاةِ · ١٨","segs":[["matn","ثُمَّ قُلْ: أَعُوذُ بِاللَّهِ مِنَ الشَّيْطَانِ الرَّجِيمِ، ثُمَّ اقْرَأِ الْفَاتِحَةَ بِتَشْدِيدَاتِهَا، وَاجْتَهِدْ فِي الْفَرْقِ بَيْنَ الضَّادِ وَالظَّاءِ فِي قِرَاءَتِكَ فِي الصَّلَاةِ، وَقُلْ آمِينَ، وَلَا تَصِلْهُ بِقَوْلِكَ: وَلَا الضَّالِّينَ - وَصْلًا وَاجْهَرْ بِالْقِرَاءَةِ فِي الصُّبْحِ وَالْمَغْرِبِ، وَالْعِشَاءِ،"]]},{"id":"bi13_19","label":"آدَابُ الصَّلَاةِ · ١٩","segs":[["matn","أَعْنِي فِي الرَّكْعَتَيْنِ الْأُولَيَيْنِ إِلَّا أَنْ تَكُونَ مَأْمُومًا وَاقْرَأْ فِي الصُّبْحِ بَعْدَ الْفَاتِحَةِ مِنَ السُّوَرِ الطِّوَالِ مِنَ الْمُفَصَّلِ، وَفِي الْمَغْرِبِ مِنْ قِصَارِهِ، وَفِي الظُّهْرِ وَالْعَصْرِ وَالْعِشَاءِ مِنْ أَوْسَاطِهِ،"]]},{"id":"bi13_20","label":"آدَابُ الصَّلَاةِ · ٢٠","segs":[["matn","نَحْوُ: ﴿وَالسَّمَاءِ ذَاتِ الْبُرُوجِ﴾ وَمَا قَارَبَهَا مِنَ السُّوَرِ، وَفِي الصُّبْحِ فِي السَّفَرِ: ﴿قُلْ يَا أَيُّهَا الْكَافِرُونَ﴾، وَ ﴿قُلْ هُوَ اللَّهُ أَحَدٌ﴾."]]},{"id":"bi13_21","label":"آدَابُ الصَّلَاةِ · ٢١","segs":[["matn","وَلَا تَصِلْ آخِرَ السُّورَةِ بِتَكْبِيرَةِ الرُّكُوعِ، وَلَكِنِ افْصِلْ بَيْنَهُمَا بِمِقْدَارِ سُبْحَانَ اللَّهِ."]]},{"id":"bi13_22","label":"آدَابُ الصَّلَاةِ · ٢٢","segs":[["matn","وَكُنْ فِي جَمِيعِ قِيَامِكَ مُطْرِقًا، قَاصِرًا نَظَرَكَ عَلَى مُصَلَّاكَ؛"]]},{"id":"bi13_23","label":"آدَابُ الصَّلَاةِ · ٢٣","segs":[["matn","فَذَلِكَ أَجْمَعُ لِهَمِّكَ، وَأَجْدَرُ لِحُضُورِ قَلْبِكَ وَإِيَّاكَ أَنْ تَلْتَفِتَ يَمِينًا وَشِمَالًا فِي صَلَاتِكَ."]]},{"id":"bi13_24","label":"آدَابُ الصَّلَاةِ · ٢٤","segs":[["matn","ثُمَّ كَبِّرْ لِلرُّكُوعِ وَارْفَعْ يَدَيْكَ كَمَا سَبَقَ، وَمُدَّ التَّكْبِيرَ إِلَى انْتِهَاءِ الرُّكُوعِ، ثُمَّ ضَعْ رَاحَتَيْكَ عَلَى رُكْبَتَيْكَ وَأَصَابِعُكَ مَنْشُورَةٌ، وَانْصِبْ رُكْبَتَيْكَ،"]]},{"id":"bi13_25","label":"آدَابُ الصَّلَاةِ · ٢٥","segs":[["matn","وَمُدَّ ظَهْرَكَ وَعُنُقَكَ وَرَأْسَكَ مُسْتَوِيًا كَالصَّفِيحَةِ الْوَاحِدَةِ، وَجَافِ مِرْفَقَيْكَ عَنْ جَنْبَيْكَ وَالْمَرْأَةُ لَا تَفْعَلُ ذَلِكَ بَلْ تَضُمُّ بَعْضَهَا إِلَى بَعْضٍ، وَقُلْ: سُبْحَانَ رَبِّيَ الْعَظِيمِ - ثَلَاثًا."]]},{"id":"bi13_26","label":"آدَابُ الصَّلَاةِ · ٢٦","segs":[["matn","وَإِنْ كُنْتَ مُنْفَرِدًا، فَالزِّيَادَةُ إِلَى السَّبْعِ وَالْعَشْرِ حَسَنٌ."]]},{"id":"bi13_27","label":"آدَابُ الصَّلَاةِ · ٢٧","segs":[["matn","ثُمَّ ارْفَعْ رَأْسَكَ حَتَّى تَعْتَدِلَ قَائِمًا، وَارْفَعْ يَدَيْكَ قَائِلًا: سَمِعَ اللَّهُ لِمَنْ حَمِدَهُ، فَإِذَا اسْتَوَيْتَ قَائِمًا فَقُلْ: رَبَّنَا لَكَ الْحَمْدُ مِلْءَ السَّمَوَاتِ وَمِلْءَ الْأَرْضِ وَمِلْءَ مَا شِئْتَ مِنْ شَيْءٍ بَعْدُ."]]},{"id":"bi13_28","label":"آدَابُ الصَّلَاةِ · ٢٨","segs":[["matn","وَإِنْ كُنْتَ فِي فَرِيضَةِ الصُّبْحِ فَاقْرَأِ الْقُنُوتَ فِي الرَّكْعَةِ الثَّانِيَةِ فِي اعْتِدَالِكَ مِنَ الرُّكُوعِ."]]},{"id":"bi13_29","label":"آدَابُ الصَّلَاةِ · ٢٩","segs":[["matn","ثُمَّ اسْجُدْ مُكَبِّرًا غَيْرَ رَافِعِ الْيَدَيْنِ، وَضَعْ أَوَّلًا عَلَى الْأَرْضِ رُكْبَتَيْكَ، ثُمَّ يَدَيْكَ ثُمَّ جَبْهَتَكَ مَكْشُوفَةً، وَضَعْ أَنْفَكَ مَعَ الْجَبْهَةِ وَجَافِ مِرْفَقَيْكَ عَنْ جَنْبَيْكَ، وَأَقِلَّ بَطْنَكَ عَنْ فَخِذَيْكَ،"]]},{"id":"bi13_30","label":"آدَابُ الصَّلَاةِ · ٣٠","segs":[["matn","وَالْمَرْأَةُ لَا تَفْعَلُ ذَلِكَ، وَضَعْ يَدَيْكَ عَلَى الْأَرْضِ حَذْوَ مَنْكِبَيْكَ، وَلَا تَفْرِشْ ذِرَاعَيْكَ عَلَى الْأَرْضِ، وَقُلْ: سُبْحَانَ رَبِّيَ الْأَعْلَى - ثَلَاثًا أَوْ سَبْعًا أَوْ عَشْرًا، إِنْ كُنْتَ مُنْفَرِدًا."]]},{"id":"bi13_31","label":"آدَابُ الصَّلَاةِ · ٣١","segs":[["matn","ثُمَّ ارْفَعْ رَأْسَكَ مِنَ السُّجُودِ مُكَبِّرًا حَتَّى تَعْتَدِلَ جَالِسًا، وَاجْلِسْ عَلَى رِجْلِكَ الْيُسْرَى، وَانْصِبْ قَدَمَكَ الْيُمْنَى، وَضَعْ يَدَيْكَ عَلَى فَخِذَيْكَ، وَالْأَصَابِعُ مَنْشُورَةٌ، وَقُلْ: رَبِّ اغْفِرْ لِي، وَارْحَمْنِي، وَارْزُقْنِي، وَاهْدِنِي، وَاجْبُرْنِي وَعَافِنِي وَاعْفُ عَنِّي."]]},{"id":"bi13_32","label":"آدَابُ الصَّلَاةِ · ٣٢","segs":[["matn","ثُمَّ اسْجُدْ سَجْدَةً ثَانِيَةً كَذَلِكَ. ثُمَّ اعْتَدِلْ جَالِسًا لِلِاسْتِرَاحَةِ فِي كُلِّ رَكْعَةٍ لَا تَشَهُّدَ عَقِبَهَا، ثُمَّ تَقُومُ وَتَضَعُ الْيَدَيْنِ عَلَى الْأَرْضِ، وَلَا تُقَدِّمْ إِحْدَى رِجْلَيْكَ فِي حَالِ الِارْتِفَاعِ،"]]},{"id":"bi13_33","label":"آدَابُ الصَّلَاةِ · ٣٣","segs":[["matn","وَابْتَدِئْ بِتَكْبِيرَةِ الِارْتِفَاعِ عِنْدَ الْقُرْبِ مِنْ حَدِّ جِلْسَةِ الِاسْتِرَاحَةِ، وَمُدَّهَا إِلَى انْتِصَافِ ارْتِفَاعِكَ إِلَى قِيَامِكَ وَلْتَكُنْ هَذِهِ الْجِلْسَةُ جِلْسَةً خَفِيفَةً مُخْتَطَفَةً."]]},{"id":"bi13_34","label":"آدَابُ الصَّلَاةِ · ٣٤","segs":[["matn","وَصَلِّ الرَّكْعَةَ الثَّانِيَةَ كَالْأُولَى، وَأَعِدِ التَّعَوُّذَ فِي الِابْتِدَاءِ، ثُمَّ اجْلِسْ فِي الرَّكْعَةِ الثَّانِيَةِ لِلتَّشَهُّدِ الْأَوَّلِ، وَضَعِ الْيَدَ الْيُمْنَى فِي جِلْسَةِ التَّشَهُّدِ الْأَوَّلِ عَلَى الْفَخِذِ الْيُمْنَى مَقْبُوضَةَ الْأَصَابِعِ إِلَّا الْمُسَبِّحَةَ وَالْإِبْهَامَ فَتُرْسِلُهُمَا، وَأَشِرْ بِمُسَبِّحَةِ يُمْنَاكَ عِنْدَ قَوْلِكَ: «إِلَّا اللَّهُ» لَا عِنْدَ قَوْلِكَ: «لَا إِلَهَ»."]]},{"id":"bi13_35","label":"آدَابُ الصَّلَاةِ · ٣٥","segs":[["matn","وَضَعِ الْيَدَ الْيُسْرَى مَنْشُورَةَ الْأَصَابِعِ عَلَى الْفَخِذِ الْيُسْرَى، وَاجْلِسْ عَلَى رِجْلِكَ الْيُسْرَى فِي هَذَا التَّشَهُّدِ كَمَا بَيْنَ السَّجْدَتَيْنِ، وَفِي التَّشَهُّدِ الْأَخِيرِ مُتَوَرِّكًا."]]},{"id":"bi13_36","label":"آدَابُ الصَّلَاةِ · ٣٦","segs":[["matn","وَاسْتَكْمِلِ الدُّعَاءَ الْمَعْرُوفَ الْمَأْثُورَ بَعْدَ الصَّلَاةِ عَلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ."]]},{"id":"bi13_37","label":"آدَابُ الصَّلَاةِ · ٣٧","segs":[["matn","وَاجْلِسْ فِيهِ عَلَى وَرِكِكَ الْأَيْسَرِ، وَضَعْ رِجْلَكَ الْيُسْرَى خَارِجَةً مِنْ تَحْتِكَ، وَانْصِبِ الْقَدَمَ الْيُمْنَى، ثُمَّ قُلْ بَعْدَ الْفَرَاغِ: السَّلَامُ عَلَيْكُمْ وَرَحْمَةُ اللَّهِ - مَرَّتَيْنِ، مِنَ الْجَانِبَيْنِ، وَالْتَفِتْ بِحَيْثُ يُرَى بَيَاضُ خَدِّكَ مِنْ جَانِبَيْكَ، وَانْوِ الْخُرُوجَ مِنَ الصَّلَاةِ، وَانْوِ السَّلَامَ عَلَى مَنْ بِجَانِبِكَ مِنَ الْمَلَائِكَةِ وَالْمُسْلِمِينَ."]]},{"id":"bi13_38","label":"آدَابُ الصَّلَاةِ · ٣٨","segs":[["matn","وَهَذِهِ هَيْئَةُ صَلَاةِ الْمُنْفَرِدِ. وَعِمَادُ الصَّلَاةِ الْخُشُوعُ، وَحُضُورُ الْقَلْبِ مَعَ الْقِرَاءَةِ وَالذِّكْرِ بِالتَّفَهُّمِ."]]},{"id":"bi13_39","label":"آدَابُ الصَّلَاةِ · ٣٩","segs":[["matn","قَالَ الْحَسَنُ الْبَصْرِيُّ - رَحِمَهُ اللَّهُ تَعَالَى: كُلُّ صَلَاةٍ لَا يَحْضُرُ فِيهَا الْقَلْبُ فَهِيَ إِلَى الْعُقُوبَةِ أَسْرَعُ."]]},{"id":"bi13_40","label":"آدَابُ الصَّلَاةِ · ٤٠","segs":[["matn","وَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: «إِنَّ الْعَبْدَ لَيُصَلِّي الصَّلَاةَ فَلَا يُكْتَبُ لَهُ مِنْهَا سُدُسُهَا وَلَا عُشْرُهَا، وَإِنَّمَا يُكْتَبُ لِلْعَبْدِ مِنْ صَلَاتِهِ بِقَدْرِ مَا عَقَلَ مِنْهَا»."]]}],"group":"الْقِسْمُ الْأَوَّلُ فِي الطَّاعَاتِ"},{"id":"bi14","title":"آدَابُ الْإِمَامَةِ وَالْقُدْوَةِ","units":[{"id":"bi14_1","label":"آدَابُ الْإِمَامَةِ وَالْقُدْوَةِ · ١","segs":[["matn","يَنْبَغِي لِلْإِمَامِ أَنْ يُخَفِّفَ الصَّلَاةَ، قَالَ أَنَسُ بْنُ مَالِكٍ رَضِيَ اللَّهُ عَنْهُ: مَا صَلَّيْتُ خَلْفَ أَحَدٍ صَلَاةً أَخَفَّ وَلَا أَتَمَّ مِنْ صَلَاةِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ."]]},{"id":"bi14_2","label":"آدَابُ الْإِمَامَةِ وَالْقُدْوَةِ · ٢","segs":[["matn","وَلَا يُكَبِّرُ مَا لَمْ يَفْرُغِ الْمُؤَذِّنُ مِنَ الْإِقَامَةِ، وَمَا لَمْ تَسْتَوِ الصُّفُوفُ، وَيَرْفَعُ الْإِمَامُ صَوْتَهُ بِالتَّكْبِيرَاتِ، وَلَا يَرْفَعُ الْمَأْمُومُ صَوْتَهُ إِلَّا بِقَدْرِ مَا يُسْمِعُ نَفْسَهُ، وَيَنْوِي الْإِمَامُ الْإِمَامَةَ لِيَنَالَ الْفَضْلَ، فَإِذَا لَمْ يَنْوِ صَحَّتْ صَلَاةُ الْقَوْمِ إِذَا نَوَوُا الِاقْتِدَاءَ بِهِ، وَنَالُوا فَضْلَ الْقُدْوَةِ."]]},{"id":"bi14_3","label":"آدَابُ الْإِمَامَةِ وَالْقُدْوَةِ · ٣","segs":[["matn","وَيُسِرُّ الْإِمَامُ بِدُعَاءِ الِاسْتِفْتَاحِ وَالتَّعَوُّذِ كَالْمُنْفَرِدِ، وَيَجْهَرُ بِالْفَاتِحَةِ وَالسُّورَةِ فِي جَمِيعِ الصُّبْحِ، وَأُولَيَيِ الْمَغْرِبِ وَالْعِشَاءِ، وَكَذَلِكَ الْمُنْفَرِدُ، وَيَجْهَرُ بِقَوْلِهِ: «آمِينَ» فِي الْجَهْرِيَّةِ، وَكَذَلِكَ الْمَأْمُومُ، وَيَقْرِنُ الْمَأْمُومُ تَأْمِينَهُ بِتَأْمِينِ الْإِمَامِ مَعًا لَا تَعْقِيبًا لَهُ،"]]},{"id":"bi14_4","label":"آدَابُ الْإِمَامَةِ وَالْقُدْوَةِ · ٤","segs":[["matn","وَيَسْكُتُ الْإِمَامُ سَكْتَةً عَقِبَ الْفَاتِحَةِ لِيَثُوبَ إِلَيْهِ نَفَسُهُ، وَيَقْرَأُ الْمَأْمُومُ الْفَاتِحَةَ فِي الْجَهْرِيَّةِ فِي هَذِهِ السَّكْتَةِ، لِيَتَمَكَّنَ مِنَ الِاسْتِمَاعِ عِنْدَ قِرَاءَةِ الْإِمَامِ، وَلَا يَقْرَأُ الْمَأْمُومُ السُّورَةَ فِي الْجَهْرِيَّةِ إِلَّا إِذَا لَمْ يَسْمَعْ صَوْتَ الْإِمَامِ."]]},{"id":"bi14_5","label":"آدَابُ الْإِمَامَةِ وَالْقُدْوَةِ · ٥","segs":[["matn","وَلَا يَزِيدُ الْإِمَامُ عَلَى ثَلَاثٍ فِي تَسْبِيحَاتِ الرُّكُوعِ وَالسُّجُودِ، وَلَا يَزِيدُ فِي التَّشَهُّدِ الْأَوَّلِ بَعْدَ قَوْلِهِ: «اللَّهُمَّ صَلِّ عَلَى مُحَمَّدٍ» وَيَقْتَصِرُ فِي الرَّكْعَتَيْنِ الْأَخِيرَتَيْنِ عَلَى الْفَاتِحَةِ، وَلَا يُطَوِّلُ عَلَى الْقَوْمِ،"]]},{"id":"bi14_6","label":"آدَابُ الْإِمَامَةِ وَالْقُدْوَةِ · ٦","segs":[["matn","وَلَا يَزِيدُ دُعَاؤُهُ فِي التَّشَهُّدِ الْأَخِيرِ عَلَى قَدْرِ تَشَهُّدِهِ وَصَلَاتِهِ عَلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، وَيَنْوِي الْإِمَامُ عِنْدَ التَّسْلِيمِ السَّلَامَ عَلَى الْقَوْمِ، وَيَنْوِي الْقَوْمُ بِتَسْلِيمِهِمْ جَوَابَهُ."]]},{"id":"bi14_7","label":"آدَابُ الْإِمَامَةِ وَالْقُدْوَةِ · ٧","segs":[["matn","وَيَلْبَثُ الْإِمَامُ سَاعَةً بَعْدَ مَا يَفْرُغُ مِنَ السَّلَامِ وَيُقْبِلُ عَلَى النَّاسِ بِوَجْهِهِ، وَلَا يَلْتَفِتُ إِنْ كَانَ خَلْفَهُ نِسَاءٌ حَتَّى يَنْصَرِفْنَ أَوَّلًا."]]},{"id":"bi14_8","label":"آدَابُ الْإِمَامَةِ وَالْقُدْوَةِ · ٨","segs":[["matn","وَلَا يَقُومُ أَحَدٌ مِنَ الْقَوْمِ حَتَّى يَقُومَ الْإِمَامُ."]]},{"id":"bi14_9","label":"آدَابُ الْإِمَامَةِ وَالْقُدْوَةِ · ٩","segs":[["matn","وَيَنْصَرِفُ الْإِمَامُ حَيْثُ شَاءَ عَنْ يَمِينِهِ أَوْ شِمَالِهِ، وَالْيَمِينُ أَحَبُّ إِلَيَّ."]]},{"id":"bi14_10","label":"آدَابُ الْإِمَامَةِ وَالْقُدْوَةِ · ١٠","segs":[["matn","وَلَا يَخُصُّ الْإِمَامُ نَفْسَهُ بِالدُّعَاءِ فِي قُنُوتِ الصُّبْحِ، بَلْ يَقُولُ: «اللَّهُمَّ اهْدِنَا» وَيَجْهَرُ بِهِ، وَيُؤَمِّنُ الْقَوْمُ وَلَا يَرْفَعُونَ أَيْدِيَهُمْ إِذْ لَمْ يَثْبُتْ ذَلِكَ فِي الْأَخْبَارِ، وَيَقْرَأُ الْمَأْمُومُ بَقِيَّةَ الْقُنُوتِ مِنْ قَوْلِهِ: «إِنَّكَ تَقْضِي وَلَا يُقْضَى عَلَيْكَ»."]]},{"id":"bi14_11","label":"آدَابُ الْإِمَامَةِ وَالْقُدْوَةِ · ١١","segs":[["matn","وَلَا يَقِفُ الْمَأْمُومُ وَحْدَهُ، بَلْ يَدْخُلُ فِي الصَّفِّ، أَوْ يَجُرُّ إِلَى نَفْسِهِ غَيْرَهُ، وَلَا يَنْبَغِي لِلْمَأْمُومِ أَنْ يَتَقَدَّمَ عَلَى الْإِمَامِ فِي أَفْعَالِهِ أَوْ يُسَاوِيَهُ،"]]},{"id":"bi14_12","label":"آدَابُ الْإِمَامَةِ وَالْقُدْوَةِ · ١٢","segs":[["matn","بَلْ يَنْبَغِي أَنْ يَتَأَخَّرَ عَنْهُ، وَلَا يَهْوِي لِلرُّكُوعِ إِلَّا إِذَا انْتَهَى الْإِمَامُ إِلَى حَدِّ الرُّكُوعِ، وَلَا يَهْوِي لِلسُّجُودِ مَا لَمْ تَصِلْ جَبْهَةُ الْإِمَامِ إِلَى الْأَرْضِ."]]}],"group":"الْقِسْمُ الْأَوَّلُ فِي الطَّاعَاتِ"},{"id":"bi15","title":"آدَابُ الْجُمُعَةِ","units":[{"id":"bi15_1","label":"آدَابُ الْجُمُعَةِ · ١","segs":[["matn","اعْلَمْ أَنَّ الْجُمُعَةَ عِيدُ الْمُؤْمِنِينَ، وَهُوَ يَوْمٌ شَرِيفٌ خَصَّ اللَّهُ عَزَّ وَجَلَّ بِهِ هَذِهِ الْأُمَّةَ، وَفِيهِ سَاعَةٌ مُبْهَمَةٌ لَا يُوَافِقُهَا عَبْدٌ مُسْلِمٌ يَسْأَلُ اللَّهَ تَعَالَى فِيهَا حَاجَةً إِلَّا أَعْطَاهُ إِيَّاهَا."]]},{"id":"bi15_2","label":"آدَابُ الْجُمُعَةِ · ٢","segs":[["matn","فَاسْتَعِدَّ لَهَا مِنْ يَوْمِ الْخَمِيسِ؛ بِتَنْظِيفِ الثِّيَابِ، وَبِكَثْرَةِ التَّسْبِيحِ وَالِاسْتِغْفَارِ عَشِيَّةَ الْخَمِيسِ، فَإِنَّهَا سَاعَةٌ تُوَازِي فِي الْفَضْلِ سَاعَةَ يَوْمِ الْجُمُعَةِ."]]},{"id":"bi15_3","label":"آدَابُ الْجُمُعَةِ · ٣","segs":[["matn","وَانْوِ صَوْمَ يَوْمِ الْجُمُعَةِ، لَكِنْ مَعَ الْخَمِيسِ أَوِ السَّبْتِ؛"]]},{"id":"bi15_4","label":"آدَابُ الْجُمُعَةِ · ٤","segs":[["matn","إِذْ جَاءَ فِي إِفْرَادِهِ نَهْيٌ. فَإِذَا طَلَعَ عَلَيْكَ الصُّبْحُ، فَاغْتَسِلْ؛"]]},{"id":"bi15_5","label":"آدَابُ الْجُمُعَةِ · ٥","segs":[["matn","«غُسْلُ الْجُمُعَةِ وَاجِبٌ عَلَى كُلِّ مُحْتَلِمٍ» أَيْ ثَابِتٌ مُؤَكَّدٌ."]]},{"id":"bi15_6","label":"آدَابُ الْجُمُعَةِ · ٦","segs":[["matn","ثُمَّ تَزَيَّنْ بِالثِّيَابِ الْبِيضِ؛ فَإِنَّهَا أَحَبُّ الثِّيَابِ إِلَى اللَّهِ تَعَالَى، وَاسْتَعْمِلْ مِنَ الطِّيبِ أَطْيَبَ مَا عِنْدَكَ، وَبَالِغْ فِي تَنْظِيفِ بَدَنِكَ بِالْحَلْقِ وَالْقَصِّ وَالسِّوَاكِ وَسَائِرِ أَنْوَاعِ النَّظَافَةِ وَتَطْيِيبِ الرَّائِحَةِ."]]},{"id":"bi15_7","label":"آدَابُ الْجُمُعَةِ · ٧","segs":[["matn","ثُمَّ بَكِّرْ إِلَى الْجَامِعِ، وَاسْعَ إِلَيْهَا عَلَى الْهِينَةِ وَالسَّكِينَةِ، فَقَدْ قَالَ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: «مَنْ رَاحَ إِلَى الْجُمُعَةِ فِي السَّاعَةِ الْأُولَى فَكَأَنَّمَا قَرَّبَ بَدَنَةً، وَمَنْ رَاحَ فِي السَّاعَةِ الثَّانِيَةِ فَكَأَنَّمَا قَرَّبَ بَقَرَةً،"]]},{"id":"bi15_8","label":"آدَابُ الْجُمُعَةِ · ٨","segs":[["matn","وَمَنْ رَاحَ فِي السَّاعَةِ الثَّالِثَةِ فَكَأَنَّمَا قَرَّبَ كَبْشًا أَقْرَنَ، وَمَنْ رَاحَ فِي السَّاعَةِ الرَّابِعَةِ فَكَأَنَّمَا قَرَّبَ دَجَاجَةً، وَمَنْ رَاحَ فِي السَّاعَةِ الْخَامِسَةِ فَكَأَنَّمَا قَرَّبَ بَيْضَةً."]]},{"id":"bi15_9","label":"آدَابُ الْجُمُعَةِ · ٩","segs":[["matn","فَإِذَا خَرَجَ الْإِمَامُ طُوِيَتِ الصُّحُفُ، وَرُفِعَتِ الْأَقْلَامُ، وَاجْتَمَعَتِ الْمَلَائِكَةُ عِنْدَ الْمِنْبَرِ يَسْتَمِعُونَ الذِّكْرَ»."]]},{"id":"bi15_10","label":"آدَابُ الْجُمُعَةِ · ١٠","segs":[["matn","وَيُقَالُ إِنَّ النَّاسَ فِي قُرْبِهِمْ عِنْدَ النَّظَرِ إِلَى وَجْهِ اللَّهِ تَعَالَى عَلَى قَدْرِ بُكُورِهِمْ إِلَى الْجُمُعَةِ."]]},{"id":"bi15_11","label":"آدَابُ الْجُمُعَةِ · ١١","segs":[["matn","ثُمَّ إِذَا دَخَلْتَ الْجَامِعَ، فَاطْلُبِ الصَّفَّ الْأَوَّلَ، فَإِذَا اجْتَمَعَ النَّاسُ فَلَا تَتَخَطَّ رِقَابَهُمْ، وَلَا تَمُرَّ بَيْنَ أَيْدِيهِمْ وَهُمْ يُصَلُّونَ، وَاجْلِسْ بِقُرْبِ حَائِطٍ أَوْ أُسْطُوَانَةٍ حَتَّى لَا يَمُرُّوا بَيْنَ يَدَيْكَ، وَلَا تَقْعُدْ حَتَّى تُصَلِّيَ التَّحِيَّةَ،"]]},{"id":"bi15_12","label":"آدَابُ الْجُمُعَةِ · ١٢","segs":[["matn","وَالْأَحْسَنُ أَنْ تُصَلِّيَ أَرْبَعَ رَكَعَاتٍ، تَقْرَأُ فِي كُلِّ رَكْعَةٍ بَعْدَ الْفَاتِحَةِ الْإِخْلَاصَ خَمْسِينَ مَرَّةً، فَفِي الْخَبَرِ: «أَنَّ مَنْ فَعَلَ ذَلِكَ لَمْ يَمُتْ حَتَّى يَرَى مَقْعَدَهُ مِنَ الْجَنَّةِ أَوْ يُرَى لَهُ»."]]},{"id":"bi15_13","label":"آدَابُ الْجُمُعَةِ · ١٣","segs":[["matn","وَلَا تَتْرُكِ التَّحِيَّةَ وَإِنْ كَانَ الْإِمَامُ يَخْطُبُ. وَيُسْتَحَبُّ فِي هَذَا الْيَوْمِ أَوْ فِي لَيْلَتِهِ أَنْ يُصَلَّى أَرْبَعُ رَكَعَاتٍ بِأَرْبَعِ سُوَرٍ: سُورَةِ الْأَنْعَامِ، وَالْكَهْفِ، وَطه، وَيس، فَإِنْ لَمْ تَقْدِرْ فَسُورَةَ يس وَالدُّخَانِ، وَ «الم» السَّجْدَةِ، وَسُورَةَ الْمُلْكِ."]]},{"id":"bi15_14","label":"آدَابُ الْجُمُعَةِ · ١٤","segs":[["matn","وَلَا تَدَعْ قِرَاءَةَ هَذِهِ السُّورَةِ لَيْلَةَ الْجُمُعَةِ؛ فَفِيهَا فَضْلٌ كَثِيرٌ."]]},{"id":"bi15_15","label":"آدَابُ الْجُمُعَةِ · ١٥","segs":[["matn","وَمَنْ لَمْ يُحْسِنْ ذَلِكَ فَلْيُكْثِرْ مِنْ قِرَاءَةِ سُورَةِ الْإِخْلَاصِ."]]},{"id":"bi15_16","label":"آدَابُ الْجُمُعَةِ · ١٦","segs":[["matn","وَأَكْثِرْ مِنَ الصَّلَاةِ عَلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي هَذَا الْيَوْمِ خَاصَّةً."]]},{"id":"bi15_17","label":"آدَابُ الْجُمُعَةِ · ١٧","segs":[["matn","وَمَتَى خَرَجَ الْإِمَامُ، فَاقْطَعِ الصَّلَاةَ وَالْكَلَامَ، وَاشْتَغِلْ بِجَوَابِ الْمُؤَذِّنِ ثُمَّ اسْتِمَاعِ الْخُطْبَةِ وَالِاتِّعَاظِ بِهَا، وَدَعِ الْكَلَامَ رَأْسًا فِي الْخُطْبَةِ، فَفِي الْخَبَرِ: «أَنَّ مَنْ قَالَ لِصَاحِبِهِ - وَالْإِمَامُ يَخْطُبُ - أَنْصِتْ، أَوْ صَهْ؛"]]},{"id":"bi15_18","label":"آدَابُ الْجُمُعَةِ · ١٨","segs":[["matn","فَقَدْ لَغَا، وَمَنْ لَغَا فَلَا جُمُعَةَ لَهُ»، أَيْ لِأَنَّ قَوْلَهُ أَنْصِتْ: كَلَامٌ، فَيَنْبَغِي أَنْ يَنْهَى غَيْرَهُ بِالْإِشَارَةِ لَا بِاللَّفْظِ."]]},{"id":"bi15_19","label":"آدَابُ الْجُمُعَةِ · ١٩","segs":[["matn","ثُمَّ اقْتَدِ بِالْإِمَامِ كَمَا سَبَقَ. فَإِذَا فَرَغْتَ وَسَلَّمْتَ، فَاقْرَأِ الْفَاتِحَةَ قَبْلَ أَنْ تَتَكَلَّمَ سَبْعَ مَرَّاتٍ، وَالْإِخْلَاصَ سَبْعًا، وَالْمُعَوِّذَتَيْنِ سَبْعًا سَبْعًا، فَذَلِكَ يَعْصِمُكَ مِنَ الْجُمُعَةِ إِلَى الْجُمُعَةِ الْأُخْرَى،"]]},{"id":"bi15_20","label":"آدَابُ الْجُمُعَةِ · ٢٠","segs":[["matn","وَيَكُونُ حِرْزًا لَكَ مِنَ الشَّيْطَانِ، وَقُلْ بَعْدَ ذَلِكَ: يَا غَنِيُّ، يَا حَمِيدُ، يَا مُبْدِئُ، يَا مُعِيدُ، يَا رَحِيمُ، يَا وَدُودُ؛"]]},{"id":"bi15_21","label":"آدَابُ الْجُمُعَةِ · ٢١","segs":[["matn","أَغْنِنِي بِحَلَالِكَ عَنْ حَرَامِكَ، وَبِطَاعَتِكَ عَنْ مَعْصِيَتِكَ، وَبِفَضْلِكَ عَمَّنْ سِوَاكَ."]]},{"id":"bi15_22","label":"آدَابُ الْجُمُعَةِ · ٢٢","segs":[["matn","ثُمَّ صَلِّ بَعْدَ الْجُمُعَةِ رَكْعَتَيْنِ أَوْ أَرْبَعًا أَوْ سِتًّا، مَثْنَى، مَثْنَى، فَكُلُّ ذَلِكَ مَرْوِيٌّ عَنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي أَحْوَالٍ مُخْتَلِفَةٍ."]]},{"id":"bi15_23","label":"آدَابُ الْجُمُعَةِ · ٢٣","segs":[["matn","ثُمَّ لَازِمِ الْمَسْجِدَ إِلَى الْمَغْرِبِ أَوْ إِلَى الْعَصْرِ، وَكُنْ حَسَنَ الْمُرَاقَبَةِ لِلسَّاعَةِ الشَّرِيفَةِ؛"]]},{"id":"bi15_24","label":"آدَابُ الْجُمُعَةِ · ٢٤","segs":[["matn","فَإِنَّهَا مُبْهَمَةٌ فِي جَمِيعِ الْيَوْمِ، فَعَسَاكَ أَنْ تُدْرِكَهَا وَأَنْتَ خَاشِعٌ لِلَّهِ تَعَالَى مُتَذَلِّلٌ مُتَضَرِّعٌ."]]},{"id":"bi15_25","label":"آدَابُ الْجُمُعَةِ · ٢٥","segs":[["matn","وَلَا تَحْضُرْ فِي الْجَامِعِ مَجَالِسَ الْحِلَقِ، وَلَا مَجَالِسَ الْقُصَّاصِ، بَلْ مَجْلِسَ الْعِلْمِ النَّافِعِ، وَهُوَ الَّذِي يَزِيدُ فِي خَوْفِكَ مِنَ اللَّهِ تَعَالَى، وَيَنْقُصُ مِنْ رَغْبَتِكَ فِي الدُّنْيَا، فَكُلُّ عِلْمٍ لَا يَدْعُوكَ مِنَ الدُّنْيَا إِلَى الْآخِرَةِ فَالْجَهْلُ أَعْوَدُ عَلَيْكَ مِنْهُ؛"]]},{"id":"bi15_26","label":"آدَابُ الْجُمُعَةِ · ٢٦","segs":[["matn","فَاسْتَعِذْ بِاللَّهِ مِنْ عِلْمٍ لَا يَنْفَعُ. وَأَكْثِرْ مِنَ الدُّعَاءِ عِنْدَ طُلُوعِ الشَّمْسِ، وَعِنْدَ الزَّوَالِ، وَعِنْدَ الْغُرُوبِ، وَعِنْدَ الْإِقَامَةِ، وَعِنْدَ صُعُودِ الْخَطِيبِ الْمِنْبَرَ، وَعِنْدَ قِيَامِ النَّاسِ إِلَى الصَّلَاةِ، فَيُوشِكُ أَنْ تَكُونَ السَّاعَةُ الشَّرِيفَةُ فِي بَعْضِ هَذِهِ الْأَوْقَاتِ."]]},{"id":"bi15_27","label":"آدَابُ الْجُمُعَةِ · ٢٧","segs":[["matn","وَاجْتَهِدْ أَنْ تَتَصَدَّقَ فِي هَذَا الْيَوْمِ بِمَا تَقْدِرُ عَلَيْهِ وَإِنْ قَلَّ، فَتَجْمَعَ بَيْنَ الصَّلَاةِ وَالصَّوْمِ وَالصَّدَقَةِ وَالْقِرَاءَةِ وَالذِّكْرِ وَالِاعْتِكَافِ وَالرِّبَاطِ."]]},{"id":"bi15_28","label":"آدَابُ الْجُمُعَةِ · ٢٨","segs":[["matn","وَاجْعَلْ هَذَا الْيَوْمَ مِنَ الْأُسْبُوعِ خَاصَّةً لِآخِرَتِكَ؛ فَعَسَاهُ أَنْ يَكُونَ كَفَّارَةً لِبَقِيَّةِ الْأُسْبُوعِ."]]}],"group":"الْقِسْمُ الْأَوَّلُ فِي الطَّاعَاتِ"},{"id":"bi16","title":"آدَابُ الصِّيَامِ","units":[{"id":"bi16_1","label":"آدَابُ الصِّيَامِ · ١","segs":[["matn","لَا يَنْبَغِي أَنْ تَقْتَصِرَ عَلَى صَوْمِ رَمَضَانَ فَتَتْرُكَ التِّجَارَةَ بِالنَّوَافِلِ، وَكَسْبَ الدَّرَجَاتِ الْعَالِيَةِ فِي الْفَرَادِيسِ؛"]]},{"id":"bi16_2","label":"آدَابُ الصِّيَامِ · ٢","segs":[["matn","فَتَتَحَسَّرَ إِذْ نَظَرْتَ إِلَى مَنَازِلِ الصَّائِمِينَ، كَمَا تَنْظُرُ إِلَى الْكَوَاكِبِ الدُّرِّيَّةِ، وَهُمْ فِي أَعْلَى عِلِّيِّينَ."]]},{"id":"bi16_3","label":"آدَابُ الصِّيَامِ · ٣","segs":[["matn","وَالْأَيَّامُ الْفَاضِلَةُ الَّتِي شَهِدَتِ الْأَخْبَارُ بِشَرَفِهَا وَفَضْلِهَا، وَبِجَزَالَةِ الثَّوَابِ فِي صِيَامِهَا: يَوْمُ عَرَفَةَ لِغَيْرِ الْحَاجِّ، وَيَوْمُ عَاشُورَاءَ، وَالْعَشْرُ الْأُوَلُ مِنْ ذِي الْحِجَّةِ، وَالْعَشْرُ الْأُوَلُ مِنَ الْمُحَرَّمِ،"]]},{"id":"bi16_4","label":"آدَابُ الصِّيَامِ · ٤","segs":[["matn","وَرَجَبٌ وَشَعْبَانُ، وَصَوْمُ الْأَشْهُرِ الْحُرُمِ مِنَ الْفَضَائِلِ، وَهِيَ ذُو الْقَعْدَةِ وَذُو الْحِجَّةِ وَالْمُحَرَّمُ وَرَجَبٌ، وَاحِدٌ فَرْدٌ وَثَلَاثَةٌ سَرْدٌ، وَهَذِهِ فِي السَّنَةِ."]]},{"id":"bi16_5","label":"آدَابُ الصِّيَامِ · ٥","segs":[["matn","وَأَمَّا فِي الشَّهْرِ فَأَوَّلُ الشَّهْرِ وَأَوْسَطُهُ وَآخِرُهُ، وَالْأَيَّامُ الْبِيضُ وَهِيَ الثَّالِثَ عَشَرَ وَالرَّابِعَ عَشَرَ وَالْخَامِسَ عَشَرَ، وَأَمَّا فِي الْأُسْبُوعِ فَيَوْمُ الِاثْنَيْنِ وَالْخَمِيسِ وَالْجُمُعَةِ؛"]]},{"id":"bi16_6","label":"آدَابُ الصِّيَامِ · ٦","segs":[["matn","فَتُكَفَّرُ ذُنُوبُ الْأُسْبُوعِ بِصَوْمِ الِاثْنَيْنِ وَالْخَمِيسِ وَالْجُمُعَةِ، وَتُكَفَّرُ ذُنُوبُ الشَّهْرِ بِالْيَوْمِ الْأَوَّلِ وَالْيَوْمِ الْأَوْسَطِ وَالْيَوْمِ الْآخِرِ وَالْأَيَّامِ الْبِيضِ، وَتُكَفَّرُ ذُنُوبُ السَّنَةِ بِصِيَامِ هَذِهِ الْأَيَّامِ وَالْأَشْهُرِ الْمَذْكُورَةِ."]]},{"id":"bi16_7","label":"آدَابُ الصِّيَامِ · ٧","segs":[["matn","وَلَا تَظُنَّ إِذَا صُمْتَ أَنَّ الصَّوْمَ هُوَ تَرْكُ الطَّعَامِ وَالشَّرَابِ وَالْوِقَاعِ فَقَطْ، فَقَدْ قَالَ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: «كَمْ مِنْ صَائِمٍ لَيْسَ لَهُ مِنْ صِيَامِهِ إِلَّا الْجُوعُ وَالْعَطَشُ»،"]]},{"id":"bi16_8","label":"آدَابُ الصِّيَامِ · ٨","segs":[["matn","بَلْ تَمَامُ الصَّوْمِ بِكَفِّ الْجَوَارِحِ كُلِّهَا عَمَّا يَكْرَهُهُ اللَّهُ تَعَالَى، بَلْ يَنْبَغِي أَنْ تَحْفَظَ الْعَيْنَ عَنِ النَّظَرِ إِلَى الْمَكَارِهِ، وَاللِّسَانَ عَنِ النُّطْقِ بِمَا لَا يَعْنِيكَ، وَالْأُذُنَ عَنِ الِاسْتِمَاعِ إِلَى مَا حَرَّمَهُ اللَّهُ؛"]]},{"id":"bi16_9","label":"آدَابُ الصِّيَامِ · ٩","segs":[["matn","فَإِنَّ الْمُسْتَمِعَ شَرِيكُ الْقَائِلِ وَهُوَ أَحَدُ الْمُغْتَابَيْنِ، وَكَذَلِكَ تَكُفُّ جَمِيعَ الْجَوَارِحِ كَمَا تَكُفُّ الْبَطْنَ وَالْفَرْجَ، فَفِي الْخَبَرِ «خَمْسٌ يُفَطِّرْنَ الصَّائِمَ: الْكَذِبُ، وَالْغِيبَةُ، وَالنَّمِيمَةُ، وَالْيَمِينُ الْكَاذِبَةُ، وَالنَّظَرُ بِشَهْوَةٍ»،"]]},{"id":"bi16_10","label":"آدَابُ الصِّيَامِ · ١٠","segs":[["matn","وَقَالَ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: «إِنَّمَا الصَّوْمُ جُنَّةٌ فَإِذَا كَانَ أَحَدُكُمْ صَائِمًا فَلَا يَرْفُثْ، وَلَا يَفْسُقْ، وَلَا يَجْهَلْ، فَإِنِ امْرُؤٌ قَاتَلَهُ أَوْ شَاتَمَهُ فَلْيَقُلْ: إِنِّي صَائِمٌ»."]]},{"id":"bi16_11","label":"آدَابُ الصِّيَامِ · ١١","segs":[["matn","ثُمَّ اجْتَهِدْ أَنْ تُفْطِرَ عَلَى طَعَامٍ حَلَالٍ، وَلَا تَسْتَكْثِرْ فَتَزِيدَ عَلَى مَا تَأْكُلُهُ كُلَّ لَيْلَةٍ، فَلَا فَرْقَ إِذَا اسْتَوْفَيْتَ مَا تَعْتَادُ أَنْ تَأْكُلَهُ دَفْعَتَيْنِ فِي دَفْعَةٍ وَاحِدَةٍ، وَإِنَّمَا الْمَقْصُودُ بِالصِّيَامِ كَسْرُ شَهْوَتِكَ، وَتَضْعِيفُ قُوَّتِكَ لِتَقْوَى بِهَا عَلَى التَّقْوَى."]]},{"id":"bi16_12","label":"آدَابُ الصِّيَامِ · ١٢","segs":[["matn","فَإِذَا أَكَلْتَ عَشِيَّةً مَا تَدَارَكْتَ بِهِ مَا فَاتَكَ ضَحْوَةً، فَلَا فَائِدَةَ فِي صَوْمِكَ، وَقَدْ ثَقُلَتْ عَلَيْكَ مَعِدَتُكَ، وَمَا وِعَاءٌ أَبْغَضَ إِلَى اللَّهِ تَعَالَى مِنْ بَطْنٍ مُلِئَ مِنْ حَلَالٍ، فَكَيْفَ إِذَا مُلِئَ مِنْ حَرَامٍ؟"]]},{"id":"bi16_13","label":"آدَابُ الصِّيَامِ · ١٣","segs":[["matn","فَإِذَا عَرَفْتَ مَعْنَى الصَّوْمِ فَاسْتَكْثِرْ مِنْهُ مَا اسْتَطَعْتَ، فَإِنَّهُ أَسَاسُ الْعِبَادَاتِ، وَمِفْتَاحُ الْقُرُبَاتِ؛"]]},{"id":"bi16_14","label":"آدَابُ الصِّيَامِ · ١٤","segs":[["matn","قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: «قَالَ اللَّهُ تَعَالَى: كُلُّ حَسَنَةٍ بِعَشْرِ أَمْثَالِهَا إِلَى سَبْعِمِائَةِ ضِعْفٍ إِلَّا الصَّوْمَ، فَإِنَّهُ لِي وَأَنَا أَجْزِي بِهِ»، وَقَالَ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: «وَالَّذِي نَفْسِي بِيَدِهِ لَخُلُوفُ فَمِ الصَّائِمِ أَطْيَبُ عِنْدَ اللَّهِ مِنْ رِيحِ الْمِسْكِ،"]]},{"id":"bi16_15","label":"آدَابُ الصِّيَامِ · ١٥","segs":[["matn","يَقُولُ اللَّهُ عَزَّ وَجَلَّ: إِنَّمَا يَذَرُ شَهْوَتَهُ وَطَعَامَهُ وَشَرَابَهُ مِنْ أَجْلِي، فَالصَّوْمُ لِي وَأَنَا أَجْزِي بِهِ» وَقَالَ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: «لِلْجَنَّةِ بَابٌ يُقَالُ لَهُ الرَّيَّانُ، لَا يَدْخُلُهُ إِلَّا الصَّائِمُونَ»."]]},{"id":"bi16_16","label":"آدَابُ الصِّيَامِ · ١٦","segs":[["matn","فَهَذَا الْقَدْرُ مِنْ شَرْحِ الطَّاعَاتِ يَكْفِيكَ مِنْ بِدَايَةِ الْهِدَايَةِ، فَإِذَا احْتَجْتَ إِلَى الزَّكَاةِ، وَالْحَجِّ، أَوْ إِلَى مَزِيدِ شَرْحِ الصَّلَاةِ وَالصِّيَامِ، فَاطْلُبْهُ مِمَّا أَوْرَدْنَاهُ فِي كِتَابِنَا «إِحْيَاءِ عُلُومِ الدِّينِ»."]]}],"group":"الْقِسْمُ الْأَوَّلُ فِي الطَّاعَاتِ"},{"id":"bi17","title":"تَوْطِئَةٌ","units":[{"id":"bi17_1","label":"تَوْطِئَةٌ · ١","segs":[["matn","اعْلَمْ أَنَّ لِلدِّينِ شَطْرَيْنِ، أَحَدُهُمَا: تَرْكُ الْمَنَاهِي، وَالْآخَرُ: فِعْلُ الطَّاعَاتِ، وَتَرْكُ الْمَنَاهِي هُوَ الْأَشَدُّ؛"]]},{"id":"bi17_2","label":"تَوْطِئَةٌ · ٢","segs":[["matn","فَإِنَّ الطَّاعَاتِ يَقْدِرُ عَلَيْهَا كُلُّ وَاحِدٍ، وَتَرْكُ الشَّهَوَاتِ لَا يَقْدِرُ عَلَيْهِ إِلَّا الصِّدِّيقُونَ، فَلِذَلِكَ قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: «الْمُهَاجِرُ مَنْ هَجَرَ السُّوءَ، وَالْمُجَاهِدُ مَنْ جَاهَدَ هَوَاهُ»."]]},{"id":"bi17_3","label":"تَوْطِئَةٌ · ٣","segs":[["matn","وَاعْلَمْ أَنَّكَ إِنَّمَا تَعْصِي اللَّهَ بِجَوَارِحِكَ، وَهِيَ نِعْمَةٌ مِنَ اللَّهِ عَلَيْكَ وَأَمَانَةٌ لَدَيْكَ، فَاسْتِعَانَتُكَ بِنِعْمَةِ اللَّهِ عَلَى مَعْصِيَتِهِ غَايَةُ الْكُفْرَانِ، وَخِيَانَتُكَ فِي أَمَانَةٍ اسْتَوْدَعَكَهَا اللَّهُ غَايَةُ الطُّغْيَانِ؛"]]},{"id":"bi17_4","label":"تَوْطِئَةٌ · ٤","segs":[["matn","فَأَعْضَاؤُكَ رَعَايَاكَ، فَانْظُرْ كَيْفَ تَرْعَاهَا؛ فَكُلُّكُمْ رَاعٍ، وَكُلُّكُمْ مَسْؤُولٌ عَنْ رَعِيَّتِهِ."]]},{"id":"bi17_5","label":"تَوْطِئَةٌ · ٥","segs":[["matn","وَاعْلَمْ أَنَّ جَمِيعَ أَعْضَائِكَ سَتَشْهَدُ عَلَيْكَ فِي عَرَصَاتِ الْقِيَامَةِ بِلِسَانٍ طَلْقٍ ذَلْقٍ، تَفْضَحُكَ بِهِ عَلَى رُؤُوسِ الْخَلَائِقِ، قَالَ اللَّهُ تَعَالَى: ﴿يَوْمَ تَشْهَدُ عَلَيْهِمْ أَلْسِنَتُهُمْ وَأَيْدِيهِمْ وَأَرْجُلُهُم بِمَا كَانُوا يَعْمَلُونَ﴾، وَقَالَ اللَّهُ تَعَالَى: ﴿الْيَوْمَ نَخْتِمُ عَلَىٰ أَفْوَاهِهِمْ وَتُكَلِّمُنَا أَيْدِيهِمْ وَتَشْهَدُ أَرْجُلُهُم بِمَا كَانُوا يَكْسِبُونَ﴾."]]},{"id":"bi17_6","label":"تَوْطِئَةٌ · ٦","segs":[["matn","فَاحْفَظْ يَا مِسْكِينُ جَمِيعَ بَدَنِكَ مِنَ الْمَعَاصِي، وَخُصُوصًا أَعْضَاءَكَ السَّبْعَةَ؛"]]},{"id":"bi17_7","label":"تَوْطِئَةٌ · ٧","segs":[["matn","فَإِنَّ جَهَنَّمَ لَهَا سَبْعَةُ أَبْوَابٍ لِكُلِّ بَابٍ مِنْهُمْ جُزْءٌ مَقْسُومٌ، وَلَا يَتَعَيَّنُ لِتِلْكَ الْأَبْوَابِ إِلَّا مَنْ عَصَى اللَّهَ تَعَالَى بِهَذِهِ الْأَعْضَاءِ السَّبْعَةِ، وَهِيَ: الْعَيْنُ، وَالْأُذُنُ، وَاللِّسَانُ، وَالْبَطْنُ، وَالْفَرْجُ، وَالْيَدُ، وَالرِّجْلُ."]]}],"group":"الْقِسْمُ الثَّانِي الْقَوْلُ فِي اجْتِنَابِ الْمَعَاصِي"},{"id":"bi18","title":"آدَابُ الْعَيْنِ","units":[{"id":"bi18_1","label":"آدَابُ الْعَيْنِ · ١","segs":[["matn","أَمَّا الْعَيْنُ: فَإِنَّمَا خُلِقَتْ لَكَ لِتَهْتَدِيَ بِهَا فِي الظُّلُمَاتِ، وَتَسْتَعِينَ بِهَا فِي الْحَاجَاتِ، وَتَنْظُرَ بِهَا إِلَى عَجَائِبِ مَلَكُوتِ الْأَرْضِ وَالسَّمَوَاتِ، وَتَعْتَبِرَ بِمَا فِيهَا مِنَ الْآيَاتِ؛"]]},{"id":"bi18_2","label":"آدَابُ الْعَيْنِ · ٢","segs":[["matn","فَاحْفَظْهَا عَنْ أَرْبَعٍ: أَنْ تَنْظُرَ بِهَا إِلَى غَيْرِ مَحْرَمٍ، أَوْ إِلَى صُورَةٍ مَلِيحَةٍ بِشَهْوَةِ نَفْسٍ، أَوْ تَنْظُرَ بِهَا إِلَى مُسْلِمٍ بِعَيْنِ الِاحْتِقَارِ، أَوْ تَطَّلِعَ بِهَا عَلَى عَيْبِ مُسْلِمٍ."]]}],"group":"الْقِسْمُ الثَّانِي الْقَوْلُ فِي اجْتِنَابِ الْمَعَاصِي"},{"id":"bi19","title":"آدَابُ الْأُذُنِ","units":[{"id":"bi19_1","label":"آدَابُ الْأُذُنِ · ١","segs":[["matn","وَأَمَّا الْأُذُنُ: فَاحْفَظْهَا عَنْ أَنْ تُصْغِيَ بِهَا إِلَى الْبِدْعَةِ، أَوِ الْغِيبَةِ، أَوِ الْفُحْشِ، أَوِ الْخَوْضِ فِي الْبَاطِلِ، أَوْ ذِكْرِ مَسَاوِئِ النَّاسِ؛"]]},{"id":"bi19_2","label":"آدَابُ الْأُذُنِ · ٢","segs":[["matn","فَإِنَّمَا خُلِقَتْ لَكَ لِتَسْمَعَ بِهَا كَلَامَ اللَّهِ تَعَالَى، وَسُنَّةَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، وَحِكْمَةَ أَوْلِيَائِهِ، وَتَتَوَصَّلَ بِاسْتِفَادَةِ الْعِلْمِ بِهَا إِلَى الْمُلْكِ الْمُقِيمِ وَالنَّعِيمِ الدَّائِمِ فِي جِوَارِ رَبِّ الْعَالَمِينَ."]]},{"id":"bi19_3","label":"آدَابُ الْأُذُنِ · ٣","segs":[["matn","فَإِذَا أَصْغَيْتَ بِهَا إِلَى شَيْءٍ مِنَ الْمَكَارِهِ صَارَ مَا كَانَ لَكَ عَلَيْكَ، وَانْقَلَبَ مَا كَانَ سَبَبَ فَوْزِكَ سَبَبَ هَلَاكِكَ، وَهَذَا غَايَةُ الْخُسْرَانِ."]]},{"id":"bi19_4","label":"آدَابُ الْأُذُنِ · ٤","segs":[["matn","وَلَا تَظُنَّ أَنَّ الْإِثْمَ يَخْتَصُّ بِهِ الْقَائِلُ دُونَ الْمُسْتَمِعِ؛"]]},{"id":"bi19_5","label":"آدَابُ الْأُذُنِ · ٥","segs":[["matn","فَفِي الْخَبَرِ: «أَنَّ الْمُسْتَمِعَ شَرِيكُ الْقَائِلِ وَهُوَ أَحَدُ الْمُغْتَابَيْنِ»."]]}],"group":"الْقِسْمُ الثَّانِي الْقَوْلُ فِي اجْتِنَابِ الْمَعَاصِي"},{"id":"bi20","title":"آدَابُ اللِّسَانِ","units":[{"id":"bi20_1","label":"آدَابُ اللِّسَانِ · ١","segs":[["matn","وَأَمَّا اللِّسَانُ: فَإِنَّمَا خُلِقَ لِتُكْثِرَ بِهِ ذِكْرَ اللَّهِ تَعَالَى وَتِلَاوَةَ كِتَابِهِ، وَتُرْشِدَ بِهِ خَلْقَ اللَّهِ تَعَالَى إِلَى طَرِيقِهِ، وَتُظْهِرَ بِهِ مَا فِي ضَمِيرِكَ مِنْ حَاجَاتِ دِينِكَ وَدُنْيَاكَ."]]},{"id":"bi20_2","label":"آدَابُ اللِّسَانِ · ٢","segs":[["matn","فَإِذَا اسْتَعْمَلْتَهُ فِي غَيْرِ مَا خُلِقَ لَهُ، فَقَدْ كَفَرْتَ نِعْمَةَ اللَّهِ تَعَالَى فِيهِ، وَهُوَ أَغْلَبُ أَعْضَائِكَ عَلَيْكَ وَعَلَى سَائِرِ الْخَلْقِ، وَلَا يَكُبُّ النَّاسَ فِي النَّارِ عَلَى مَنَاخِرِهِمْ إِلَّا حَصَائِدُ أَلْسِنَتِهِمْ."]]},{"id":"bi20_3","label":"آدَابُ اللِّسَانِ · ٣","segs":[["matn","فَاسْتَظْهِرْ عَلَيْهِ بِغَايَةِ قُوَّتِكَ حَتَّى لَا يَكُبَّكَ فِي قَعْرِ جَهَنَّمَ، فَفِي الْخَبَرِ: «إِنَّ الرَّجُلَ لَيَتَكَلَّمُ بِالْكَلِمَةِ لِيُضْحِكَ بِهَا أَصْحَابَهُ فَيَهْوِي بِهَا فِي قَعْرِ جَهَنَّمَ سَبْعِينَ خَرِيفًا»،"]]},{"id":"bi20_4","label":"آدَابُ اللِّسَانِ · ٤","segs":[["matn","وَرُوِيَ أَنَّهُ قُتِلَ شَهِيدٌ فِي الْمَعْرَكَةِ عَلَى عَهْدِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ قَائِلٌ: هَنِيئًا لَهُ الْجَنَّةُ، فَقَالَ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: «وَمَا يُدْرِيكَ لَعَلَّهُ كَانَ يَتَكَلَّمُ فِيمَا لَا يَعْنِيهِ، وَيَبْخَلُ بِمَا لَا يُغْنِيهِ». فَاحْفَظْ لِسَانَكَ مِنْ ثَمَانِيَةٍ:"]]}],"group":"الْقِسْمُ الثَّانِي الْقَوْلُ فِي اجْتِنَابِ الْمَعَاصِي"},{"id":"bi21","title":"الْأَوَّلُ الْكَذِبُ","units":[{"id":"bi21_1","label":"الْأَوَّلُ الْكَذِبُ · ١","segs":[["matn","فَاحْفَظْ مِنْهُ لِسَانَكَ فِي الْجِدِّ وَالْهَزْلِ، وَلَا تُعَوِّدْ لِسَانَكَ الْكَذِبَ هَزْلًا فَيَدْعُوَكَ إِلَى الْكَذِبِ فِي الْجِدِّ، وَالْكَذِبُ مِنْ أُمَّهَاتِ الْكَبَائِرِ، ثُمَّ إِنَّكَ إِذَا عُرِفْتَ بِذَلِكَ سَقَطَتْ عَدَالَتُكَ وَالثِّقَةُ بِقَوْلِكَ، وَتَزْدَرِيكَ الْأَعْيُنُ وَتَحْتَقِرُكَ."]]},{"id":"bi21_2","label":"الْأَوَّلُ الْكَذِبُ · ٢","segs":[["matn","وَإِذَا أَرَدْتَ أَنْ تَعْرِفَ قُبْحَ الْكَذِبِ مِنْ نَفْسِكَ، فَانْظُرْ إِلَى كَذِبِ غَيْرِكَ، وَعَلَى نَفْرَةِ نَفْسِكَ عَنْهُ، وَاسْتِحْقَارِكَ لِصَاحِبِهِ وَاسْتِقْبَاحِكَ لَهُ."]]},{"id":"bi21_3","label":"الْأَوَّلُ الْكَذِبُ · ٣","segs":[["matn","وَكَذَلِكَ فَافْعَلْ فِي جَمِيعِ عُيُوبِ نَفْسِكَ؛ فَإِنَّكَ لَا تَرَى قُبْحَ عُيُوبِكَ مِنْ نَفْسِكَ، بَلْ مِنْ غَيْرِكَ، فَمَا اسْتَقْبَحْتَهُ مِنْ غَيْرِكَ يَسْتَقْبِحُهُ غَيْرُكَ مِنْكَ لَا مَحَالَةَ؛ فَلَا تَرْضَ لِنَفْسِكَ ذَلِكَ."]]}],"group":"الْقِسْمُ الثَّانِي الْقَوْلُ فِي اجْتِنَابِ الْمَعَاصِي"},{"id":"bi22","title":"الثَّانِي الْخُلْفُ فِي الْوَعْدِ","units":[{"id":"bi22_1","label":"الثَّانِي الْخُلْفُ فِي الْوَعْدِ · ١","segs":[["matn","فَإِيَّاكَ أَنْ تَعِدَ بِشَيْءٍ وَلَا تَفِيَ بِهِ، بَلْ يَنْبَغِي أَنْ يَكُونَ إِحْسَانُكَ إِلَى النَّاسِ فِعْلًا بِلَا قَوْلٍ، فَإِنِ اضْطُرِرْتَ إِلَى الْوَعْدِ، فَإِيَّاكَ أَنْ تُخْلِفَ إِلَّا لِعَجْزٍ أَوْ ضَرُورَةٍ؛"]]},{"id":"bi22_2","label":"الثَّانِي الْخُلْفُ فِي الْوَعْدِ · ٢","segs":[["matn","فَإِنَّ ذَلِكَ مِنْ أَمَارَاتِ النِّفَاقِ وَخَبَائِثِ الْأَخْلَاقِ، قَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: «ثَلَاثٌ مَنْ كُنَّ فِيهِ فَهُوَ مُنَافِقٌ وَإِنْ صَامَ وَصَلَّى: مَنْ إِذَا حَدَّثَ كَذَبَ، وَإِذَا وَعَدَ أَخْلَفَ، وَإِذَا اؤْتُمِنَ خَانَ»."]]}],"group":"الْقِسْمُ الثَّانِي الْقَوْلُ فِي اجْتِنَابِ الْمَعَاصِي"},{"id":"bi23","title":"الثَّالِثُ الْغِيبَةُ","units":[{"id":"bi23_1","label":"الثَّالِثُ الْغِيبَةُ · ١","segs":[["matn","فَاحْفَظْ لِسَانَكَ عَنْهَا، وَالْغِيبَةُ أَشَدُّ مِنْ ثَلَاثِينَ زَنْيَةً فِي الْإِسْلَامِ."]]},{"id":"bi23_2","label":"الثَّالِثُ الْغِيبَةُ · ٢","segs":[["matn","كَذَلِكَ وَرَدَ فِي الْخَبَرِ. وَمَعْنَى الْغِيبَةِ: أَنْ تَذْكُرَ إِنْسَانًا بِمَا يَكْرَهُهُ لَوْ سَمِعَهُ، فَأَنْتَ مُغْتَابٌ ظَالِمٌ وَإِنْ كُنْتَ صَادِقًا."]]},{"id":"bi23_3","label":"الثَّالِثُ الْغِيبَةُ · ٣","segs":[["matn","وَإِيَّاكَ وَغِيبَةَ الْقُرَّاءِ الْمُرَائِينَ، وَهُوَ أَنْ تُفْهِمَ الْمَقْصُودَ مِنْ غَيْرِ تَصْرِيحٍ فَتَقُولَ: أَصْلَحَهُ اللَّهُ فَقَدْ سَاءَنِي وَغَمَّنِي مَا جَرَى عَلَيْهِ، فَنَسْأَلُ اللَّهَ تَعَالَى أَنْ يُصْلِحَنَا وَإِيَّاهُ؛"]]},{"id":"bi23_4","label":"الثَّالِثُ الْغِيبَةُ · ٤","segs":[["matn","فَإِنَّ هَذَا جَمْعٌ بَيْنَ خَبِيثَيْنِ، أَحَدُهُمَا: الْغِيبَةُ إِذَا حَصَلَ بِهِ التَّفَهُّمُ، وَالْآخَرُ: تَزْكِيَةُ النَّفْسِ وَالثَّنَاءُ عَلَيْهَا بِالتَّجْرِيحِ لِغَيْرِكَ وَالصَّلَاحِ لِنَفْسِكَ."]]},{"id":"bi23_5","label":"الثَّالِثُ الْغِيبَةُ · ٥","segs":[["matn","وَلَكِنْ إِنْ كَانَ مَقْصُودُكَ مِنْ قَوْلِكَ: أَصْلَحَهُ اللَّهُ - الدُّعَاءَ؛"]]},{"id":"bi23_6","label":"الثَّالِثُ الْغِيبَةُ · ٦","segs":[["matn","فَادْعُ لَهُ فِي السِّرِّ. وَإِنِ اغْتَمَمْتَ بِسَبَبِهِ، فَعَلَامَتُهُ أَنَّكَ لَا تُرِيدُ فَضِيحَتَهُ وَإِظْهَارَ عَيْبِهِ، وَفِي إِظْهَارِكَ الْغَمَّ بِعَيْبِهِ إِظْهَارُ تَعْيِيبِهِ."]]},{"id":"bi23_7","label":"الثَّالِثُ الْغِيبَةُ · ٧","segs":[["matn","وَيَكْفِيكَ زَاجِرًا عَنِ الْغِيبَةِ قَوْلُهُ تَعَالَى: ﴿وَلَا يَغْتَب بَّعْضُكُم بَعْضًا أَيُحِبُّ أَحَدُكُمْ أَن يَأْكُلَ لَحْمَ أَخِيهِ مَيْتًا فَكَرِهْتُمُوهُ﴾."]]},{"id":"bi23_8","label":"الثَّالِثُ الْغِيبَةُ · ٨","segs":[["matn","فَقَدْ شَبَّهَكَ اللَّهُ بِآكِلِ لَحْمِ الْمَيْتَةِ؛ فَمَا أَجْدَرَكَ أَنْ تَحْتَرِزَ مِنْهَا؟"]]},{"id":"bi23_9","label":"الثَّالِثُ الْغِيبَةُ · ٩","segs":[["matn","وَيَمْنَعُكَ عَنِ الْغِيبَةِ أَمْرٌ لَوْ تَفَكَّرْتَ فِيهِ وَهُوَ أَنْ تَنْظُرَ فِي نَفْسِكَ، هَلْ فِيكَ عَيْبٌ ظَاهِرٌ أَوْ بَاطِنٌ؟، وَهَلْ أَنْتَ مُقَارِفٌ مَعْصِيَةً سِرًّا أَوْ جَهْرًا؟"]]},{"id":"bi23_10","label":"الثَّالِثُ الْغِيبَةُ · ١٠","segs":[["matn","فَإِذَا عَرَفْتَ ذَلِكَ مِنْ نَفْسِكَ، فَاعْلَمْ أَنَّ عَجْزَهُ عَنِ التَّنَزُّهِ عَمَّا نَسَبْتَهُ إِلَيْهِ كَعَجْزِكَ، وَعُذْرَهُ كَعُذْرِكَ."]]},{"id":"bi23_11","label":"الثَّالِثُ الْغِيبَةُ · ١١","segs":[["matn","وَكَمَا تَكْرَهُ أَنْ تَفْتَضِحَ وَتُذْكَرَ عُيُوبُكَ، فَهُوَ أَيْضًا يَكْرَهُهُ؛"]]},{"id":"bi23_12","label":"الثَّالِثُ الْغِيبَةُ · ١٢","segs":[["matn","فَإِنْ سَتَرْتَهُ سَتَرَ اللَّهُ عَلَيْكَ عُيُوبَكَ، وَإِنْ فَضَحْتَهُ سَلَّطَ اللَّهُ عَلَيْكَ أَلْسِنَةً حِدَادًا، يُمَزِّقُونَ عِرْضَكَ فِي الدُّنْيَا، ثُمَّ يَفْضَحُكَ اللَّهُ فِي الْآخِرَةِ عَلَى رُؤُوسِ الْخَلَائِقِ يَوْمَ الْقِيَامَةِ."]]},{"id":"bi23_13","label":"الثَّالِثُ الْغِيبَةُ · ١٣","segs":[["matn","وَإِنْ نَظَرْتَ إِلَى ظَاهِرِكَ وَبَاطِنِكَ، فَلَمْ تَطَّلِعْ فِيهِمَا عَلَى عَيْبٍ وَنَقْصٍ فِي دِينٍ وَلَا دُنْيَا، فَاعْلَمْ أَنَّ جَهْلَكَ بِعُيُوبِ نَفْسِكَ أَقْبَحُ أَنْوَاعِ الْحَمَاقَةِ، وَلَا عَيْبَ أَعْظَمُ مِنَ الْحُمْقِ."]]},{"id":"bi23_14","label":"الثَّالِثُ الْغِيبَةُ · ١٤","segs":[["matn","وَلَوْ أَرَادَ اللَّهُ بِكَ خَيْرًا لَبَصَّرَكَ بِعُيُوبِ نَفْسِكَ، فَرُؤْيَتُكَ نَفْسَكَ بِعَيْنِ الرِّضَا غَايَةُ غَبَاوَتِكَ وَجَهْلِكَ."]]},{"id":"bi23_15","label":"الثَّالِثُ الْغِيبَةُ · ١٥","segs":[["matn","ثُمَّ إِنْ كُنْتَ صَادِقًا فِي ظَنِّكَ فَاشْكُرِ اللَّهَ تَعَالَى عَلَيْهِ وَلَا تُفْسِدْهُ بِثَلْبِ النَّاسِ، وَالتَّمَضْمُضِ بِأَعْرَاضِهِمْ؛ فَإِنَّ ذَلِكَ مِنْ أَعْظَمِ الْعُيُوبِ."]]}],"group":"الْقِسْمُ الثَّانِي الْقَوْلُ فِي اجْتِنَابِ الْمَعَاصِي"},{"id":"bi24","title":"الرَّابِعُ الْمِرَاءُ وَالْجِدَالُ وَمُنَاقَشَةُ النَّاسِ فِي الْكَلَامِ","units":[{"id":"bi24_1","label":"الرَّابِعُ الْمِرَاءُ وَالْجِدَالُ وَمُنَاقَشَةُ النَّاسِ فِي الْكَلَامِ · ١","segs":[["matn","فَذَلِكَ فِيهِ إِيذَاءٌ لِلْمُخَاطَبِ وَتَجْهِيلٌ لَهُ، وَطَعْنٌ فِيهِ، وَفِيهِ ثَنَاءٌ عَلَى النَّفْسِ وَتَزْكِيَةٌ لَهَا بِمَزِيدِ الْفِطْنَةِ وَالْعِلْمِ، ثُمَّ هُوَ مُشَوِّشٌ لِلْعَيْشِ؛"]]},{"id":"bi24_2","label":"الرَّابِعُ الْمِرَاءُ وَالْجِدَالُ وَمُنَاقَشَةُ النَّاسِ فِي الْكَلَامِ · ٢","segs":[["matn","فَإِنَّكَ لَا تُمَارِي سَفِيهًا إِلَّا وَيُؤْذِيكَ، وَلَا تُمَارِي حَلِيمًا إِلَّا وَيَقْلِيكَ وَيَحْقِدُ عَلَيْكَ؛"]]},{"id":"bi24_3","label":"الرَّابِعُ الْمِرَاءُ وَالْجِدَالُ وَمُنَاقَشَةُ النَّاسِ فِي الْكَلَامِ · ٣","segs":[["matn","فَقَدْ قَالَ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: «مَنْ تَرَكَ الْمِرَاءَ وَهُوَ مُبْطِلٌ بَنَى اللَّهُ لَهُ بَيْتًا فِي رَبَضِ الْجَنَّةِ، وَمَنْ تَرَكَ الْمِرَاءَ وَهُوَ مُحِقٌّ بَنَى اللَّهُ لَهُ بَيْتًا فِي أَعْلَى الْجَنَّةِ»."]]},{"id":"bi24_4","label":"الرَّابِعُ الْمِرَاءُ وَالْجِدَالُ وَمُنَاقَشَةُ النَّاسِ فِي الْكَلَامِ · ٤","segs":[["matn","وَلَا يَنْبَغِي أَنْ يَخْدَعَكَ الشَّيْطَانُ وَيَقُولَ لَكَ: أَظْهِرِ الْحَقَّ وَلَا تُدَاهِنْ فِيهِ، فَإِنَّ الشَّيْطَانَ أَبَدًا يَسْتَجِرُّ الْحَمْقَى إِلَى الشَّرِّ فِي مَعْرِضِ الْخَيْرِ، فَلَا تَكُنْ ضُحْكَةً لِلشَّيْطَانِ فَيَسْخَرَ مِنْكَ، فَإِظْهَارُ الْحَقِّ حَسَنٌ مَعَ مَنْ يَقْبَلُهُ مِنْكَ، وَذَلِكَ بِطَرِيقِ النَّصِيحَةِ فِي الْخُفْيَةِ لَا بِطَرِيقِ الْمُمَارَاةِ."]]},{"id":"bi24_5","label":"الرَّابِعُ الْمِرَاءُ وَالْجِدَالُ وَمُنَاقَشَةُ النَّاسِ فِي الْكَلَامِ · ٥","segs":[["matn","وَلِلنَّصِيحَةِ صِفَةٌ وَهَيْئَةٌ، وَيُحْتَاجُ فِيهَا إِلَى تَلَطُّفٍ وَإِلَّا صَارَتْ فَضِيحَةً، وَكَانَ فَسَادُهَا أَكْثَرَ مِنْ صَلَاحِهَا."]]},{"id":"bi24_6","label":"الرَّابِعُ الْمِرَاءُ وَالْجِدَالُ وَمُنَاقَشَةُ النَّاسِ فِي الْكَلَامِ · ٦","segs":[["matn","وَمَنْ خَالَطَ مُتَفَقِّهَةَ الْعَصْرِ غَلَبَ عَلَى طَبْعِهِ الْمِرَاءُ وَالْجِدَالُ، وَعَسُرَ عَلَيْهِ الصَّمْتُ، إِذْ أَلْقَى إِلَيْهِ عُلَمَاءُ السُّوءِ أَنَّ ذَلِكَ هُوَ الْفَضْلُ، وَالْقُدْرَةَ عَلَى الْمُحَاجَّةِ وَالْمُنَاقَشَةِ هُوَ الَّذِي يُمْتَدَحُ بِهِ؛"]]},{"id":"bi24_7","label":"الرَّابِعُ الْمِرَاءُ وَالْجِدَالُ وَمُنَاقَشَةُ النَّاسِ فِي الْكَلَامِ · ٧","segs":[["matn","فَفِرَّ مِنْهُمْ فِرَارَكَ مِنَ الْأَسَدِ، وَاعْلَمْ أَنَّ الْمِرَاءَ سَبَبُ الْمَقْتِ عِنْدَ اللَّهِ وَعِنْدَ الْخَلْقِ."]]}],"group":"الْقِسْمُ الثَّانِي الْقَوْلُ فِي اجْتِنَابِ الْمَعَاصِي"},{"id":"bi25","title":"الْخَامِسُ تَزْكِيَةُ النَّفْسِ","units":[{"id":"bi25_1","label":"الْخَامِسُ تَزْكِيَةُ النَّفْسِ · ١","segs":[["matn","فَقَدْ قَالَ اللَّهُ تَعَالَى: ﴿فَلَا تُزَكُّوا أَنفُسَكُمْ هُوَ أَعْلَمُ بِمَنِ اتَّقَىٰ﴾، وَقِيلَ لِبَعْضِ الْحُكَمَاءِ: مَا الصِّدْقُ الْقَبِيحُ؟"]]},{"id":"bi25_2","label":"الْخَامِسُ تَزْكِيَةُ النَّفْسِ · ٢","segs":[["matn","فَقَالَ: ثَنَاءُ الْمَرْءِ عَلَى نَفْسِهِ. فَإِيَّاكَ أَنْ تَتَعَوَّدَ ذَلِكَ، وَاعْلَمْ أَنَّ ذَلِكَ يَنْقُصُ مِنْ قَدْرِكَ عِنْدَ النَّاسِ، وَيُوجِبُ مَقْتَكَ عِنْدَ اللَّهِ تَعَالَى."]]},{"id":"bi25_3","label":"الْخَامِسُ تَزْكِيَةُ النَّفْسِ · ٣","segs":[["matn","فَإِذَا أَرَدْتَ أَنْ تَعْرِفَ أَنَّ ثَنَاءَكَ عَلَى نَفْسِكَ لَا يَزِيدُ فِي قَدْرِكَ عِنْدَ غَيْرِكَ، فَانْظُرْ إِلَى أَقْرَانِكَ إِذَا أَثْنَوْا عَلَى أَنْفُسِهِمْ بِالْفَضْلِ وَالْجَاهِ وَالْمَالِ كَيْفَ يَسْتَنْكِرُهُ قَلْبُكَ عَلَيْهِمْ، وَيَسْتَثْقِلُهُ طَبْعُكَ، وَكَيْفَ تَذُمُّهُمْ عَلَيْهِ إِذَا فَارَقْتَهُمْ؛"]]},{"id":"bi25_4","label":"الْخَامِسُ تَزْكِيَةُ النَّفْسِ · ٤","segs":[["matn","فَاعْلَمْ أَنَّهُمْ أَيْضًا فِي حَالِ تَزْكِيَتِكَ لِنَفْسِكَ يَذُمُّونَكَ فِي قُلُوبِهِمْ نَاجِزًا، وَسَيُظْهِرُونَهُ بِأَلْسِنَتِهِمْ إِذَا فَارَقْتَهُمْ."]]}],"group":"الْقِسْمُ الثَّانِي الْقَوْلُ فِي اجْتِنَابِ الْمَعَاصِي"},{"id":"bi26","title":"السَّادِسُ: اللَّعْنُ","units":[{"id":"bi26_1","label":"السَّادِسُ: اللَّعْنُ · ١","segs":[["matn","فَإِيَّاكَ أَنْ تَلْعَنَ شَيْئًا مِمَّا خَلَقَ اللَّهُ تَعَالَى مِنْ حَيَوَانٍ أَوْ طَعَامٍ أَوْ إِنْسَانٍ بِعَيْنِهِ، وَلَا تَقْطَعْ بِشَهَادَتِكَ عَلَى أَحَدٍ مِنْ أَهْلِ الْقِبْلَةِ بِشِرْكٍ أَوْ كُفْرٍ أَوْ نِفَاقٍ؛"]]},{"id":"bi26_2","label":"السَّادِسُ: اللَّعْنُ · ٢","segs":[["matn","فَإِنَّ الْمُطَّلِعَ عَلَى السَّرَائِرِ هُوَ اللَّهُ تَعَالَى، فَلَا تَدْخُلْ بَيْنَ الْعِبَادِ وَبَيْنَ اللَّهِ تَعَالَى، وَاعْلَمْ أَنَّكَ يَوْمَ الْقِيَامَةِ لَا يُقَالُ لَكَ: لِمَ لَمْ تَلْعَنْ فُلَانًا، وَلِمَ سَكَتَّ عَنْهُ؟"]]},{"id":"bi26_3","label":"السَّادِسُ: اللَّعْنُ · ٣","segs":[["matn","بَلْ لَوْ لَمْ تَلْعَنْ إِبْلِيسَ طُولَ عُمُرِكَ، وَلَمْ تَشْغَلْ لِسَانَكَ بِذِكْرِهِ لَمْ تُسْأَلْ عَنْهُ وَلَمْ تُطَالَبْ بِهِ يَوْمَ الْقِيَامَةِ."]]},{"id":"bi26_4","label":"السَّادِسُ: اللَّعْنُ · ٤","segs":[["matn","وَإِذَا لَعَنْتَ أَحَدًا مِنْ خَلْقِ اللَّهِ تَعَالَى طُولِبْتَ بِهِ، وَلَا تَذُمَّ شَيْئًا مِمَّا خَلَقَ اللَّهُ تَعَالَى، فَقَدْ كَانَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لَا يَذُمُّ الطَّعَامَ الرَّدِيءَ قَطُّ، بَلْ كَانَ إِذَا اشْتَهَى شَيْئًا أَكَلَهُ وَإِلَّا تَرَكَهُ."]]}],"group":"الْقِسْمُ الثَّانِي الْقَوْلُ فِي اجْتِنَابِ الْمَعَاصِي"},{"id":"bi27","title":"السَّابِعُ الدُّعَاءُ عَلَى الْخَلْقِ","units":[{"id":"bi27_1","label":"السَّابِعُ الدُّعَاءُ عَلَى الْخَلْقِ · ١","segs":[["matn","فَاحْفَظْ لِسَانَكَ عَنِ الدُّعَاءِ عَلَى أَحَدٍ مِنْ خَلْقِ اللَّهِ تَعَالَى، وَإِنْ ظَلَمَكَ فَكِلْ أَمْرَهُ إِلَى اللَّهِ تَعَالَى؛"]]},{"id":"bi27_2","label":"السَّابِعُ الدُّعَاءُ عَلَى الْخَلْقِ · ٢","segs":[["matn","فَفِي الْحَدِيثِ: «إِنَّ الْمَظْلُومَ لَيَدْعُو عَلَى ظَالِمِهِ حَتَّى يُكَافِئَهُ ثُمَّ يَبْقَى لِلظَّالِمِ فَضْلٌ عِنْدَهُ يُطَالِبُ بِهِ يَوْمَ الْقِيَامَةِ»."]]},{"id":"bi27_3","label":"السَّابِعُ الدُّعَاءُ عَلَى الْخَلْقِ · ٣","segs":[["matn","وَطَوَّلَ بَعْضُ النَّاسِ لِسَانَهُ عَلَى الْحَجَّاجِ فَقَالَ بَعْضُ السَّلَفِ: «إِنَّ اللَّهَ لَيَنْتَقِمُ لِلْحَجَّاجِ مِمَّنْ تَعَرَّضَ لَهُ بِلِسَانِهِ كَمَا يَنْتَقِمُ مِنَ الْحَجَّاجِ لِمَنْ ظَلَمَهُ»."]]}],"group":"الْقِسْمُ الثَّانِي الْقَوْلُ فِي اجْتِنَابِ الْمَعَاصِي"},{"id":"bi28","title":"الثَّامِنُ الْمِزَاحُ وَالسُّخْرِيَةُ وَالِاسْتِهْزَاءُ بِالنَّاسِ","units":[{"id":"bi28_1","label":"الثَّامِنُ الْمِزَاحُ وَالسُّخْرِيَةُ وَالِاسْتِهْزَاءُ بِالنَّاسِ · ١","segs":[["matn","فَاحْفَظْ لِسَانَكَ مِنْهُ، فِي الْجِدِّ وَالْهَزْلِ؛ فَإِنَّهُ يُرِيقُ مَاءَ الْوَجْهِ وَيُسْقِطُ الْمَهَابَةَ، وَيَسْتَجِرُّ الْوَحْشَةَ، وَيُؤْذِي الْقُلُوبَ، وَهُوَ مَبْدَأُ اللَّجَاجِ وَالْغَضَبِ وَالتَّصَارُمِ، وَيَغْرِسُ الْحِقْدَ فِي الْقُلُوبِ؛"]]},{"id":"bi28_2","label":"الثَّامِنُ الْمِزَاحُ وَالسُّخْرِيَةُ وَالِاسْتِهْزَاءُ بِالنَّاسِ · ٢","segs":[["matn","فَلَا تُمَازِحْ أَحَدًا؛ فَإِنْ مَازَحَكَ أَحَدٌ فَلَا تُجِبْهُ، وَأَعْرِضْ عَنْهُمْ حَتَّى يَخُوضُوا فِي حَدِيثٍ غَيْرِهِ، وَكُنْ مِنَ الَّذِينَ إِذَا مَرُّوا بِاللَّغْوِ مَرُّوا كِرَامًا."]]},{"id":"bi28_3","label":"الثَّامِنُ الْمِزَاحُ وَالسُّخْرِيَةُ وَالِاسْتِهْزَاءُ بِالنَّاسِ · ٣","segs":[["matn","فَهَذِهِ مَجَامِعُ آفَاتِ اللِّسَانِ، وَلَا يُعِينُكَ عَلَيْهِ إِلَّا الْعُزْلَةُ، أَوْ مُلَازَمَةُ الصَّمْتِ إِلَّا بِقَدْرِ الضَّرُورَةِ؛"]]},{"id":"bi28_4","label":"الثَّامِنُ الْمِزَاحُ وَالسُّخْرِيَةُ وَالِاسْتِهْزَاءُ بِالنَّاسِ · ٤","segs":[["matn","فَقَدْ كَانَ أَبُو بَكْرٍ الصِّدِّيقُ رَضِيَ اللَّهُ تَعَالَى عَنْهُ يَضَعُ حَجَرًا فِي فِيهِ لِيَمْنَعَهُ ذَلِكَ مِنَ الْكَلَامِ بِغَيْرِ ضَرُورَةٍ، وَيُشِيرُ إِلَى لِسَانِهِ وَيَقُولُ: هَذَا الَّذِي أَوْرَدَنِي الْمَوَارِدَ."]]},{"id":"bi28_5","label":"الثَّامِنُ الْمِزَاحُ وَالسُّخْرِيَةُ وَالِاسْتِهْزَاءُ بِالنَّاسِ · ٥","segs":[["matn","فَاحْتَرِزْ مِنْهُ بِجُهْدِكَ؛ فَإِنَّهُ أَقْوَى أَسْبَابِ هَلَاكِكَ فِي الدُّنْيَا وَالْآخِرَةِ."]]}],"group":"الْقِسْمُ الثَّانِي الْقَوْلُ فِي اجْتِنَابِ الْمَعَاصِي"},{"id":"bi29","title":"آدَابُ الْبَطْنِ","units":[{"id":"bi29_1","label":"آدَابُ الْبَطْنِ · ١","segs":[["matn","وَأَمَّا الْبَطْنُ: فَاحْفَظْهُ مِنْ تَنَاوُلِ الْحَرَامِ وَالشُّبْهَةِ، وَاحْرِصْ عَلَى طَلَبِ الْحَلَالِ، فَإِذَا وَجَدْتَهُ فَاحْرِصْ عَلَى أَنْ تَقْتَصِرَ مِنْهُ عَلَى مَا دُونَ الشِّبَعِ، فَإِنَّ الشِّبَعَ يُقْسِي الْقَلْبَ، وَيُفْسِدُ الذِّهْنَ، وَيُبْطِلُ الْحِفْظَ، وَيُثَقِّلُ الْأَعْضَاءَ عَنِ الْعِبَادَةِ وَالْعِلْمِ، وَيُقَوِّي الشَّهَوَاتِ، وَيَنْصُرُ جُنُودَ الشَّيْطَانِ."]]},{"id":"bi29_2","label":"آدَابُ الْبَطْنِ · ٢","segs":[["matn","وَالشِّبَعُ مِنَ الْحَلَالِ مَبْدَأُ كُلِّ شَرٍّ، فَكَيْفَ مِنَ الْحَرَامِ وَطَلَبُ الْحَلَالِ فَرِيضَةٌ عَلَى كُلِّ مُسْلِمٍ، وَالْعِبَادَةُ مَعَ أَكْلِ الْحَرَامِ كَالْبِنَاءِ عَلَى السِّرْجِينِ."]]},{"id":"bi29_3","label":"آدَابُ الْبَطْنِ · ٣","segs":[["matn","فَإِذَا قَنِعْتَ فِي السَّنَةِ بِقَمِيصٍ خَشِنٍ، وَفِي الْيَوْمِ وَاللَّيْلَةِ بِرَغِيفَيْنِ مِنَ الْخُشْكَارِ، وَتَرَكْتَ التَّلَذُّذَ بِأَطْيَبِ الْأُدُمِ، لَمْ يُعْوِزْكَ مِنَ الْحَلَالِ مَا يَكْفِيكَ، وَالْحَلَالُ كَثِيرٌ."]]},{"id":"bi29_4","label":"آدَابُ الْبَطْنِ · ٤","segs":[["matn","وَلَيْسَ عَلَيْكَ أَنْ تَتَيَقَّنَ بَوَاطِنَ الْأُمُورِ، بَلْ عَلَيْكَ أَنْ تَحْتَرِزَ مِمَّا تَعْلَمُ أَنَّهُ حَرَامٌ أَوْ تَظُنُّ أَنَّهُ حَرَامٌ ظَنًّا حَصَلَ مِنْ عَلَامَةٍ نَاجِزَةٍ مَقْرُونَةٍ بِالْمَالِ؛"]]},{"id":"bi29_5","label":"آدَابُ الْبَطْنِ · ٥","segs":[["matn","أَمَّا الْمَعْلُومُ فَظَاهِرٌ، وَأَمَّا الْمَظْنُونُ بِعَلَامَةٍ فَهُوَ مَالُ السُّلْطَانِ وَعُمَّالِهِ، وَمَالُ مَنْ لَا كَسْبَ لَهُ إِلَّا مِنَ النِّيَاحَةِ، أَوْ بَيْعِ الْخَمْرِ، أَوِ الرِّبَا، أَوِ الْمَزَامِيرِ؛"]]},{"id":"bi29_6","label":"آدَابُ الْبَطْنِ · ٦","segs":[["matn","وَغَيْرِ ذَلِكَ مِنْ آلَاتِ اللَّهْوِ الْمُحَرَّمَةِ. فَإِنَّ مَنْ عَلِمْتَ أَنَّ أَكْثَرَ مَالِهِ حَرَامٌ قَطْعًا، فَمَا تَأْخُذُهُ مِنْ يَدِهِ - وَإِنْ أَمْكَنَ أَنْ يَكُونَ حَلَالًا نَادِرًا - فَهُوَ حَرَامٌ؛"]]},{"id":"bi29_7","label":"آدَابُ الْبَطْنِ · ٧","segs":[["matn","لِأَنَّهُ الْغَالِبُ عَلَى الظَّنِّ. وَمِنَ الْحَرَامِ الْمَحْضِ مَا يُؤْكَلُ مِنَ الْأَوْقَافِ مِنْ غَيْرِ شَرْطِ الْوَاقِفِ، فَمَنْ لَمْ يَشْتَغِلْ بِالتَّفَقُّهِ فَمَا يَأْخُذُهُ مِنَ الْمَدَارِسِ حَرَامٌ، وَمَنِ ارْتَكَبَ مَعْصِيَةً تُرَدُّ بِهَا شَهَادَتُهُ، فَمَا يَأْخُذُهُ بِاسْمِ الصُّوفِيَّةِ مِنْ وَقْفٍ أَوْ غَيْرِهِ فَهُوَ حَرَامٌ."]]},{"id":"bi29_8","label":"آدَابُ الْبَطْنِ · ٨","segs":[["matn","وَقَدْ ذَكَرْنَا مَدَاخِلَ الشُّبُهَاتِ وَالْحَلَالِ وَالْحَرَامِ فِي كِتَابٍ مُفْرَدٍ مِنْ كُتُبِ إِحْيَاءِ عُلُومِ الدِّينِ، فَعَلَيْكَ بِطَلَبِهِ؛"]]},{"id":"bi29_9","label":"آدَابُ الْبَطْنِ · ٩","segs":[["matn","فَإِنَّ مَعْرِفَةَ الْحَلَالِ وَطَلَبَهُ فَرِيضَةٌ عَلَى كُلِّ مُسْلِمٍ، كَالصَّلَوَاتِ الْخَمْسِ."]]}],"group":"الْقِسْمُ الثَّانِي الْقَوْلُ فِي اجْتِنَابِ الْمَعَاصِي"},{"id":"bi30","title":"آدَابُ الْفَرْجِ","units":[{"id":"bi30_1","label":"آدَابُ الْفَرْجِ · ١","segs":[["matn","وَأَمَّا الْفَرْجُ: فَاحْفَظْهُ عَنْ كُلِّ مَا حَرَّمَ اللَّهُ تَعَالَى، وَكُنْ كَمَا قَالَ اللَّهُ: ﴿وَالَّذِينَ هُمْ لِفُرُوجِهِمْ حَافِظُونَ إِلَّا عَلَىٰ أَزْوَاجِهِمْ أَوْ مَا مَلَكَتْ أَيْمَانُهُمْ فَإِنَّهُمْ غَيْرُ مَلُومِينَ﴾."]]},{"id":"bi30_2","label":"آدَابُ الْفَرْجِ · ٢","segs":[["matn","وَلَا تَصِلُ إِلَى حِفْظِ الْفَرْجِ إِلَّا بِحِفْظِ الْعَيْنِ عَنِ النَّظَرِ، وَحِفْظِ الْقَلْبِ عَنِ التَّفَكُّرِ، وَحِفْظِ الْبَطْنِ عَنِ الشُّبْهَةِ وَعَنِ الشِّبَعِ؛ فَإِنَّ هَذِهِ مُحَرِّكَاتٌ لِلشَّهْوَةِ وَمَغَارِسُهَا."]]}],"group":"الْقِسْمُ الثَّانِي الْقَوْلُ فِي اجْتِنَابِ الْمَعَاصِي"},{"id":"bi31","title":"آدَابُ الْيَدَيْنِ","units":[{"id":"bi31_1","label":"آدَابُ الْيَدَيْنِ · ١","segs":[["matn","وَأَمَّا الْيَدَانِ: فَاحْفَظْهُمَا عَنْ أَنْ تَضْرِبَ بِهِمَا مُسْلِمًا، أَوْ تَتَنَاوَلَ بِهِمَا مَالًا حَرَامًا، أَوْ تُؤْذِيَ بِهِمَا أَحَدًا مِنَ الْخَلْقِ، أَوْ تَخُونَ بِهِمَا فِي أَمَانَةٍ أَوْ وَدِيعَةٍ، أَوْ تَكْتُبَ بِهِمَا مَا لَا يَجُوزُ النُّطْقُ بِهِ، فَإِنَّ الْقَلَمَ أَحَدُ اللِّسَانَيْنِ، فَاحْفَظِ الْقَلَمَ عَمَّا يَجِبُ حِفْظُ اللِّسَانِ عَنْهُ."]]}],"group":"الْقِسْمُ الثَّانِي الْقَوْلُ فِي اجْتِنَابِ الْمَعَاصِي"},{"id":"bi32","title":"آدَابُ الرِّجْلَيْنِ","units":[{"id":"bi32_1","label":"آدَابُ الرِّجْلَيْنِ · ١","segs":[["matn","وَأَمَّا الرِّجْلَانِ: فَاحْفَظْهُمَا عَنْ أَنْ تَمْشِيَ بِهِمَا إِلَى حَرَامٍ، أَوْ تَسْعَى بِهِمَا إِلَى بَابِ سُلْطَانٍ ظَالِمٍ؛"]]},{"id":"bi32_2","label":"آدَابُ الرِّجْلَيْنِ · ٢","segs":[["matn","فَإِنَّ الْمَشْيَ إِلَى السَّلَاطِينِ الظَّلَمَةِ مِنْ غَيْرِ ضَرُورَةٍ وَإِرْهَاقٍ مَعْصِيَةٌ كَبِيرَةٌ؛"]]},{"id":"bi32_3","label":"آدَابُ الرِّجْلَيْنِ · ٣","segs":[["matn","فَإِنَّهُ تَوَاضُعٌ وَإِكْرَامٌ لَهُمْ عَلَى ظُلْمِهِمْ. وَقَدْ أَمَرَ اللَّهُ تَعَالَى بِالْإِعْرَاضِ عَنْهُمْ فِي قَوْلِهِ تَعَالَى: ﴿وَلَا تَرْكَنُوا إِلَى الَّذِينَ ظَلَمُوا فَتَمَسَّكُمُ النَّارُ﴾ وَهُوَ تَكْثِيرٌ لِسَوَادِهِمْ، وَإِنْ كَانَ ذَلِكَ لِسَبَبِ طَلَبِ مَالِهِمْ فَهُوَ سَعْيٌ إِلَى حَرَامٍ،"]]},{"id":"bi32_4","label":"آدَابُ الرِّجْلَيْنِ · ٤","segs":[["matn","وَقَدْ قَالَ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: «مَنْ تَوَاضَعَ لِغَنِيٍّ صَالِحٍ لِغِنَاهُ ذَهَبَ ثُلُثَا دِينِهِ» وَهَذَا فِي غَنِيٍّ صَالِحٍ، فَمَا ظَنُّكَ بِالْغَنِيِّ الظَّالِمِ؟"]]},{"id":"bi32_5","label":"آدَابُ الرِّجْلَيْنِ · ٥","segs":[["matn","وَعَلَى الْجُمْلَةِ، فَحَرَكَاتُكَ وَسَكَنَاتُكَ بِأَعْضَائِكَ نِعْمَةٌ مِنْ نِعَمِ اللَّهِ تَعَالَى عَلَيْكَ؛"]]},{"id":"bi32_6","label":"آدَابُ الرِّجْلَيْنِ · ٦","segs":[["matn","فَلَا تُحَرِّكْ شَيْئًا مِنْهَا فِي مَعْصِيَةِ اللَّهِ تَعَالَى أَصْلًا، وَاسْتَعْمِلْهَا فِي طَاعَةِ اللَّهِ تَعَالَى."]]},{"id":"bi32_7","label":"آدَابُ الرِّجْلَيْنِ · ٧","segs":[["matn","وَاعْلَمْ أَنَّكَ إِنْ قَصَّرْتَ فَعَلَيْكَ وَبَالُهُ، وَإِنْ شَمَّرْتَ فَإِلَيْكَ تَعُودُ ثَمَرَتُهُ، وَاللَّهُ غَنِيٌّ عَنْكَ وَعَنْ عَمَلِكَ، وَإِنَّمَا كُلُّ نَفْسٍ بِمَا كَسَبَتْ رَهِينَةٌ، وَإِيَّاكَ أَنْ تَقُولَ: إِنَّ اللَّهَ كَرِيمٌ رَحِيمٌ يَغْفِرُ الذُّنُوبَ لِلْعُصَاةِ؛"]]},{"id":"bi32_8","label":"آدَابُ الرِّجْلَيْنِ · ٨","segs":[["matn","فَإِنَّ هَذِهِ كَلِمَةُ حَقٍّ أُرِيدَ بِهَا بَاطِلٌ، وَصَاحِبُهَا مُلَقَّبٌ بِالْحَمَاقَةِ، بِتَلْقِيبِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ حَيْثُ قَالَ: «الْكَيِّسُ مَنْ دَانَ نَفْسَهُ وَعَمِلَ لِمَا بَعْدَ الْمَوْتِ، وَالْأَحْمَقُ مَنْ أَتْبَعَ نَفْسَهُ هَوَاهَا، وَتَمَنَّى عَلَى اللَّهِ الْأَمَانِيَّ»."]]},{"id":"bi32_9","label":"آدَابُ الرِّجْلَيْنِ · ٩","segs":[["matn","وَاعْلَمْ أَنَّ قَوْلَكَ هَذَا يُضَاهِي قَوْلَ مَنْ يُرِيدُ أَنْ يَكُونَ فَقِيهًا فِي عُلُومِ الدِّينِ مِنْ غَيْرِ أَنْ يَدْرُسَ عِلْمًا وَاشْتَغَلَ بِالْبَطَالَةِ وَقَالَ:"]]},{"id":"bi32_10","label":"آدَابُ الرِّجْلَيْنِ · ١٠","segs":[["matn","إِنَّ اللَّهَ كَرِيمٌ رَحِيمٌ قَادِرٌ عَلَى أَنْ يُفِيضَ عَلَى قَلْبِي مِنَ الْعُلُومِ مَا أَفَاضَهُ عَلَى قُلُوبِ أَنْبِيَائِهِ وَأَوْلِيَائِهِ مِنْ غَيْرِ جُهْدٍ وَتَكْرَارٍ وَتَعَلُّمٍ وَهُوَ كَقَوْلِ مَنْ يُرِيدُ مَالًا فَتَرَكَ الْحِرَاثَةَ وَالتِّجَارَةَ وَالْكَسْبَ وَيَتَعَطَّلُ،"]]},{"id":"bi32_11","label":"آدَابُ الرِّجْلَيْنِ · ١١","segs":[["matn","وَقَالَ: إِنَّ اللَّهَ كَرِيمٌ رَحِيمٌ وَلَهُ خَزَائِنُ السَّمَوَاتِ وَالْأَرْضِ وَهُوَ قَادِرٌ عَلَى أَنْ يُطْلِعَنِي عَلَى كَنْزٍ مِنْ كُنُوزٍ أَسْتَغْنِي بِهِ عَنِ الْكَسْبِ،"]]},{"id":"bi32_12","label":"آدَابُ الرِّجْلَيْنِ · ١٢","segs":[["matn","فَقَدْ فَعَلَ ذَلِكَ لِبَعْضِ عِبَادِهِ، فَأَنْتَ إِذَا سَمِعْتَ كَلَامَ هَذَيْنِ الرَّجُلَيْنِ اسْتَحْمَقْتَهُمَا وَسَخِرْتَ مِنْهُمَا، وَإِنْ كَانَ مَا وَصَفَاهُ مِنْ كَرَمِ اللَّهِ تَعَالَى وَقُدْرَتِهِ صِدْقًا وَحَقًّا، فَكَذَلِكَ يَضْحَكُ عَلَيْكَ أَرْبَابُ الْبَصَائِرِ فِي الدِّينِ إِذَا طَلَبْتَ الْمَغْفِرَةَ بِغَيْرِ سَعْيٍ لَهَا،"]]},{"id":"bi32_13","label":"آدَابُ الرِّجْلَيْنِ · ١٣","segs":[["matn","وَاللَّهُ تَعَالَى يَقُولُ: ﴿وَأَن لَّيْسَ لِلْإِنسَانِ إِلَّا مَا سَعَىٰ﴾، وَيَقُولُ: ﴿إِنَّمَا تُجْزَوْنَ مَا كُنتُمْ تَعْمَلُونَ﴾ وَيَقُولُ ﴿إِنَّ الْأَبْرَارَ لَفِي نَعِيمٍ وَإِنَّ الْفُجَّارَ لَفِي جَحِيمٍ﴾."]]},{"id":"bi32_14","label":"آدَابُ الرِّجْلَيْنِ · ١٤","segs":[["matn","فَإِذَا لَمْ تَكُنْ تَتْرُكُ السَّعْيَ فِي طَلَبِ الْعِلْمِ وَالْمَالِ اعْتِمَادًا عَلَى كَرَمِهِ، فَكَذَلِكَ لَا تَتْرُكِ التَّزَوُّدَ لِلْآخِرَةِ، وَلَا تَفْتُرْ؛"]]},{"id":"bi32_15","label":"آدَابُ الرِّجْلَيْنِ · ١٥","segs":[["matn","فَإِنَّ رَبَّ الدُّنْيَا وَالْآخِرَةِ وَاحِدٌ، وَهُوَ فِيهِمَا كَرِيمٌ رَحِيمٌ، وَلَيْسَ يَزِيدُ لَهُ كَرَمٌ بِطَاعَتِكَ وَإِنَّمَا كَرَمُهُ سُبْحَانَهُ وَتَعَالَى فِي أَنْ يُيَسِّرَ لَكَ طَرِيقَ الْوُصُولِ إِلَى الْمُلْكِ الْمُقِيمِ وَالنَّعِيمِ الدَّائِمِ الْمُخَلَّدِ، بِالصَّبْرِ عَلَى تَرْكِ الشَّهَوَاتِ أَيَّامًا قَلَائِلَ، وَهَذَا نِهَايَةُ الْكَرَمِ."]]},{"id":"bi32_16","label":"آدَابُ الرِّجْلَيْنِ · ١٦","segs":[["matn","فَلَا تُحَدِّثْ نَفْسَكَ بِتَهْوِيسَاتِ الْبَطَّالِينَ، وَاقْتَدِ بِأُولِي الْعَزْمِ وَالنُّهَى مِنَ الْأَنْبِيَاءِ وَالصَّالِحِينَ، وَلَا تَطْمَعْ فِي أَنْ تَحْصُدَ مَا لَمْ تَزْرَعْ، وَلَيْتَ مَنْ صَامَ وَصَلَّى وَجَاهَدَ وَاتَّقَى غُفِرَ لَهُ."]]},{"id":"bi32_17","label":"آدَابُ الرِّجْلَيْنِ · ١٧","segs":[["matn","فَهَذِهِ جُمَلٌ مِمَّا يَنْبَغِي أَنْ تَحْفَظَ عَنْهُ جَوَارِحَكَ الظَّاهِرَةَ، وَأَعْمَالُ هَذِهِ الْجَوَارِحِ إِنَّمَا تَتَرَشَّحُ مِنْ صِفَاتِ الْقَلْبِ؛"]]},{"id":"bi32_18","label":"آدَابُ الرِّجْلَيْنِ · ١٨","segs":[["matn","فَإِنْ أَرَدْتَ حِفْظَ الْجَوَارِحِ فَعَلَيْكَ بِتَطْهِيرِ الْقَلْبِ؛ فَهُوَ تَقْوَى الْبَاطِنِ، وَالْقَلْبُ هُوَ الْمُضْغَةُ الَّتِي إِذَا صَلَحَتْ صَلَحَ بِهَا سَائِرُ الْجَسَدِ، وَإِذَا فَسَدَتْ فَسَدَ بِهَا سَائِرُ الْجَسَدِ، فَاشْتَغِلْ بِإِصْلَاحِهِ لِتَصْلُحَ بِهِ جَوَارِحُكَ، وَصَلَاحُهُ يَكُونُ بِمُلَازَمَةِ الْمُرَاقَبَةِ."]]}],"group":"الْقِسْمُ الثَّانِي الْقَوْلُ فِي اجْتِنَابِ الْمَعَاصِي"},{"id":"bi33","title":"الْقَوْلُ فِي مَعَاصِي الْقَلْبِ","units":[{"id":"bi33_1","label":"الْقَوْلُ فِي مَعَاصِي الْقَلْبِ · ١","segs":[["matn","اعْلَمْ أَنَّ الصِّفَاتِ الْمَذْمُومَةَ فِي الْقَلْبِ كَثِيرَةٌ، وَطَرِيقَ تَطْهِيرِ الْقَلْبِ مِنْ رَذَائِلِهَا طَوِيلَةٌ، وَسَبِيلَ الْعِلَاجِ فِيهَا غَامِضٌ، وَقَدِ انْدَرَسَ بِالْكُلِّيَّةِ عِلْمُهُ وَعَمَلُهُ؛"]]},{"id":"bi33_2","label":"الْقَوْلُ فِي مَعَاصِي الْقَلْبِ · ٢","segs":[["matn","لِغَفْلَةِ الْخَلْقِ عَنْ أَنْفُسِهِمْ وَاشْتِغَالِهِمْ بِزَخَارِفِ الدُّنْيَا. وَقَدِ اسْتَقْصَيْنَا ذَلِكَ كُلَّهُ فِي كِتَابِ «إِحْيَاءِ عُلُومِ الدِّينِ» فِي رُبْعِ الْمُهْلِكَاتِ وَرُبْعِ الْمُنْجِيَاتِ، وَلَكِنَّا نُحَذِّرُكَ؛"]]},{"id":"bi33_3","label":"الْقَوْلُ فِي مَعَاصِي الْقَلْبِ · ٣","segs":[["matn","الْآنَ ثَلَاثًا مِنْ خَبَائِثِ الْقَلْبِ، وَهِيَ الْغَالِبَةُ عَلَى مُتَفَقِّهَةِ الْعَصْرِ، لِتَأْخُذَ مِنْهَا حِذْرَكَ، فَإِنَّهَا مُهْلِكَاتٌ فِي أَنْفُسِهَا، وَهِيَ أُمَّهَاتٌ لِجُمْلَةٍ مِنَ الْخَبَائِثِ سِوَاهَا: وَهِيَ الْحَسَدُ، وَالرِّيَاءُ، وَالْعُجْبُ؛"]]},{"id":"bi33_4","label":"الْقَوْلُ فِي مَعَاصِي الْقَلْبِ · ٤","segs":[["matn","فَاجْتَهِدْ فِي تَطْهِيرِ قَلْبِكَ مِنْهَا؛ فَإِنْ قَدَرْتَ عَلَيْهَا فَتَعَلَّمْ كَيْفِيَّةَ الْحَذَرِ مِنْ بَقِيَّتِهَا مِنْ رُبْعِ الْمُهْلِكَاتِ."]]},{"id":"bi33_5","label":"الْقَوْلُ فِي مَعَاصِي الْقَلْبِ · ٥","segs":[["matn","فَإِنْ عَجَزْتَ عَنْ هَذَا، فَأَنْتَ عَنْ غَيْرِهِ أَعْجَزُ."]]},{"id":"bi33_6","label":"الْقَوْلُ فِي مَعَاصِي الْقَلْبِ · ٦","segs":[["matn","وَلَا تَظُنَّ أَنَّكَ تَسْلَمُ بِنِيَّةٍ صَالِحَةٍ فِي تَعَلُّمِ الْعِلْمِ، وَفِي قَلْبِكَ شَيْءٌ مِنَ الْحَسَدِ وَالرِّيَاءِ وَالْعُجْبِ، وَقَدْ قَالَ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: «ثَلَاثٌ مُهْلِكَاتٌ: شُحٌّ مُطَاعٌ، وَهَوًى مُتَّبَعٌ، وَإِعْجَابُ الْمَرْءِ بِنَفْسِهِ»."]]}],"group":"الْقِسْمُ الثَّانِي الْقَوْلُ فِي اجْتِنَابِ الْمَعَاصِي"},{"id":"bi34","title":"الْحَسَدُ","units":[{"id":"bi34_1","label":"الْحَسَدُ · ١","segs":[["matn","أَمَّا الْحَسَدُ: فَهُوَ مُتَشَعِّبٌ مِنَ الشُّحِّ، فَإِنَّ الْبَخِيلَ هُوَ الَّذِي يَبْخَلُ بِمَا فِي يَدِهِ عَلَى غَيْرِهِ، وَالشَّحِيحَ هُوَ الَّذِي يَبْخَلُ بِنِعْمَةِ اللَّهِ تَعَالَى وَهِيَ فِي خَزَائِنِ قُدْرَتِهِ تَعَالَى، لَا فِي خَزَائِنِهِ، عَلَى عِبَادِ اللَّهِ فَشُحُّهُ أَعْظَمُ،"]]},{"id":"bi34_2","label":"الْحَسَدُ · ٢","segs":[["matn","وَالْحَسُودُ هُوَ الَّذِي يَشُقُّ عَلَيْهِ إِنْعَامُ اللَّهِ تَعَالَى مِنْ خَزَائِنِ قُدْرَتِهِ، عَلَى عَبْدٍ مِنْ عِبَادِهِ بِعِلْمٍ أَوْ مَالٍ أَوْ مَحَبَّةٍ فِي قُلُوبِ النَّاسِ، أَوْ حَظٍّ مِنَ الْحُظُوظِ، حَتَّى إِنَّهُ لَيُحِبُّ زَوَالَهَا عَنْهُ، وَإِنْ لَمْ يَحْصُلْ لَهُ بِذَلِكَ شَيْءٌ مِنْ تِلْكَ النِّعْمَةِ؛"]]},{"id":"bi34_3","label":"الْحَسَدُ · ٣","segs":[["matn","فَهَذَا مُنْتَهَى الْخُبْثِ؛ فَلِذَلِكَ قَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: «الْحَسَدُ يَأْكُلُ الْحَسَنَاتِ كَمَا تَأْكُلُ النَّارُ الْحَطَبَ»."]]},{"id":"bi34_4","label":"الْحَسَدُ · ٤","segs":[["matn","وَالْحَسُودُ هُوَ الْمُعَذَّبُ الَّذِي لَا يُرْحَمُ، وَلَا يَزَالُ فِي عَذَابٍ دَائِمٍ فِي الدُّنْيَا فَهِيَ لَا تَخْلُو مِنْ خَلْقٍ كَثِيرٍ مِنْ أَقْرَانِهِ وَمَعَارِفِهِ مِمَّنْ أَنْعَمَ اللَّهُ عَلَيْهِمْ بِعِلْمٍ أَوْ مَالٍ أَوْ جَاهٍ، فَلَا يَزَالُ فِي عَذَابٍ دَائِمٍ فِي الدُّنْيَا إِلَى مَوْتِهِ، وَلَعَذَابُ الْآخِرَةِ أَشَدُّ وَأَكْبَرُ."]]},{"id":"bi34_5","label":"الْحَسَدُ · ٥","segs":[["matn","بَلْ لَا يَصِلُ الْعَبْدُ إِلَى حَقِيقَةِ الْإِيمَانِ مَا لَمْ يُحِبَّ لِسَائِرِ النَّاسِ مَا يُحِبُّ لِنَفْسِهِ، بَلْ يَنْبَغِي أَنْ يُسَاهِمَ الْمُسْلِمِينَ فِي السَّرَّاءِ وَالضَّرَّاءِ؛"]]},{"id":"bi34_6","label":"الْحَسَدُ · ٦","segs":[["matn","فَالْمُسْلِمُونَ كَالْبُنْيَانِ الْوَاحِدِ يَشُدُّ بَعْضُهُ بَعْضًا، وَكَالْجَسَدِ الْوَاحِدِ إِذَا اشْتَكَى مِنْهُ عُضْوٌ اشْتَكَى سَائِرُ الْجَسَدِ."]]},{"id":"bi34_7","label":"الْحَسَدُ · ٧","segs":[["matn","فَإِنْ كُنْتَ لَا تُصَادِفُ هَذَا مِنْ قَلْبِكَ، فَاشْتِغَالُكَ بِطَلَبِ التَّخَلُّصِ مِنَ الْهَلَاكِ أَهَمُّ مِنِ اشْتِغَالِكَ بِنَوَادِرِ الْفُرُوعِ وَعِلْمِ الْخُصُومَاتِ."]]}],"group":"الْقِسْمُ الثَّانِي الْقَوْلُ فِي اجْتِنَابِ الْمَعَاصِي"},{"id":"bi35","title":"الرِّيَاءُ","units":[{"id":"bi35_1","label":"الرِّيَاءُ · ١","segs":[["matn","وَأَمَّا الرِّيَاءُ: فَهُوَ الشِّرْكُ الْخَفِيُّ، وَهُوَ أَحَدُ الشِّرْكَيْنِ، وَذَلِكَ طَلَبُ الْمَنْزِلَةِ فِي قُلُوبِ الْخَلْقِ، لِتَنَالَ بِهَا الْجَاهَ وَالْحِشْمَةَ، وَحُبُّ الْجَاهِ مِنَ الْهَوَى الْمُتَّبَعِ، وَفِيهِ هَلَكَ أَكْثَرُ النَّاسِ،"]]},{"id":"bi35_2","label":"الرِّيَاءُ · ٢","segs":[["matn","فَمَا أَهْلَكَ النَّاسَ إِلَّا النَّاسُ، وَلَوْ أَنْصَفَ النَّاسُ حَقِيقَةً لَعَلِمُوا أَنَّ أَكْثَرَ مَا هُمْ فِيهِ مِنَ الْعُلُومِ وَالْعِبَادَاتِ فَضْلًا عَنْ أَعْمَالِ الْعَادَاتِ،"]]},{"id":"bi35_3","label":"الرِّيَاءُ · ٣","segs":[["matn","لَيْسَ يَحْمِلُهَا عَلَيْهَا إِلَّا مُرَاءَاةُ النَّاسِ، وَهِيَ مُحْبِطَةٌ لِلْأَعْمَالِ، كَمَا وَرَدَ الْخَبَرُ: «أَنَّ الشَّهِيدَ يُؤْمَرُ بِهِ يَوْمَ الْقِيَامَةِ إِلَى النَّارِ، فَيَقُولُ: يَا رَبِّ اسْتُشْهِدْتُ فِي سَبِيلِكَ، فَيَقُولُ اللَّهُ تَعَالَى:"]]},{"id":"bi35_4","label":"الرِّيَاءُ · ٤","segs":[["matn","بَلْ أَرَدْتَ أَنْ يُقَالَ إِنَّكَ شُجَاعٌ، وَقَدْ قِيلَ ذَلِكَ، وَذَلِكَ أَجْرُكَ - وَكَذَلِكَ يُقَالُ لِلْعَالِمِ وَالْحَاجِّ وَالْقَارِئِ."]]}],"group":"الْقِسْمُ الثَّانِي الْقَوْلُ فِي اجْتِنَابِ الْمَعَاصِي"},{"id":"bi36","title":"الْعُجْبُ وَالْكِبْرُ وَالْفَخْرُ","units":[{"id":"bi36_1","label":"الْعُجْبُ وَالْكِبْرُ وَالْفَخْرُ · ١","segs":[["matn","وَأَمَّا الْعُجْبُ وَالْكِبْرُ وَالْفَخْرُ: فَهُوَ الدَّاءُ الْعُضَالُ، وَهُوَ نَظَرُ الْعَبْدِ إِلَى نَفْسِهِ بِعَيْنِ الْعِزَّةِ وَالِاسْتِعْظَامِ، وَإِلَى غَيْرِهِ بِعَيْنِ الِاحْتِقَارِ وَالذُّلِّ، وَنَتِيجَتُهُ عَلَى اللِّسَانِ أَنْ يَقُولَ: أَنَا وَأَنَا كَمَا قَالَ إِبْلِيسُ اللَّعِينُ:"]]},{"id":"bi36_2","label":"الْعُجْبُ وَالْكِبْرُ وَالْفَخْرُ · ٢","segs":[["matn","﴿أَنَا خَيْرٌ مِّنْهُ خَلَقْتَنِي مِن نَّارٍ وَخَلَقْتَهُ مِن طِينٍ﴾ وَثَمَرَتُهُ فِي الْمَجَالِسِ التَّرَفُّعُ وَالتَّقَدُّمُ وَطَلَبُ التَّصَدُّرِ فِيهَا، وَفِي الْمُحَاوَرَةِ الِاسْتِنْكَافُ مِنْ أَنْ يُرَدَّ كَلَامُهُ عَلَيْهِ."]]},{"id":"bi36_3","label":"الْعُجْبُ وَالْكِبْرُ وَالْفَخْرُ · ٣","segs":[["matn","وَالْمُتَكَبِّرُ هُوَ الَّذِي إِنْ وُعِظَ أَنِفَ، أَوْ وَعَظَ عَنُفَ، فَكُلُّ مَنْ رَأَى نَفْسَهُ خَيْرًا مِنْ أَحَدٍ مِنْ خَلْقِ اللَّهِ تَعَالَى فَهُوَ مُتَكَبِّرٌ."]]},{"id":"bi36_4","label":"الْعُجْبُ وَالْكِبْرُ وَالْفَخْرُ · ٤","segs":[["matn","بَلْ يَنْبَغِي لَكَ أَنْ تَعْلَمَ أَنَّ الْخَيِّرَ مَنْ هُوَ خَيِّرٌ عِنْدَ اللَّهِ فِي دَارِ الْآخِرَةِ، وَذَلِكَ غَيْبٌ، وَهُوَ مَوْقُوفٌ عَلَى الْخَاتِمَةِ؛"]]},{"id":"bi36_5","label":"الْعُجْبُ وَالْكِبْرُ وَالْفَخْرُ · ٥","segs":[["matn","فَاعْتِقَادُكَ فِي نَفْسِكَ أَنَّكَ خَيْرٌ مِنْ غَيْرِكَ جَهْلٌ مَحْضٌ، بَلْ يَنْبَغِي أَنْ لَا تَنْظُرَ إِلَى أَحَدٍ إِلَّا وَتَرَى أَنَّهُ خَيْرٌ مِنْكَ، وَأَنَّ الْفَضْلَ لَهُ عَلَى نَفْسِكَ، فَإِنْ رَأَيْتَ صَغِيرًا قُلْتَ: هَذَا لَمْ يَعْصِ اللَّهَ وَأَنَا عَصَيْتُهُ،"]]},{"id":"bi36_6","label":"الْعُجْبُ وَالْكِبْرُ وَالْفَخْرُ · ٦","segs":[["matn","فَلَا شَكَّ أَنَّهُ خَيْرٌ مِنِّي وَإِنْ رَأَيْتَ كَبِيرًا قُلْتَ هَذَا قَدْ عَبَدَ اللَّهَ قَبْلِي، فَلَا شَكَّ أَنَّهُ خَيْرٌ مِنِّي وَإِنْ كَانَ عَالِمًا قُلْتَ: هَذَا قَدْ أُعْطِيَ مَا لَمْ أُعْطَ، وَبَلَغَ مَا لَمْ أَبْلُغْ، وَعَلِمَ مَا جَهِلْتُ؛"]]},{"id":"bi36_7","label":"الْعُجْبُ وَالْكِبْرُ وَالْفَخْرُ · ٧","segs":[["matn","فَكَيْفَ أَكُونُ مِثْلَهُ وَإِنْ كَانَ جَاهِلًا قُلْتَ: هَذَا قَدْ عَصَى اللَّهَ بِجَهْلٍ، وَأَنَا عَصَيْتُهُ بِعِلْمٍ؛"]]},{"id":"bi36_8","label":"الْعُجْبُ وَالْكِبْرُ وَالْفَخْرُ · ٨","segs":[["matn","فَحُجَّةُ اللَّهِ عَلَيَّ آكَدُ، وَمَا أَدْرِي بِمَ يُخْتَمُ لِي وَبِمَ يُخْتَمُ لَهُ؟"]]},{"id":"bi36_9","label":"الْعُجْبُ وَالْكِبْرُ وَالْفَخْرُ · ٩","segs":[["matn","وَإِنْ كَانَ كَافِرًا قُلْتَ: لَا أَدْرِي، عَسَى أَنْ يُسْلِمَ وَيُخْتَمَ لَهُ بِخَيْرِ الْعَمَلِ، وَيَنْسَلَّ بِإِسْلَامِهِ مِنَ الذُّنُوبِ كَمَا تَنْسَلُّ الشَّعْرَةُ مِنَ الْعَجِينِ، وَأَمَّا أَنَا - وَالْعِيَاذُ بِاللَّهِ - فَعَسَى أَنْ يُضِلَّنِي اللَّهُ فَأَكْفُرَ فَيُخْتَمَ لِي بِشَرِّ الْعَمَلِ؛"]]},{"id":"bi36_10","label":"الْعُجْبُ وَالْكِبْرُ وَالْفَخْرُ · ١٠","segs":[["matn","فَيَكُونَ غَدًا هُوَ مِنَ الْمُقَرَّبِينَ، وَأَنَا أَكُونُ مِنَ الْمُبْعَدِينَ."]]},{"id":"bi36_11","label":"الْعُجْبُ وَالْكِبْرُ وَالْفَخْرُ · ١١","segs":[["matn","فَلَا يَخْرُجُ الْكِبْرُ مِنْ قَلْبِكَ إِلَّا بِأَنْ تَعْرِفَ أَنَّ الْكَبِيرَ مَنْ هُوَ كَبِيرٌ عِنْدَ اللَّهِ تَعَالَى، وَذَلِكَ مَوْقُوفٌ عَلَى الْخَاتِمَةِ، وَهِيَ مَشْكُوكٌ فِيهَا؛"]]},{"id":"bi36_12","label":"الْعُجْبُ وَالْكِبْرُ وَالْفَخْرُ · ١٢","segs":[["matn","فَيَشْغَلُكَ خَوْفُ الْخَاتِمَةِ عَنْ أَنْ تَتَكَبَّرَ مَعَ الشَّكِّ فِيهَا عَلَى عِبَادِ اللَّهِ تَعَالَى، فَيَقِينُكَ وَإِيمَانُكَ فِي الْحَالِ لَا يُنَاقِضُ تَجْوِيزَكَ التَّغَيُّرَ فِي الِاسْتِقْبَالِ؛"]]},{"id":"bi36_13","label":"الْعُجْبُ وَالْكِبْرُ وَالْفَخْرُ · ١٣","segs":[["matn","فَإِنَّ اللَّهَ مُقَلِّبُ الْقُلُوبِ يَهْدِي مَنْ يَشَاءُ، وَيُضِلُّ مَنْ يَشَاءُ."]]}],"group":"الْقِسْمُ الثَّانِي الْقَوْلُ فِي اجْتِنَابِ الْمَعَاصِي"},{"id":"bi37","title":"حَدِيثٌ جَامِعٌ فِي مَعَاصِي الْقَلْبِ","units":[{"id":"bi37_1","label":"حَدِيثٌ جَامِعٌ فِي مَعَاصِي الْقَلْبِ · ١","segs":[["matn","وَالْأَخْبَارُ فِي الْحَسَدِ وَالْكِبْرِ وَالرِّيَاءِ وَالْعُجْبِ كَثِيرَةٌ، وَيَكْفِيكَ فِيهَا حَدِيثٌ وَاحِدٌ جَامِعٌ؛"]]},{"id":"bi37_2","label":"حَدِيثٌ جَامِعٌ فِي مَعَاصِي الْقَلْبِ · ٢","segs":[["matn","فَقَدْ رَوَى ابْنُ الْمُبَارَكِ بِإِسْنَادِهِ عَنْ رَجُلٍ أَنَّهُ قَالَ لِمُعَاذٍ: يَا مُعَاذُ حَدِّثْنِي حَدِيثًا سَمِعْتَهُ مِنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، قَالَ: «فَبَكَى مُعَاذٌ حَتَّى ظَنَنْتُ أَنَّهُ لَا يَسْكُتُ،"]]},{"id":"bi37_3","label":"حَدِيثٌ جَامِعٌ فِي مَعَاصِي الْقَلْبِ · ٣","segs":[["matn","ثُمَّ سَكَتَ، ثُمَّ قَالَ: وَا شَوْقَاهُ إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَإِلَى لِقَائِهِ، ثُمَّ قَالَ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ لِي: «يَا مُعَاذُ،"]]},{"id":"bi37_4","label":"حَدِيثٌ جَامِعٌ فِي مَعَاصِي الْقَلْبِ · ٤","segs":[["matn","إِنِّي مُحَدِّثُكَ بِحَدِيثٍ إِنْ أَنْتَ حَفِظْتَهُ نَفَعَكَ عِنْدَ اللَّهِ، وَإِنْ ضَيَّعْتَهُ وَلَمْ تَحْفَظْهُ انْقَطَعَتْ حُجَّتُكَ عِنْدَ اللَّهِ تَعَالَى يَوْمَ الْقِيَامَةِ يَا مُعَاذُ إِنَّ اللَّهَ تَبَارَكَ وَتَعَالَى خَلَقَ سَبْعَةَ أَمْلَاكٍ قَبْلَ أَنْ يَخْلُقَ السَّمَوَاتِ وَالْأَرْضَ،"]]},{"id":"bi37_5","label":"حَدِيثٌ جَامِعٌ فِي مَعَاصِي الْقَلْبِ · ٥","segs":[["matn","فَجَعَلَ لِكُلِّ سَمَاءٍ مِنَ السَّبْعِ مَلَكًا بَوَّابًا عَلَيْهَا، فَتَصْعَدُ الْحَفَظَةُ بِعَمَلِ الْعَبْدِ مِنْ حِينِ يُصْبِحُ إِلَى حِينِ يُمْسِي، لَهُ نُورٌ كَنُورِ الشَّمْسِ، حَتَّى إِذَا صَعِدَتْ بِهِ إِلَى السَّمَاءِ الدُّنْيَا زَكَّتْهُ وَكَثَّرَتْهُ،"]]},{"id":"bi37_6","label":"حَدِيثٌ جَامِعٌ فِي مَعَاصِي الْقَلْبِ · ٦","segs":[["matn","فَيَقُولُ الْمَلَكُ الْمُوَكَّلُ بِهَا لِلْحَفَظَةِ: اضْرِبُوا بِهَذَا الْعَمَلِ وَجْهَ صَاحِبِهِ، أَنَا صَاحِبُ الْغِيبَةِ، أَمَرَنِي رَبِّي أَنْ لَا أَدَعَ عَمَلَ مَنِ اغْتَابَ النَّاسَ يُجَاوِزُنِي إِلَى غَيْرِي، قَالَ:"]]},{"id":"bi37_7","label":"حَدِيثٌ جَامِعٌ فِي مَعَاصِي الْقَلْبِ · ٧","segs":[["matn","ثُمَّ تَأْتِي الْحَفَظَةُ بِعَمَلٍ صَالِحٍ مِنْ أَعْمَالِ الْعَبْدِ لَهُ نُورٌ فَتُزَكِّيهِ وَتُكَثِّرُهُ حَتَّى تَبْلُغَ بِهِ إِلَى السَّمَاءِ الثَّانِيَةِ، فَيَقُولُ لَهُمُ الْمَلَكُ الْمُوَكَّلُ بِهَا: قِفُوا، وَاضْرِبُوا بِهَذَا الْعَمَلِ وَجْهَ صَاحِبِهِ، إِنَّهُ أَرَادَ بِعَمَلِهِ عَرَضَ الدُّنْيَا،"]]},{"id":"bi37_8","label":"حَدِيثٌ جَامِعٌ فِي مَعَاصِي الْقَلْبِ · ٨","segs":[["matn","أَنَا مَلَكُ الْفَخْرِ، أَمَرَنِي رَبِّي أَلَّا أَدَعَ عَمَلَهُ يُجَاوِزُنِي إِلَى غَيْرِي، إِنَّهُ كَانَ يَفْتَخِرُ عَلَى النَّاسِ فِي مَجَالِسِهِمْ، قَالَ: وَتَصْعَدُ الْحَفَظَةُ بِعَمَلِ الْعَبْدِ يَبْتَهِجُ نُورًا، مِنْ صَدَقَةٍ وَصَلَاةٍ وَصِيَامٍ، قَدْ أَعْجَبَ الْحَفَظَةَ،"]]},{"id":"bi37_9","label":"حَدِيثٌ جَامِعٌ فِي مَعَاصِي الْقَلْبِ · ٩","segs":[["matn","فَيُجَاوِزُونَ بِهِ إِلَى السَّمَاءِ الثَّالِثَةِ، فَيَقُولُ لَهُمُ الْمَلَكُ الْمُوَكَّلُ بِهَا: قِفُوا، وَاضْرِبُوا بِهَذَا الْعَمَلِ وَجْهَ صَاحِبِهِ، أَنَا مَلَكُ الْكِبْرِ، أَمَرَنِي رَبِّي أَنْ لَا أَدَعَ عَمَلَهُ يُجَاوِزُنِي إِلَى غَيْرِي؛"]]},{"id":"bi37_10","label":"حَدِيثٌ جَامِعٌ فِي مَعَاصِي الْقَلْبِ · ١٠","segs":[["matn","إِنَّهُ كَانَ يَتَكَبَّرُ عَلَى النَّاسِ فِي مَجَالِسِهِمْ، قَالَ: وَتَصْعَدُ الْحَفَظَةُ بِعَمَلِ الْعَبْدِ يَزْهُو كَمَا يَزْهُو الْكَوْكَبُ الدُّرِّيُّ وَلَهُ دَوِيٌّ مِنْ تَسْبِيحٍ وَصَلَاةٍ وَصِيَامٍ وَحَجٍّ وَعُمْرَةٍ، حَتَّى يُجَاوِزُوا بِهِ إِلَى السَّمَاءِ الرَّابِعَةِ،"]]},{"id":"bi37_11","label":"حَدِيثٌ جَامِعٌ فِي مَعَاصِي الْقَلْبِ · ١١","segs":[["matn","فَيَقُولُ لَهُمُ الْمَلَكُ الْمُوَكَّلُ بِهَا: قِفُوا، وَاضْرِبُوا بِهَذَا الْعَمَلِ وَجْهَ صَاحِبِهِ وَظَهْرَهُ وَبَطْنَهُ، أَنَا صَاحِبُ الْعُجْبِ، أَمَرَنِي رَبِّي أَنْ لَا أَدَعَ عَمَلَهُ يُجَاوِزُنِي إِلَى غَيْرِي؛"]]},{"id":"bi37_12","label":"حَدِيثٌ جَامِعٌ فِي مَعَاصِي الْقَلْبِ · ١٢","segs":[["matn","إِنَّهُ كَانَ إِذَا عَمِلَ عَمَلًا أَدْخَلَ الْعُجْبَ فِيهِ، قَالَ: وَتَصْعَدُ الْحَفَظَةُ بِعَمَلِ الْعَبْدِ حَتَّى يُجَاوِزُوا بِهِ إِلَى السَّمَاءِ الْخَامِسَةِ كَأَنَّهُ الْعَرُوسُ الْمَزْفُوفَةُ إِلَى بَعْلِهَا، فَيَقُولُ الْمَلَكُ الْمُوَكَّلُ بِهَا: قِفُوا وَاضْرِبُوا بِهَذَا الْعَمَلِ وَجْهَ صَاحِبِهِ،"]]},{"id":"bi37_13","label":"حَدِيثٌ جَامِعٌ فِي مَعَاصِي الْقَلْبِ · ١٣","segs":[["matn","وَاحْمِلُوهُ عَلَى عَاتِقِهِ، أَنَا مَلَكُ الْحَسَدِ، إِنَّهُ كَانَ يَحْسُدُ مَنْ يَتَعَلَّمُ وَيَعْمَلُ بِمِثْلِ عَمَلِهِ، وَكُلَّ مَنْ كَانَ يَأْخُذُ فَضْلًا مِنَ الْعِبَادَةِ كَانَ يَحْسُدُهُمْ، وَيَقَعُ فِيهِمْ، أَمَرَنِي رَبِّي أَنْ لَا أَدَعَ عَمَلَهُ يُجَاوِزُنِي إِلَى غَيْرِي."]]},{"id":"bi37_14","label":"حَدِيثٌ جَامِعٌ فِي مَعَاصِي الْقَلْبِ · ١٤","segs":[["matn","قَالَ: وَتَصْعَدُ الْحَفَظَةُ بِعَمَلِ الْعَبْدِ لَهُ ضَوْءٌ كَضَوْءِ الشَّمْسِ، مِنْ صَلَاةٍ وَزَكَاةٍ وَحَجٍّ وَعُمْرَةٍ وَجِهَادٍ وَصِيَامٍ، فَيُجَاوِزُونَ بِهِ إِلَى السَّمَاءِ السَّادِسَةِ، فَيَقُولُ لَهُمُ الْمَلَكُ الْمُوَكَّلُ بِهَا: قِفُوا وَاضْرِبُوا بِهَذَا الْعَمَلِ وَجْهَ صَاحِبِهِ؛"]]},{"id":"bi37_15","label":"حَدِيثٌ جَامِعٌ فِي مَعَاصِي الْقَلْبِ · ١٥","segs":[["matn","إِنَّهُ كَانَ لَا يَرْحَمُ إِنْسَانًا قَطُّ مِنْ عِبَادِ اللَّهِ أَصَابَهُ بَلَاءٌ أَوْ مَرَضٌ، بَلْ كَانَ يَشْمَتُ بِهِ، أَنَا مَلَكُ الرَّحْمَةِ، أَمَرَنِي رَبِّي أَنْ لَا أَدَعَ عَمَلَهُ يُجَاوِزُنِي إِلَى غَيْرِي، قَالَ: وَتَصْعَدُ الْحَفَظَةُ بِعَمَلِ الْعَبْدِ مِنْ صَوْمٍ وَصَلَاةٍ وَنَفَقَةٍ وَجِهَادٍ وَوَرَعٍ، لَهُ دَوِيٌّ كَدَوِيِّ النَّحْلِ،"]]},{"id":"bi37_16","label":"حَدِيثٌ جَامِعٌ فِي مَعَاصِي الْقَلْبِ · ١٦","segs":[["matn","وَضَوْءٌ كَضَوْءِ الشَّمْسِ، وَمَعَهُ ثَلَاثَةُ آلَافِ مَلَكٍ، فَيُجَاوِزُونَ بِهِ إِلَى السَّمَاءِ السَّابِعَةِ، فَيَقُولُ لَهُمُ الْمَلَكُ الْمُوَكَّلُ بِهَا: قِفُوا، وَاضْرِبُوا بِهَذَا الْعَمَلِ وَجْهَ صَاحِبِهِ، وَاضْرِبُوا جَوَارِحَهُ وَاقْفِلُوا بِهِ عَلَى قَلْبِهِ، أَنَا صَاحِبُ الذِّكْرِ، فَإِنِّي أَحْجُبُ عَنْ رَبِّي كُلَّ عَمَلٍ لَمْ يُرَدْ بِهِ وَجْهُ رَبِّي؛"]]},{"id":"bi37_17","label":"حَدِيثٌ جَامِعٌ فِي مَعَاصِي الْقَلْبِ · ١٧","segs":[["matn","إِنَّهُ إِنَّمَا أَرَادَ بِعَمَلِهِ غَيْرَ اللَّهِ تَعَالَى، إِنَّهُ أَرَادَ بِهِ رِفْعَةً عِنْدَ الْفُقَهَاءِ، وَذِكْرًا عِنْدَ الْعُلَمَاءِ، وَصِيتًا فِي الْمَدَائِنِ، أَمَرَنِي رَبِّي أَنْ لَا أَدَعَ عَمَلَهُ يُجَاوِزُنِي إِلَى غَيْرِي وَكُلُّ عَمَلٍ لَمْ يَكُنْ لِلَّهِ تَعَالَى خَالِصًا فَهُوَ رِيَاءٌ، وَلَا يَقْبَلُ اللَّهُ عَمَلَ الْمُرَائِي، قَالَ:"]]},{"id":"bi37_18","label":"حَدِيثٌ جَامِعٌ فِي مَعَاصِي الْقَلْبِ · ١٨","segs":[["matn","وَتَصْعَدُ الْحَفَظَةُ بِعَمَلِ الْعَبْدِ مِنْ صَلَاةٍ وَزَكَاةٍ وَصِيَامٍ وَحَجٍّ وَعُمْرَةٍ وَخُلُقٍ حَسَنٍ وَصَمْتٍ وَذِكْرِ اللَّهِ تَعَالَى، فَتُشَيِّعُهُ مَلَائِكَةُ السَّمَوَاتِ السَّبْعِ حَتَّى يَقْطَعُوا بِهِ الْحُجُبَ كُلَّهَا إِلَى اللَّهِ تَعَالَى،"]]},{"id":"bi37_19","label":"حَدِيثٌ جَامِعٌ فِي مَعَاصِي الْقَلْبِ · ١٩","segs":[["matn","فَيَقِفُونَ بَيْنَ يَدَيْهِ، وَيَشْهَدُونَ لَهُ بِالْعَمَلِ الصَّالِحِ الْمُخْلَصِ لِلَّهِ تَعَالَى، فَيَقُولُ اللَّهُ تَعَالَى: أَنْتُمُ الْحَفَظَةُ عَلَى عَمَلِ عَبْدِي، وَأَنَا الرَّقِيبُ عَلَى مَا فِي قَلْبِهِ؛"]]},{"id":"bi37_20","label":"حَدِيثٌ جَامِعٌ فِي مَعَاصِي الْقَلْبِ · ٢٠","segs":[["matn","إِنَّهُ لَمْ يُرِدْنِي بِهَذَا الْعَمَلِ، وَإِنَّمَا أَرَادَ بِهِ غَيْرِي، فَعَلَيْهِ لَعْنَتِي، فَتَقُولُ الْمَلَائِكَةُ كُلُّهَا: عَلَيْهِ لَعْنَتُكَ وَلَعْنَتُنَا، فَتَلْعَنُهُ السَّمَوَاتُ السَّبْعُ وَمَنْ فِيهِنَّ» ثُمَّ بَكَى مُعَاذٌ، وَانْتَحَبَ انْتِحَابًا شَدِيدًا، وَقَالَ مُعَاذٌ: قُلْتُ يَا رَسُولَ اللَّهِ أَنْتَ رَسُولُ اللَّهِ وَأَنَا مُعَاذٌ، فَكَيْفَ لِي بِالنَّجَاةِ وَالْخَلَاصِ مِنْ ذَلِكَ؟"]]},{"id":"bi37_21","label":"حَدِيثٌ جَامِعٌ فِي مَعَاصِي الْقَلْبِ · ٢١","segs":[["matn","قَالَ: «اقْتَدِ بِي وَإِنْ كَانَ فِي عَمَلِكَ نَقْصٌ، يَا مُعَاذُ حَافِظْ عَلَى لِسَانِكَ مِنَ الْوَقِيعَةِ فِي إِخْوَانِكَ مِنْ حَمَلَةِ الْقُرْآنِ خَاصَّةً، وَاحْمِلْ ذُنُوبَكَ عَلَيْكَ،"]]},{"id":"bi37_22","label":"حَدِيثٌ جَامِعٌ فِي مَعَاصِي الْقَلْبِ · ٢٢","segs":[["matn","وَلَا تَحْمِلْهَا عَلَيْهِمْ، وَلَا تُزِلَّ نَفْسَكَ بِذَمِّهِمْ، وَلَا تَرْفَعْ نَفْسَكَ عَلَيْهِمْ، وَلَا تُدْخِلْ عَمَلَ الدُّنْيَا فِي عَمَلِ الْآخِرَةِ، وَلَا تُرَاءِ بِعَمَلِكَ، وَلَا تَتَكَبَّرْ فِي مَجْلِسِكَ،"]]},{"id":"bi37_23","label":"حَدِيثٌ جَامِعٌ فِي مَعَاصِي الْقَلْبِ · ٢٣","segs":[["matn","لِكَيْ يَحْذَرَ النَّاسُ مِنْ سُوءِ خُلُقِكَ، وَلَا تُنَاجِ رَجُلًا وَعِنْدَكَ آخَرُ، وَلَا تَتَعَظَّمْ عَلَى النَّاسِ فَتَنْقَطِعَ عَنْكَ خَيْرَاتُ الدُّنْيَا وَالْآخِرَةِ، وَلَا تُمَزِّقِ النَّاسَ بِلِسَانِكَ فَتُمَزِّقَكَ كِلَابُ النَّارِ يَوْمَ الْقِيَامَةِ فِي النَّارِ،"]]},{"id":"bi37_24","label":"حَدِيثٌ جَامِعٌ فِي مَعَاصِي الْقَلْبِ · ٢٤","segs":[["matn","قَالَ اللَّهُ تَعَالَى: «وَالنَّاشِطَاتِ نَشْطًا»، هَلْ تَدْرِي مَا هُنَّ يَا مُعَاذُ؟، قُلْتُ: مَا هُنَّ - بِأَبِي أَنْتَ وَأُمِّي - يَا رَسُولَ اللَّهِ؟"]]},{"id":"bi37_25","label":"حَدِيثٌ جَامِعٌ فِي مَعَاصِي الْقَلْبِ · ٢٥","segs":[["matn","قَالَ: «كِلَابٌ فِي النَّارِ تَنْشِطُ اللَّحْمَ مِنَ الْعَظْمِ»، قُلْتُ: بِأَبِي أَنْتَ وَأُمِّي يَا رَسُولَ اللَّهِ، مَنْ يُطِيقُ هَذِهِ الْخِصَالَ وَمَنْ يَنْجُو مِنْهَا؟"]]},{"id":"bi37_26","label":"حَدِيثٌ جَامِعٌ فِي مَعَاصِي الْقَلْبِ · ٢٦","segs":[["matn","قَالَ: «يَا مُعَاذُ إِنَّهُ لَيَسِيرٌ عَلَى مَنْ يَسَّرَهُ اللَّهُ تَعَالَى عَلَيْهِ، إِنَّمَا يَكْفِيكَ مِنْ ذَلِكَ أَنْ تُحِبَّ لِلنَّاسِ مَا تُحِبُّ لِنَفْسِكَ، وَتَكْرَهَ لَهُمْ مَا تَكْرَهُ لِنَفْسِكَ، فَإِذَنْ أَنْتَ يَا مُعَاذُ قَدْ سَلِمْتَ»."]]},{"id":"bi37_27","label":"حَدِيثٌ جَامِعٌ فِي مَعَاصِي الْقَلْبِ · ٢٧","segs":[["matn","قَالَ خَالِدُ بْنُ مَعْدَانَ: فَمَا رَأَيْتُ أَحَدًا أَكْثَرَ تِلَاوَةً لِلْقُرْآنِ الْعَظِيمِ مِنْ مُعَاذٍ لِهَذَا الْحَدِيثِ الْعَظِيمِ."]]},{"id":"bi37_28","label":"حَدِيثٌ جَامِعٌ فِي مَعَاصِي الْقَلْبِ · ٢٨","segs":[["matn","فَتَأَمَّلْ أَيُّهَا الرَّاغِبُ فِي الْعِلْمِ هَذِهِ الْخِصَالَ، وَاعْلَمْ أَنَّ أَعْظَمَ الْأَسْبَابِ فِي رُسُوخِ هَذِهِ الْخَبَائِثِ فِي الْقَلْبِ: طَلَبُ الْعِلْمِ لِأَجْلِ الْمُبَاهَاةِ وَالْمُنَافَسَةِ، فَالْعَامِّيُّ بِمَعْزِلٍ عَنْ أَكْثَرِ هَذِهِ الْخِصَالِ، وَالْمُتَفَقِّهُ مُسْتَهْدَفٌ لَهَا، وَهُوَ مُتَعَرِّضٌ لِلْهَلَاكِ بِسَبَبِهَا؛"]]},{"id":"bi37_29","label":"حَدِيثٌ جَامِعٌ فِي مَعَاصِي الْقَلْبِ · ٢٩","segs":[["matn","فَانْظُرْ أَيُّ أُمُورِكَ أَهَمُّ، أَتَتَعَلَّمُ كَيْفِيَّةَ الْحَذَرِ مِنْ هَذِهِ الْمُهْلِكَاتِ، وَتَشْتَغِلُ بِإِصْلَاحِ قَلْبِكَ وَعِمَارَةِ آخِرَتِكَ؟"]]},{"id":"bi37_30","label":"حَدِيثٌ جَامِعٌ فِي مَعَاصِي الْقَلْبِ · ٣٠","segs":[["matn","أَمِ الْأَهَمُّ أَنْ تَخُوضَ مَعَ الْخَائِضِينَ، فَتَطْلُبَ مِنَ الْعِلْمِ مَا هُوَ سَبَبُ زِيَادَةِ الْكِبْرِ وَالرِّيَاءِ وَالْحَسَدِ وَالْعُجْبِ، حَتَّى تَهْلِكَ مَعَ الْهَالِكِينَ."]]},{"id":"bi37_31","label":"حَدِيثٌ جَامِعٌ فِي مَعَاصِي الْقَلْبِ · ٣١","segs":[["matn","وَاعْلَمْ أَنَّ هَذِهِ الْخِصَالَ الثَّلَاثَ مِنْ أُمَّهَاتِ خَبَائِثِ الْقَلْبِ، وَلَهَا مَغْرِسٌ وَاحِدٌ، وَهُوَ حُبُّ الدُّنْيَا وَلِذَلِكَ قَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: «حُبُّ الدُّنْيَا رَأْسُ كُلِّ خَطِيئَةٍ»، وَمَعَ هَذَا فَالدُّنْيَا مَزْرَعَةٌ لِلْآخِرَةِ فَمَنْ أَخَذَ مِنَ الدُّنْيَا بِقَدْرِ الضَّرُورَةِ، لِيَسْتَعِينَ بِهَا عَلَى الْآخِرَةِ، فَالدُّنْيَا مَزْرَعَتُهُ؛"]]},{"id":"bi37_32","label":"حَدِيثٌ جَامِعٌ فِي مَعَاصِي الْقَلْبِ · ٣٢","segs":[["matn","وَمَنْ أَرَادَ الدُّنْيَا لِيَتَنَعَّمَ بِهَا، فَالدُّنْيَا مَهْلَكَتُهُ. فَهَذِهِ نُبْذَةٌ يَسِيرَةٌ مِنْ ظَاهِرِ عِلْمِ التَّقْوَى، وَهِيَ بِدَايَةُ الْهِدَايَةِ، فَإِنْ جَرَّبْتَ بِهَا نَفْسَكَ وَطَاوَعَتْكَ عَلَيْهَا، فَعَلَيْكَ بِكِتَابِ «إِحْيَاءِ عُلُومِ الدِّينِ» لِتَعْرِفَ كَيْفِيَّةَ الْوُصُولِ إِلَى بَاطِنِ التَّقْوَى."]]},{"id":"bi37_33","label":"حَدِيثٌ جَامِعٌ فِي مَعَاصِي الْقَلْبِ · ٣٣","segs":[["matn","وَإِنْ كُنْتَ تَطْلُبُ الْعِلْمَ مِنَ الْقِيلِ وَالْقَالِ، وَالْمِرَاءِ وَالْجِدَالِ، فَمَا أَعْظَمَ مُصِيبَتَكَ وَمَا أَطْوَلَ تَعَبَكَ وَمَا أَعْظَمَ حِرْمَانَكَ وَخُسْرَانَكَ!"]]},{"id":"bi37_34","label":"حَدِيثٌ جَامِعٌ فِي مَعَاصِي الْقَلْبِ · ٣٤","segs":[["matn","فَاعْمَلْ مَا شِئْتَ؛ فَإِنَّ الدُّنْيَا الَّتِي تَطْلُبُهَا بِالدِّينِ لَا تَسْلَمُ لَكَ، وَالْآخِرَةُ تُسْلَبُ مِنْكَ؛"]]},{"id":"bi37_35","label":"حَدِيثٌ جَامِعٌ فِي مَعَاصِي الْقَلْبِ · ٣٥","segs":[["matn","فَمَنْ طَلَبَ الدُّنْيَا بِالدِّينِ خَسِرَهُمَا جَمِيعًا، وَمَنْ تَرَكَ الدُّنْيَا لِلدِّينِ رَبِحَهُمَا جَمِيعًا."]]},{"id":"bi37_36","label":"حَدِيثٌ جَامِعٌ فِي مَعَاصِي الْقَلْبِ · ٣٦","segs":[["matn","فَإِذَا عَمَرْتَ بِالتَّقْوَى بَاطِنَ قَلْبِكَ، فَعِنْدَ ذَلِكَ تَرْتَفِعُ الْحُجُبُ بَيْنَكَ وَبَيْنَ رَبِّكَ، وَتَنْكَشِفُ لَكَ أَنْوَارُ الْمَعَارِفِ، وَتَتَفَجَّرُ مِنْ قَلْبِكَ يَنَابِيعُ الْحِكَمِ، وَتَتَّضِحُ لَكَ أَسْرَارُ الْمُلْكِ وَالْمَلَكُوتِ،"]]},{"id":"bi37_37","label":"حَدِيثٌ جَامِعٌ فِي مَعَاصِي الْقَلْبِ · ٣٧","segs":[["matn","وَيَتَيَسَّرُ لَكَ مِنَ الْعُلُومِ مَا تَسْتَحْقِرُ بِهِ هَذِهِ الْعُلُومَ الْمُحْدَثَةَ الَّتِي لَمْ يَكُنْ لَهَا ذِكْرٌ فِي زَمَنِ الصَّحَابَةِ رَضِيَ اللَّهُ عَنْهُمْ وَالتَّابِعِينَ."]]},{"id":"bi37_38","label":"حَدِيثٌ جَامِعٌ فِي مَعَاصِي الْقَلْبِ · ٣٨","segs":[["matn","فَهَذِهِ جُمَلُ الْهِدَايَةِ إِلَى بِدَايَةِ الطَّرِيقِ فِي مُعَامَلَتِكَ مَعَ اللَّهِ تَعَالَى بِأَدَاءِ أَوَامِرِهِ وَاجْتِنَابِ نَوَاهِيهِ، وَأُشِيرُ عَلَيْكَ الْآنَ بِجُمَلٍ مِنَ الْآدَابِ لِتُؤَاخِذَ نَفْسَكَ بِهَا فِي مُخَالَطَتِكَ مَعَ عِبَادِ اللَّهِ تَعَالَى وَصُحْبَتِكَ مَعَهُمْ فِي الدُّنْيَا."]]}],"group":"الْقِسْمُ الثَّانِي الْقَوْلُ فِي اجْتِنَابِ الْمَعَاصِي"},{"id":"bi38","title":"آدَابُ الصُّحْبَةِ مَعَ اللَّهِ تَعَالَى","units":[{"id":"bi38_1","label":"آدَابُ الصُّحْبَةِ مَعَ اللَّهِ تَعَالَى · ١","segs":[["matn","اعْلَمْ أَنَّ صَاحِبَكَ الَّذِي لَا يُفَارِقُكَ فِي حَضَرِكَ وَسَفَرِكَ وَنَوْمِكَ وَيَقَظَتِكَ، بَلْ فِي حَيَاتِكَ وَمَوْتِكَ، هُوَ رَبُّكَ وَسَيِّدُكَ وَمَوْلَاكَ وَخَالِقُكَ، وَمَهْمَا ذَكَرْتَهُ فَهُوَ جَلِيسُكَ؛"]]},{"id":"bi38_2","label":"آدَابُ الصُّحْبَةِ مَعَ اللَّهِ تَعَالَى · ٢","segs":[["matn","إِذْ قَالَ اللَّهُ تَعَالَى: «أَنَا جَلِيسُ مَنْ ذَكَرَنِي»."]]},{"id":"bi38_3","label":"آدَابُ الصُّحْبَةِ مَعَ اللَّهِ تَعَالَى · ٣","segs":[["matn","وَمَهْمَا انْكَسَرَ قَلْبُكَ حُزْنًا عَلَى تَقْصِيرِكَ فِي حَقِّ دِينِكَ، فَهُوَ صَاحِبُكَ وَمُلَازِمُكَ؛"]]},{"id":"bi38_4","label":"آدَابُ الصُّحْبَةِ مَعَ اللَّهِ تَعَالَى · ٤","segs":[["matn","إِذْ قَالَ اللَّهُ تَعَالَى: «أَنَا عِنْدَ الْمُنْكَسِرَةِ قُلُوبُهُمْ مِنْ أَجْلِي»."]]},{"id":"bi38_5","label":"آدَابُ الصُّحْبَةِ مَعَ اللَّهِ تَعَالَى · ٥","segs":[["matn","فَلَوْ عَرَفْتَهُ حَقَّ مَعْرِفَتِهِ لَاتَّخَذْتَهُ صَاحِبًا وَتَرَكْتَ النَّاسَ جَانِبًا."]]},{"id":"bi38_6","label":"آدَابُ الصُّحْبَةِ مَعَ اللَّهِ تَعَالَى · ٦","segs":[["matn","فَإِنْ لَمْ تَقْدِرْ عَلَى ذَلِكَ فِي جَمِيعِ أَوْقَاتِكَ، فَإِيَّاكَ أَنْ تُخْلِيَ لَيْلَكَ وَنَهَارَكَ عَنْ وَقْتٍ تَخْلُو فِيهِ لِمَوْلَاكَ وَتَتَلَذَّذُ مَعَهُ بِمُنَاجَاتِكَ لَهُ، وَعِنْدَ ذَلِكَ فَعَلَيْكَ أَنْ تَتَعَلَّمَ آدَابَ الصُّحْبَةِ مَعَ اللَّهِ تَعَالَى."]]},{"id":"bi38_7","label":"آدَابُ الصُّحْبَةِ مَعَ اللَّهِ تَعَالَى · ٧","segs":[["matn","وَآدَابُهَا: إِطْرَاقُ الرَّأْسِ، وَغَضُّ الطَّرْفِ، وَجَمْعُ الْهَمِّ، وَدَوَامُ الصَّمْتِ، وَسُكُونُ الْجَوَارِحِ، وَمُبَادَرَةُ الْأَمْرِ، وَاجْتِنَابُ النَّهْيِ، وَقِلَّةُ الِاعْتِرَاضِ عَلَى الْقَدَرِ، وَدَوَامُ الذِّكْرِ، وَمُلَازَمَةُ الْفِكْرِ، وَإِيثَارُ الْحَقِّ عَلَى الْبَاطِلِ،"]]},{"id":"bi38_8","label":"آدَابُ الصُّحْبَةِ مَعَ اللَّهِ تَعَالَى · ٨","segs":[["matn","وَالْإِيَاسُ عَنِ الْخَلْقِ، وَالْخُضُوعُ تَحْتَ الْهَيْبَةِ وَالِانْكِسَارُ تَحْتَ الْحَيَاءِ، وَالسُّكُونُ عَنْ حِيَلِ الْكَسْبِ ثِقَةً بِالضَّمَانِ وَالتَّوَكُّلُ عَلَى فَضْلِ اللَّهِ تَعَالَى مَعْرِفَةً بِحُسْنِ الِاخْتِيَارِ."]]},{"id":"bi38_9","label":"آدَابُ الصُّحْبَةِ مَعَ اللَّهِ تَعَالَى · ٩","segs":[["matn","وَهَذَا كُلُّهُ يَنْبَغِي أَنْ يَكُونَ شِعَارَكَ فِي جَمِيعِ لَيْلِكَ وَنَهَارِكَ؛"]]},{"id":"bi38_10","label":"آدَابُ الصُّحْبَةِ مَعَ اللَّهِ تَعَالَى · ١٠","segs":[["matn","فَإِنَّهَا آدَابُ الصُّحْبَةِ مَعَ صَاحِبٍ لَا يُفَارِقُكَ، وَالْخَلْقُ كُلُّهُمْ يُفَارِقُونَكَ فِي بَعْضِ أَوْقَاتِكَ."]]}],"group":"الْقِسْمُ الثَّالِثُ الْقَوْلُ فِي آدَابِ الصُّحْبَةِ"},{"id":"bi39","title":"آدَابُ الْعَالِمِ","units":[{"id":"bi39_1","label":"آدَابُ الْعَالِمِ · ١","segs":[["matn","وَإِنْ كُنْتَ عَالِمًا، فَآدَابُ الْعَالِمِ: الِاحْتِمَالُ، وَلُزُومُ الْحِلْمِ، وَالْجُلُوسُ بِالْهَيْبَةِ عَلَى سَمْتِ الْوَقَارِ مَعَ إِطْرَاقِ الرَّأْسِ، وَتَرْكُ التَّكَبُّرِ عَلَى جَمِيعِ الْعِبَادِ إِلَّا عَلَى الظَّلَمَةِ زَجْرًا لَهُمْ عَنِ الظُّلْمِ،"]]},{"id":"bi39_2","label":"آدَابُ الْعَالِمِ · ٢","segs":[["matn","وَإِيثَارًا لِلتَّوَاضُعِ فِي الْمَحَافِلِ وَالْمَجَالِسِ، وَتَرْكُ الْهَزْلِ وَالدُّعَابَةِ، وَالرِّفْقُ بِالْمُتَعَلِّمِ، وَالتَّأَنِّي بِالْمُتَعَجْرِفِ، وَإِصْلَاحُ الْبَلِيدِ بِحُسْنِ الْإِرْشَادِ، وَتَرْكُ الْحَرَدِ عَلَيْهِ، وَتَرْكُ الْأَنَفَةِ مِنْ قَوْلِ: «لَا أَدْرِي» وَصَرْفُ الْهِمَّةِ إِلَى السَّائِلِ وَتَفَهُّمُ سُؤَالِهِ،"]]},{"id":"bi39_3","label":"آدَابُ الْعَالِمِ · ٣","segs":[["matn","وَقَبُولُ الْحُجَّةِ، وَالِانْقِيَادُ لِلْحَقِّ، وَالرُّجُوعُ إِلَيْهِ عِنْدَ الْهَفْوَةِ، وَمَنْعُ الْمُتَعَلِّمِ عَنْ كُلِّ عِلْمٍ يَضُرُّهُ، وَزَجْرُهُ عَنْ أَنْ يُرِيدَ بِالْعِلْمِ النَّافِعِ غَيْرَ وَجْهِ اللَّهِ تَعَالَى،"]]},{"id":"bi39_4","label":"آدَابُ الْعَالِمِ · ٤","segs":[["matn","وَصَدُّ الْمُتَعَلِّمِ عَنْ أَنْ يَشْتَغِلَ بِفَرْضِ الْكِفَايَةِ قَبْلَ الْفَرَاغِ مِنْ فَرْضِ الْعَيْنِ، وَفَرْضُ عَيْنِهِ إِصْلَاحُ ظَاهِرِهِ وَبَاطِنِهِ بِالتَّقْوَى، وَمُؤَاخَذَةُ نَفْسِهِ أَوَّلًا بِالتَّقْوَى لِيَقْتَدِيَ الْمُتَعَلِّمُ أَوَّلًا بِأَعْمَالِهِ، وَيَسْتَفِيدَ ثَانِيًا مِنْ أَقْوَالِهِ."]]}],"group":"الْقِسْمُ الثَّالِثُ الْقَوْلُ فِي آدَابِ الصُّحْبَةِ"},{"id":"bi40","title":"آدَابُ الْمُتَعَلِّمِ","units":[{"id":"bi40_1","label":"آدَابُ الْمُتَعَلِّمِ · ١","segs":[["matn","وَإِنْ كُنْتَ مُتَعَلِّمًا، فَآدَابُ الْمُتَعَلِّمِ مَعَ الْعَالِمِ: أَنْ يَبْدَأَهُ بِالتَّحِيَّةِ وَالسَّلَامِ، وَأَنْ يُقَلِّلَ بَيْنَ يَدَيْهِ الْكَلَامَ، وَلَا يَتَكَلَّمَ مَا لَمْ يَسْأَلْهُ أُسْتَاذُهُ، وَلَا يَسْأَلَ مَا لَمْ يَسْتَأْذِنْ أَوَّلًا، وَلَا يَقُولَ فِي مُعَارَضَةِ قَوْلِهِ:"]]},{"id":"bi40_2","label":"آدَابُ الْمُتَعَلِّمِ · ٢","segs":[["matn","قَالَ فُلَانٌ بِخِلَافِ مَا قُلْتَ، وَلَا يُشِيرَ عَلَيْهِ بِخِلَافِ رَأْيِهِ فَيَرَى أَنَّهُ أَعْلَمُ بِالصَّوَابِ مِنْ أُسْتَاذِهِ، وَلَا يَسْأَلَ جَلِيسَهُ فِي مَجْلِسِهِ، وَلَا يَلْتَفِتَ إِلَى الْجَوَانِبِ، بَلْ يَجْلِسُ مُطْرِقًا سَاكِنًا مُتَأَدِّبًا كَأَنَّهُ فِي الصَّلَاةِ،"]]},{"id":"bi40_3","label":"آدَابُ الْمُتَعَلِّمِ · ٣","segs":[["matn","وَلَا يُكْثِرَ عَلَيْهِ السُّؤَالَ عِنْدَ مَلَلِهِ، وَإِذَا قَامَ قَامَ لَهُ، وَلَا يَتْبَعَهُ بِكَلَامِهِ وَسُؤَالِهِ، وَلَا يَسْأَلَهُ فِي طَرِيقِهِ إِلَى أَنْ يَبْلُغَ إِلَى مَنْزِلِهِ، وَلَا يُسِيءَ الظَّنَّ بِهِ فِي أَفْعَالٍ ظَاهِرُهَا مُنْكَرَةٌ عِنْدَهُ،"]]},{"id":"bi40_4","label":"آدَابُ الْمُتَعَلِّمِ · ٤","segs":[["matn","فَهُوَ أَعْلَمُ بِأَسْرَارِهِ، وَلْيَذْكُرْ عِنْدَ ذَلِكَ قَوْلَ مُوسَى لِلْخَضِرِ - عَلَيْهِمَا السَّلَامُ: ﴿أَخَرَقْتَهَا لِتُغْرِقَ أَهْلَهَا لَقَدْ جِئْتَ شَيْئًا إِمْرًا﴾، وَكَوْنَهُ مُخْطِئًا فِي إِنْكَارِهِ اعْتِمَادًا عَلَى الظَّاهِرِ."]]}],"group":"الْقِسْمُ الثَّالِثُ الْقَوْلُ فِي آدَابِ الصُّحْبَةِ"},{"id":"bi41","title":"آدَابُ الْوَلَدِ مَعَ الْوَالِدَيْنِ","units":[{"id":"bi41_1","label":"آدَابُ الْوَلَدِ مَعَ الْوَالِدَيْنِ · ١","segs":[["matn","وَإِنْ كَانَ لَكَ وَالِدَانِ، فَآدَابُ الْوَلَدِ مَعَ الْوَالِدَيْنِ: أَنْ يَسْمَعَ كَلَامَهُمَا، وَيَقُومَ لِقِيَامِهِمَا؛"]]},{"id":"bi41_2","label":"آدَابُ الْوَلَدِ مَعَ الْوَالِدَيْنِ · ٢","segs":[["matn","وَيَمْتَثِلَ لِأَمْرِهِمَا، وَلَا يَمْشِيَ أَمَامَهُمَا، وَلَا يَرْفَعَ صَوْتَهُ فَوْقَ أَصْوَاتِهِمَا، وَيُلَبِّيَ دَعْوَتَهُمَا، وَيَحْرِصَ عَلَى مَرْضَاتِهِمَا، وَيَخْفِضَ لَهُمَا جَنَاحَ الذُّلِّ، وَلَا يَمُنَّ عَلَيْهِمَا بِالْبِرِّ لَهُمَا وَلَا بِالْقِيَامِ لِأَمْرِهِمَا، وَلَا يَنْظُرَ إِلَيْهِمَا شَزْرًا، وَلَا يُقَطِّبَ وَجْهَهُ فِي وَجْهِهِمَا، وَلَا يُسَافِرَ إِلَّا بِإِذْنِهِمَا."]]}],"group":"الْقِسْمُ الثَّالِثُ الْقَوْلُ فِي آدَابِ الصُّحْبَةِ"},{"id":"bi42","title":"أَصْنَافُ النَّاسِ فِي الْعَلَاقَةِ بِالْمَرْءِ","units":[{"id":"bi42_1","label":"أَصْنَافُ النَّاسِ فِي الْعَلَاقَةِ بِالْمَرْءِ · ١","segs":[["matn","وَاعْلَمْ أَنَّ النَّاسَ بَعْدَ هَؤُلَاءِ فِي حَقِّكَ ثَلَاثَةُ أَصْنَافٍ: إِمَّا أَصْدِقَاءُ، وَإِمَّا مَعَارِفُ، وَإِمَّا مَجَاهِيلُ."]]}],"group":"الْقِسْمُ الثَّالِثُ الْقَوْلُ فِي آدَابِ الصُّحْبَةِ"},{"id":"bi43","title":"آدَابُ الْعَلَاقَةِ بِالْعَوَامِّ الْمَجْهُولِينَ","units":[{"id":"bi43_1","label":"آدَابُ الْعَلَاقَةِ بِالْعَوَامِّ الْمَجْهُولِينَ · ١","segs":[["matn","فَإِنْ بُلِيتَ بِالْعَوَامِّ الْمَجْهُولِينَ، فَآدَابُ مُجَالَسَتِهِمْ: تَرْكُ الْخَوْضِ فِي حَدِيثِهِمْ، وَقِلَّةُ الْإِصْغَاءِ إِلَى أَرَاجِيفِهِمْ، وَالتَّغَافُلُ عَمَّا يَجْرِي مِنْ سُوءِ أَلْفَاظِهِمْ، وَالِاحْتِرَازُ عَنْ كَثْرَةِ لِقَائِهِمْ وَالْحَاجَةِ إِلَيْهِمْ، وَالتَّنْبِيهُ عَلَى مُنْكَرَاتِهِمْ بِاللُّطْفِ وَالنُّصْحِ عِنْدَ رَجَاءِ الْقَبُولِ مِنْهُمْ."]]}],"group":"الْقِسْمُ الثَّالِثُ الْقَوْلُ فِي آدَابِ الصُّحْبَةِ"},{"id":"bi44","title":"آدَابُ الْعَلَاقَةِ بِالْإِخْوَانِ وَالْأَصْدِقَاءِ","units":[{"id":"bi44_1","label":"آدَابُ الْعَلَاقَةِ بِالْإِخْوَانِ وَالْأَصْدِقَاءِ · ١","segs":[["matn","وَأَمَّا الْإِخْوَانُ وَالْأَصْدِقَاءُ فَعَلَيْكَ فِيهِمْ وَظِيفَتَانِ: الْوَظِيفَةُ الْأُولَى"]]}],"group":"الْقِسْمُ الثَّالِثُ الْقَوْلُ فِي آدَابِ الصُّحْبَةِ"},{"id":"bi45","title":"شُرُوطُ الصُّحْبَةِ وَالصَّدَاقَةِ","units":[{"id":"bi45_1","label":"شُرُوطُ الصُّحْبَةِ وَالصَّدَاقَةِ · ١","segs":[["matn","إِحْدَاهُمَا: أَنْ تَطْلُبَ أَوَّلًا شُرُوطَ الصُّحْبَةِ وَالصَّدَاقَةِ، فَلَا تُؤَاخِ إِلَّا مَنْ يَصْلُحُ لِلْأُخُوَّةِ وَالصَّدَاقَةِ، قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: «الْمَرْءُ عَلَى دِينِ خَلِيلِهِ فَلْيَنْظُرْ أَحَدُكُمْ مَنْ يُخَالِلُ»."]]},{"id":"bi45_2","label":"شُرُوطُ الصُّحْبَةِ وَالصَّدَاقَةِ · ٢","segs":[["matn","فَإِذَا طَلَبْتَ رَفِيقًا لِيَكُونَ شَرِيكَكَ فِي التَّعَلُّمِ، وَصَاحِبَكَ فِي أَمْرِ دِينِكَ وَدُنْيَاكَ، فَرَاعِ فِيهِ خَمْسَ خِصَالٍ: الْأُولَى: الْعَقْلُ: فَلَا خَيْرَ فِي صُحْبَةِ الْأَحْمَقِ، فَإِلَى الْوَحْشَةِ وَالْقَطِيعَةِ يَرْجِعُ آخِرُهَا،"]]},{"id":"bi45_3","label":"شُرُوطُ الصُّحْبَةِ وَالصَّدَاقَةِ · ٣","segs":[["matn","وَأَحْسَنُ أَحْوَالِهِ أَنْ يَضُرَّكَ وَهُوَ يُرِيدُ أَنْ يَنْفَعَكَ، وَالْعَدُوُّ الْعَاقِلُ خَيْرٌ مِنَ الصَّدِيقِ الْأَحْمَقِ، قَالَ عَلِيٌّ رَضِيَ اللَّهُ عَنْهُ: فَلَا تَصْحَبْ أَخَا الْجَهْلِ ..."]]},{"id":"bi45_4","label":"شُرُوطُ الصُّحْبَةِ وَالصَّدَاقَةِ · ٤","segs":[["matn","وَإِيَّاكَ وَإِيَّاهُ فَكَمْ مِنْ جَاهِلٍ أَرْدَى ... حَلِيمًا حِينَ آخَاهُ يُقَاسُ الْمَرْءُ بِالْمَرْءِ ..."]]},{"id":"bi45_5","label":"شُرُوطُ الصُّحْبَةِ وَالصَّدَاقَةِ · ٥","segs":[["matn","إِذَا مَا الْمَرْءُ مَاشَاهُ كَحَذْوِ النَّعْلِ بِالنَّعْلِ ... إِذَا مَا النَّعْلُ حَاذَاهُ وَلِلشَّيْءِ مِنَ الشَّيْءِ ..."]]},{"id":"bi45_6","label":"شُرُوطُ الصُّحْبَةِ وَالصَّدَاقَةِ · ٦","segs":[["matn","مَقَايِيسُ وَأَشْبَاهُ وَلِلْقَلْبِ عَلَى الْقَلْبِ ... دَلِيلٌ حِينَ يَلْقَاهُ الثَّانِيَةُ: حُسْنُ الْخُلُقِ: فَلَا تَصْحَبْ مَنْ سَاءَ خُلُقُهُ، وَهُوَ الَّذِي لَا يَمْلِكُ نَفْسَهُ عِنْدَ الْغَضَبِ وَالشَّهْوَةِ."]]},{"id":"bi45_7","label":"شُرُوطُ الصُّحْبَةِ وَالصَّدَاقَةِ · ٧","segs":[["matn","وَقَدْ جَمَعَهُ عَلْقَمَةُ الْعُطَارِدِيُّ رَحِمَهُ اللَّهُ تَعَالَى فِي وَصِيَّتِهِ لِابْنِهِ لَمَّا حَضَرَتْهُ الْوَفَاةُ، قَالَ: يَا بُنَيَّ إِذَا أَرَدْتَ صُحْبَةَ إِنْسَانٍ فَاصْحَبْ مَنْ إِذَا خَدَمْتَهُ صَانَكَ،"]]},{"id":"bi45_8","label":"شُرُوطُ الصُّحْبَةِ وَالصَّدَاقَةِ · ٨","segs":[["matn","وَإِنْ صَحِبْتَهُ زَانَكَ، وَإِنْ قَعَدَتْ بِكَ مُؤْنَةٌ مَانَكَ، اصْحَبْ مَنْ إِذَا مَدَدْتَ يَدَكَ بِخَيْرٍ مَدَّهَا، وَإِنْ رَأَى مِنْكَ حَسَنَةً عَدَّهَا، وَإِنْ رَأَى مِنْكَ سَيِّئَةً سَدَّهَا."]]},{"id":"bi45_9","label":"شُرُوطُ الصُّحْبَةِ وَالصَّدَاقَةِ · ٩","segs":[["matn","اصْحَبْ مَنْ إِذَا قُلْتَ صَدَّقَ قَوْلَكَ، وَإِنْ حَاوَلْتَ أَمْرًا أَعَانَكَ وَنَصَرَكَ، وَإِنْ تَنَازَعْتُمَا فِي شَيْءٍ آثَرَكَ."]]},{"id":"bi45_10","label":"شُرُوطُ الصُّحْبَةِ وَالصَّدَاقَةِ · ١٠","segs":[["matn","وَقَالَ عَلِيٌّ رَضِيَ اللَّهُ عَنْهُ رَجَزًا: إِنَّ أَخَاكَ الْحَقَّ مَنْ كَانَ مَعَكْ ..."]]},{"id":"bi45_11","label":"شُرُوطُ الصُّحْبَةِ وَالصَّدَاقَةِ · ١١","segs":[["matn","وَمَنْ يَضُرُّ نَفْسَهُ لِيَنْفَعَكْ وَمَنْ إِذَا رَيْبُ الزَّمَانِ صَدَعَكْ ..."]]},{"id":"bi45_12","label":"شُرُوطُ الصُّحْبَةِ وَالصَّدَاقَةِ · ١٢","segs":[["matn","شَتَّتَ فِيكَ شَمْلَهُ لِيَجْمَعَكْ الثَّالِثَةُ: الصَّلَاحُ: فَلَا تَصْحَبْ فَاسِقًا مُصِرًّا عَلَى مَعْصِيَةٍ كَبِيرَةٍ، لِأَنَّ مَنْ يَخَافُ اللَّهَ لَا يُصِرُّ عَلَى كَبِيرَةٍ، وَمَنْ لَا يَخَافُ اللَّهَ لَا تُؤْمَنُ غَوَائِلُهُ،"]]},{"id":"bi45_13","label":"شُرُوطُ الصُّحْبَةِ وَالصَّدَاقَةِ · ١٣","segs":[["matn","بَلْ يَتَغَيَّرُ بِتَغَيُّرِ الْأَحْوَالِ وَالْأَعْرَاضِ، قَالَ اللَّهُ تَعَالَى لِنَبِيِّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: ﴿وَلَا تُطِعْ مَنْ أَغْفَلْنَا قَلْبَهُ عَن ذِكْرِنَا وَاتَّبَعَ هَوَاهُ وَكَانَ أَمْرُهُ فُرُطًا﴾."]]},{"id":"bi45_14","label":"شُرُوطُ الصُّحْبَةِ وَالصَّدَاقَةِ · ١٤","segs":[["matn","فَاحْذَرْ صُحْبَةَ الْفَاسِقِ؛ فَإِنَّ مُشَاهَدَةَ الْفِسْقِ وَالْمَعْصِيَةِ عَلَى الدَّوَامِ تُزِيلُ عَنْ قَلْبِكَ كَرَاهِيَةَ الْمَعْصِيَةِ، وَتُهَوِّنُ عَلَيْكَ أَمْرَهَا، وَلِذَلِكَ هَانَ عَلَى الْقُلُوبِ مَعْصِيَةُ الْغِيبَةِ لَا لِفَهْمٍ لَهَا، وَلَوْ رَأَوْا خَاتَمًا مِنْ ذَهَبٍ أَوْ مَلْبُوسًا مِنْ حَرِيرٍ عَلَى فَقِيهٍ لَاشْتَدَّ إِنْكَارُهُمْ عَلَيْهِ، وَالْغِيبَةُ أَشَدُّ مِنْ ذَلِكَ."]]},{"id":"bi45_15","label":"شُرُوطُ الصُّحْبَةِ وَالصَّدَاقَةِ · ١٥","segs":[["matn","الرَّابِعَةُ: أَنْ لَا يَكُونَ حَرِيصًا عَلَى الدُّنْيَا: فَصُحْبَةُ الْحَرِيصِ عَلَى الدُّنْيَا سُمٌّ قَاتِلٌ؛"]]},{"id":"bi45_16","label":"شُرُوطُ الصُّحْبَةِ وَالصَّدَاقَةِ · ١٦","segs":[["matn","لِأَنَّ الطِّبَاعَ مَجْبُولَةٌ عَلَى التَّشَبُّهِ وَالِاقْتِدَاءِ، بَلِ الطَّبْعُ يَسْرِقُ مِنَ الطَّبْعِ مِنْ حَيْثُ لَا يَدْرِي فَمُجَالَسَةُ الْحَرِيصِ تَزِيدُ فِي حِرْصِكَ، وَمُجَالَسَةُ الزَّاهِدِ تَزِيدُ فِي زُهْدِكَ."]]},{"id":"bi45_17","label":"شُرُوطُ الصُّحْبَةِ وَالصَّدَاقَةِ · ١٧","segs":[["matn","الْخَامِسَةُ: الصِّدْقُ: فَلَا تَصْحَبْ كَذَّابًا، فَإِنَّكَ مِنْهُ عَلَى غُرُورٍ، فَإِنَّهُ مِثْلُ السَّرَابِ، يُقَرِّبُ مِنْكَ الْبَعِيدَ، وَيُبَعِّدُ مِنْكَ الْقَرِيبَ."]]},{"id":"bi45_18","label":"شُرُوطُ الصُّحْبَةِ وَالصَّدَاقَةِ · ١٨","segs":[["matn","وَلَعَلَّكَ تَعْدَمُ اجْتِمَاعَ هَذِهِ الْخِصَالِ فِي سُكَّانِ الْمَدَارِسِ وَالْمَسَاجِدِ، فَعَلَيْكَ بِأَحَدِ أَمْرَيْنِ: إِمَّا الْعُزْلَةُ وَالِانْفِرَادُ؛"]]},{"id":"bi45_19","label":"شُرُوطُ الصُّحْبَةِ وَالصَّدَاقَةِ · ١٩","segs":[["matn","فَفِيهَا سَلَامَتُكَ، وَإِمَّا أَنْ تَكُونَ مُخَالَطَتُكَ مَعَ شُرَكَائِكَ بِقَدْرِ خِصَالِهِمْ، بِأَنْ تَعْلَمَ أَنَّ الْإِخْوَةَ ثَلَاثَةٌ: أَخٌ لِآخِرَتِكَ فَلَا تُرَاعِ فِيهِ إِلَّا الدِّينَ، وَأَخٌ لِدُنْيَاكَ فَلَا تُرَاعِ فِيهِ إِلَّا الْخُلُقَ الْحَسَنَ، وَأَخٌ لِتَأْنَسَ بِهِ فَلَا تُرَاعِ فِيهِ إِلَّا السَّلَامَةَ مِنْ شَرِّهِ وَفِتْنَتِهِ وَخُبْثِهِ."]]},{"id":"bi45_20","label":"شُرُوطُ الصُّحْبَةِ وَالصَّدَاقَةِ · ٢٠","segs":[["matn","وَالنَّاسُ ثَلَاثَةٌ: أَحَدُهُمْ مَثَلُهُ مَثَلُ الْغِذَاءِ لَا يُسْتَغْنَى عَنْهُ، وَالْآخَرُ مَثَلُهُ مَثَلُ الدَّوَاءِ يُحْتَاجُ إِلَيْهِ فِي وَقْتٍ دُونَ وَقْتٍ، وَالثَّالِثُ مَثَلُهُ مَثَلُ الدَّاءِ لَا يُحْتَاجُ إِلَيْهِ قَطُّ، وَلَكِنَّ الْعَبْدَ قَدْ يُبْتَلَى بِهِ، وَهُوَ الَّذِي لَا أُنْسَ فِيهِ وَلَا نَفْعَ؛"]]},{"id":"bi45_21","label":"شُرُوطُ الصُّحْبَةِ وَالصَّدَاقَةِ · ٢١","segs":[["matn","فَتَجِبُ مُدَارَاتُهُ إِلَى الْخَلَاصِ مِنْهُ، وَفِي مُشَاهَدَتِهِ فَائِدَةٌ عَظِيمَةٌ إِنْ وُفِّقْتَ لَهَا، وَهُوَ أَنْ تُشَاهِدَ مِنْ خَبَائِثِ أَحْوَالِهِ وَأَفْعَالِهِ مَا تَسْتَقْبِحُهُ فَتَجْتَنِبَهُ؛"]]},{"id":"bi45_22","label":"شُرُوطُ الصُّحْبَةِ وَالصَّدَاقَةِ · ٢٢","segs":[["matn","فَالسَّعِيدُ مَنْ وُعِظَ بِغَيْرِهِ، وَالْمُؤْمِنُ مِرْآةُ الْمُؤْمِنِ، وَقِيلَ لِعِيسَى عَلَيْهِ السَّلَامُ: مَنْ أَدَّبَكَ؟"]]},{"id":"bi45_23","label":"شُرُوطُ الصُّحْبَةِ وَالصَّدَاقَةِ · ٢٣","segs":[["matn","فَقَالَ: مَا أَدَّبَنِي أَحَدٌ، وَلَكِنْ رَأَيْتُ جَهْلَ الْجَاهِلِ فَاجْتَنَبْتُهُ."]]},{"id":"bi45_24","label":"شُرُوطُ الصُّحْبَةِ وَالصَّدَاقَةِ · ٢٤","segs":[["matn","وَلَقَدْ صَدَقَ - عَلَى نَبِيِّنَا وَعَلَيْهِ الصَّلَاةُ وَالسَّلَامُ - فَلَوِ اجْتَنَبَ النَّاسُ مَا يَكْرَهُونَهُ مِنْ غَيْرِهِمْ لَكَمُلَتْ آدَابُهُمْ وَاسْتَغْنَوْا عَنِ الْمُؤَدِّبِينَ."]]}],"group":"الْقِسْمُ الثَّالِثُ الْقَوْلُ فِي آدَابِ الصُّحْبَةِ"},{"id":"bi46","title":"الْوَظِيفَةُ الثَّانِيَةُ: مُرَاعَاةُ حُقُوقِ الصُّحْبَةِ","units":[{"id":"bi46_1","label":"الْوَظِيفَةُ الثَّانِيَةُ: مُرَاعَاةُ حُقُوقِ الصُّحْبَةِ · ١","segs":[["matn","فَمَهْمَا انْعَقَدَتِ الشَّرِكَةُ، وَانْتَظَمَتْ بَيْنَكَ وَبَيْنَ شَرِيكِكَ الصُّحْبَةُ، فَعَلَيْكَ حُقُوقٌ يُوجِبُهَا عَقْدُ الصُّحْبَةِ، وَفِي الْقِيَامِ بِهَا آدَابٌ، وَقَدْ قَالَ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: «مَثَلُ الْأَخَوَيْنِ مَثَلُ الْيَدَيْنِ تَغْسِلُ إِحْدَاهُمَا الْأُخْرَى»، وَدَخَلَ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَجَمَةً، فَاجْتَنَى مِنْهَا سِوَاكَيْنِ، أَحَدُهُمَا مُعْوَجٌّ، وَالْآخَرُ مُسْتَقِيمٌ،"]]},{"id":"bi46_2","label":"الْوَظِيفَةُ الثَّانِيَةُ: مُرَاعَاةُ حُقُوقِ الصُّحْبَةِ · ٢","segs":[["matn","وَكَانَ مَعَهُ بَعْضُ أَصْحَابِهِ، فَأَعْطَاهُ الْمُسْتَقِيمَ، وَأَمْسَكَ لِنَفْسِهِ الْمُعْوَجَّ، فَقَالَ: يَا رَسُولَ اللَّهِ أَنْتَ أَحَقُّ مِنِّي بِالْمُسْتَقِيمِ، فَقَالَ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: «مَا مِنْ صَاحِبٍ يَصْحَبُ صَاحِبًا وَلَوْ سَاعَةً مِنْ نَهَارٍ إِلَّا وَسُئِلَ عَنْ صُحْبَتِهِ، هَلْ أَقَامَ فِيهَا حَقَّ اللَّهِ تَعَالَى أَوْ أَضَاعَهُ»."]]},{"id":"bi46_3","label":"الْوَظِيفَةُ الثَّانِيَةُ: مُرَاعَاةُ حُقُوقِ الصُّحْبَةِ · ٣","segs":[["matn","وَقَالَ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: «مَا اصْطَحَبَ اثْنَانِ قَطُّ إِلَّا وَكَانَ أَحَبُّهُمَا إِلَى اللَّهِ تَعَالَى أَرْفَقَهُمَا بِصَاحِبِهِ»."]]},{"id":"bi46_4","label":"الْوَظِيفَةُ الثَّانِيَةُ: مُرَاعَاةُ حُقُوقِ الصُّحْبَةِ · ٤","segs":[["matn","وَآدَابُ الصُّحْبَةِ: الْإِيثَارُ بِالْمَالِ، فَإِنْ لَمْ يَكُنْ هَذَا فَبَذْلُ الْفَضْلِ مِنَ الْمَالِ عِنْدَ الْحَاجَةِ، وَالْإِعَانَةُ بِالنَّفْسِ فِي الْحَاجَاتِ، عَلَى سَبِيلِ الْمُبَادَرَةِ مِنْ غَيْرِ إِحْوَاجٍ إِلَى الْتِمَاسٍ،"]]},{"id":"bi46_5","label":"الْوَظِيفَةُ الثَّانِيَةُ: مُرَاعَاةُ حُقُوقِ الصُّحْبَةِ · ٥","segs":[["matn","وَكِتْمَانُ السِّرِّ، وَسَتْرُ الْعُيُوبِ، وَالسُّكُوتُ عَلَى تَبْلِيغِ مَا يَسُوؤُهُ مِنْ مَذَمَّةِ النَّاسِ إِيَّاهُ، وَإِبْلَاغُ مَا يَسُرُّهُ مِنْ ثَنَاءِ النَّاسِ عَلَيْهِ، وَحُسْنُ الْإِصْغَاءِ عِنْدَ الْحَدِيثِ،"]]},{"id":"bi46_6","label":"الْوَظِيفَةُ الثَّانِيَةُ: مُرَاعَاةُ حُقُوقِ الصُّحْبَةِ · ٦","segs":[["matn","وَتَرْكُ الْمُمَارَاةِ فِيهِ، وَأَنْ يَدْعُوَهُ بِأَحَبِّ أَسْمَائِهِ إِلَيْهِ، وَأَنْ يُثْنِيَ عَلَيْهِ بِمَا يَعْرِفُ مِنْ مَحَاسِنِهِ، وَأَنْ يَشْكُرَهُ عَلَى صَنِيعِهِ فِي وَجْهِهِ، وَأَنْ يَذُبَّ عَنْهُ فِي غَيْبَتِهِ إِذَا تُعُرِّضَ لِعِرْضِهِ كَمَا يَذُبُّ عَنْ نَفْسِهِ، وَأَنْ يَنْصَحَهُ بِاللُّطْفِ وَالتَّعْرِيضِ إِذَا احْتَاجَ إِلَيْهِ، وَأَنْ يَعْفُوَ عَنْ زَلَّتِهِ وَهَفْوَتِهِ،"]]},{"id":"bi46_7","label":"الْوَظِيفَةُ الثَّانِيَةُ: مُرَاعَاةُ حُقُوقِ الصُّحْبَةِ · ٧","segs":[["matn","وَلَا يَعْتِبَ عَلَيْهِ، وَأَنْ يَدْعُوَ لَهُ فِي خَلْوَتِهِ فِي حَيَاتِهِ وَبَعْدَ مَمَاتِهِ، وَأَنْ يُحْسِنَ الْوَفَاءَ مَعَ أَهْلِهِ وَأَقَارِبِهِ بَعْدَ مَوْتِهِ، وَأَنْ يُؤْثِرَ التَّخْفِيفَ عَنْهُ،"]]},{"id":"bi46_8","label":"الْوَظِيفَةُ الثَّانِيَةُ: مُرَاعَاةُ حُقُوقِ الصُّحْبَةِ · ٨","segs":[["matn","فَلَا يُكَلِّفَهُ شَيْئًا مِنْ حَاجَاتِهِ وَيُرَوِّحَ قَلْبَهُ مِنْ مُهِمَّاتِهِ، وَأَنْ يُظْهِرَ الْفَرَحَ بِجَمِيعِ مَا يَرْتَاحُ لَهُ مِنْ مَسَارِّهِ، وَالْحُزْنَ عَلَى مَا يَنَالُهُ مِنْ مَكَارِهِهِ،"]]},{"id":"bi46_9","label":"الْوَظِيفَةُ الثَّانِيَةُ: مُرَاعَاةُ حُقُوقِ الصُّحْبَةِ · ٩","segs":[["matn","وَأَنْ يُضْمِرَ فِي قَلْبِهِ مِثْلَ مَا يُظْهِرُهُ، فَيَكُونَ صَادِقًا فِي وُدِّهِ سِرًّا وَعَلَانِيَةً، وَأَنْ يَبْدَأَهُ بِالسَّلَامِ عِنْدَ إِقْبَالِهِ، وَأَنْ يُوَسِّعَ لَهُ فِي الْمَجْلِسِ وَيَخْرُجَ لَهُ مِنْ مَكَانِهِ، وَأَنْ يُشَيِّعَهُ عِنْدَ قِيَامِهِ، وَأَنْ يَصْمُتَ عِنْدَ كَلَامِهِ حَتَّى يَفْرُغَ مِنْ كَلَامِهِ، وَيَتْرُكَ الْمُدَاخَلَةَ فِي كَلَامِهِ."]]},{"id":"bi46_10","label":"الْوَظِيفَةُ الثَّانِيَةُ: مُرَاعَاةُ حُقُوقِ الصُّحْبَةِ · ١٠","segs":[["matn","وَعَلَى الْجُمْلَةِ، فَيُعَامِلُهُ بِمَا يُحِبُّ أَنْ يُعَامَلَ بِهِ، فَمَنْ لَا يُحِبُّ لِأَخِيهِ مَا يُحِبُّ لِنَفْسِهِ فَأُخُوَّتُهُ نِفَاقٌ، وَهِيَ عَلَيْهِ وَبَالٌ فِي الدُّنْيَا وَالْآخِرَةِ."]]},{"id":"bi46_11","label":"الْوَظِيفَةُ الثَّانِيَةُ: مُرَاعَاةُ حُقُوقِ الصُّحْبَةِ · ١١","segs":[["matn","فَهَذَا أَدَبُكَ فِي حَقِّ الْعَوَامِّ الْمَجْهُولِينَ، وَفِي حَقِّ الْأَصْدِقَاءِ الْمُؤَاخِينَ."]]}],"group":"الْقِسْمُ الثَّالِثُ الْقَوْلُ فِي آدَابِ الصُّحْبَةِ"},{"id":"bi47","title":"آدَابُ الْعَلَاقَةِ بِالْمَعَارِفِ","units":[{"id":"bi47_1","label":"آدَابُ الْعَلَاقَةِ بِالْمَعَارِفِ · ١","segs":[["matn","وَأَمَّا الْقِسْمُ الثَّالِثُ، وَهُمُ الْمَعَارِفُ: فَاحْذَرْ مِنْهُمْ؛ فَإِنَّكَ لَا تَرَى الشَّرَّ إِلَّا مِمَّنْ تَعْرِفُهُ، أَمَّا الصَّدِيقُ فَيُعِينُكَ، وَأَمَّا الْمَجْهُولُ فَلَا يَتَعَرَّضُ لَكَ، وَإِنَّمَا الشَّرُّ كُلُّهُ مِنَ الْمَعَارِفِ الَّذِينَ يُظْهِرُونَ الصَّدَاقَةَ بِأَلْسِنَتِهِمْ."]]},{"id":"bi47_2","label":"آدَابُ الْعَلَاقَةِ بِالْمَعَارِفِ · ٢","segs":[["matn","فَأَقْلِلْ مِنَ الْمَعَارِفِ مَا قَدَرْتَ، فَإِذَا بُلِيتَ بِهِمْ فِي مَدْرَسَةٍ أَوْ مَسْجِدٍ أَوْ جَامِعٍ أَوْ سُوقٍ أَوْ بَلَدٍ، فَيَجِبُ أَنْ لَا تَسْتَصْغِرَ مِنْهُمْ أَحَدًا؛"]]},{"id":"bi47_3","label":"آدَابُ الْعَلَاقَةِ بِالْمَعَارِفِ · ٣","segs":[["matn","فَإِنَّكَ لَا تَدْرِي لَعَلَّهُ خَيْرٌ مِنْكَ، وَلَا تَنْظُرْ إِلَيْهِمْ بِعَيْنِ التَّعْظِيمِ لَهُمْ فِي حَالِ دُنْيَاهُمْ فَتَهْلِكَ، لِأَنَّ الدُّنْيَا صَغِيرَةٌ عِنْدَ اللَّهِ تَعَالَى، صَغِيرٌ مَا فِيهَا."]]},{"id":"bi47_4","label":"آدَابُ الْعَلَاقَةِ بِالْمَعَارِفِ · ٤","segs":[["matn","وَمَهْمَا عَظُمَ أَهْلُ الدُّنْيَا فِي قَلْبِكَ فَقَدْ سَقَطْتَ مِنْ عَيْنِ اللَّهِ تَعَالَى، وَإِيَّاكَ أَنْ تَبْذُلَ لَهُمْ دِينَكَ لِتَنَالَ بِهِ مِنْ دُنْيَاهُمْ؛"]]},{"id":"bi47_5","label":"آدَابُ الْعَلَاقَةِ بِالْمَعَارِفِ · ٥","segs":[["matn","فَلَا يَفْعَلُ ذَلِكَ أَحَدٌ إِلَّا صَغُرَ فِي أَعْيُنِهِمْ ثُمَّ حُرِمَ مَا عِنْدَهُمْ."]]},{"id":"bi47_6","label":"آدَابُ الْعَلَاقَةِ بِالْمَعَارِفِ · ٦","segs":[["matn","وَإِنْ عَادَوْكَ فَلَا تُقَابِلْهُمْ بِالْعَدَاوَةِ؛ فَإِنَّكَ لَا تُطِيقُ الصَّبْرَ عَلَى مُكَافَأَتِهِمْ، فَيَذْهَبُ دِينُكَ فِي عَدَاوَتِهِمْ، وَيَطُولُ عَنَاؤُكَ مَعَهُمْ، وَلَا تَسْكُنْ إِلَيْهِمْ فِي حَالِ إِكْرَامِهِمْ إِيَّاكَ وَثَنَائِهِمْ عَلَيْكَ فِي وَجْهِكَ وَإِظْهَارِهِمُ الْمَوَدَّةَ لَكَ؛"]]},{"id":"bi47_7","label":"آدَابُ الْعَلَاقَةِ بِالْمَعَارِفِ · ٧","segs":[["matn","فَإِنَّكَ إِنْ طَلَبْتَ حَقِيقَةَ ذَلِكَ لَمْ تَجِدْ فِي الْمِائَةِ وَاحِدًا، وَلَا تَطْمَعْ أَنْ يَكُونُوا لَكَ فِي السِّرِّ وَالْعَلَنِ وَاحِدٌ، وَلَا تَتَعَجَّبْ إِنْ ثَلَبُوكَ فِي غَيْبَتِكَ وَلَا تَغْضَبْ مِنْهُ؛"]]},{"id":"bi47_8","label":"آدَابُ الْعَلَاقَةِ بِالْمَعَارِفِ · ٨","segs":[["matn","فَإِنَّكَ إِنْ أَنْصَفْتَ وَجَدْتَ مِنْ نَفْسِكَ مِثْلَ ذَلِكَ، حَتَّى فِي أَصْدِقَائِكَ وَأَقَارِبِكَ، بَلْ فِي أُسْتَاذِكَ وَوَالِدَيْكَ؛"]]},{"id":"bi47_9","label":"آدَابُ الْعَلَاقَةِ بِالْمَعَارِفِ · ٩","segs":[["matn","فَإِنَّكَ تَذْكُرُهُمْ فِي الْغَيْبَةِ بِمَا لَا تُشَافِهُهُمْ بِهِ، فَاقْطَعْ طَمَعَكَ عَنْ مَالِهِمْ وَجَاهِهِمْ وَمَعُونَتِهِمْ؛"]]},{"id":"bi47_10","label":"آدَابُ الْعَلَاقَةِ بِالْمَعَارِفِ · ١٠","segs":[["matn","فَإِنَّ الطَّامِعَ فِي الْأَكْثَرِ خَائِبٌ فِي الْمَآلِ، وَهُوَ ذَلِيلٌ لَا مَحَالَةَ فِي الْحَالِ."]]},{"id":"bi47_11","label":"آدَابُ الْعَلَاقَةِ بِالْمَعَارِفِ · ١١","segs":[["matn","وَإِذَا سَأَلْتَ وَاحِدًا حَاجَةً فَقَضَاهَا، فَاشْكُرِ اللَّهَ تَعَالَى وَاشْكُرْهُ، وَإِنْ قَصَّرَ فَلَا تُعَاتِبْهُ وَلَا تَشْكُهُ فَيَصِيرَ عَدَاوَةً لَهُ، وَكُنْ كَالْمُؤْمِنِ يَطْلُبُ الْمَعَاذِيرَ، وَلَا تَكُنْ كَالْمُنَافِقِ يَطْلُبُ الْعُيُوبَ، وَقُلْ لَعَلَّهُ قَصَّرَ لِعُذْرٍ لَهُ لَمْ أَطَّلِعْ عَلَيْهِ."]]},{"id":"bi47_12","label":"آدَابُ الْعَلَاقَةِ بِالْمَعَارِفِ · ١٢","segs":[["matn","وَلَا تَعِظَنَّ أَحَدًا مِنْهُمْ مَا لَمْ تَتَوَسَّمْ فِيهِ أَوَّلًا مَخَايِلَ الْقَبُولِ، وَإِلَّا لَمْ يَسْتَمِعْ مِنْكَ وَصَارَ خَصْمًا عَلَيْكَ، فَإِذَا أَخْطَؤُوا فِي مَسْأَلَةٍ، وَكَانُوا يَأْنَفُونَ مِنَ التَّعَلُّمِ مِنْكَ، فَلَا تُعَلِّمْهُمْ؛"]]},{"id":"bi47_13","label":"آدَابُ الْعَلَاقَةِ بِالْمَعَارِفِ · ١٣","segs":[["matn","فَإِنَّهُمْ يَسْتَفِيدُونَ مِنْكَ عِلْمًا وَيُصْبِحُونَ لَكَ أَعْدَاءً، إِلَّا إِذَا تَعَلَّقَ ذَلِكَ بِمَعْصِيَةٍ يُقَارِفُونَهَا عَنْ جَهْلٍ مِنْهُمْ، فَاذْكُرِ الْحَقَّ بِلُطْفٍ مِنْ غَيْرِ عُنْفٍ."]]},{"id":"bi47_14","label":"آدَابُ الْعَلَاقَةِ بِالْمَعَارِفِ · ١٤","segs":[["matn","وَإِذَا رَأَيْتَ مِنْهُمْ كَرَامَةً وَخَيْرًا، فَاشْكُرِ اللَّهَ الَّذِي حَبَّبَكَ إِلَيْهِمْ."]]},{"id":"bi47_15","label":"آدَابُ الْعَلَاقَةِ بِالْمَعَارِفِ · ١٥","segs":[["matn","وَإِذَا رَأَيْتَ مِنْهُمْ شَرًّا، فَكِلْهُمْ إِلَى اللَّهِ تَعَالَى، وَاسْتَعِذْ بِاللَّهِ مِنْ شَرِّهِمْ، وَلَا تُعَاتِبْهُمْ، وَلَا تَقُلْ لَهُمْ: لِمَ لَمْ تَعْرِفُوا حَقِّي؛"]]},{"id":"bi47_16","label":"آدَابُ الْعَلَاقَةِ بِالْمَعَارِفِ · ١٦","segs":[["matn","وَأَنَا فُلَانُ بْنُ فُلَانٍ، وَأَنَا الْفَاضِلُ فِي الْعُلُومِ؟"]]},{"id":"bi47_17","label":"آدَابُ الْعَلَاقَةِ بِالْمَعَارِفِ · ١٧","segs":[["matn","فَإِنَّ ذَلِكَ مِنْ كَلَامِ الْحَمْقَى، وَأَشَدُّ النَّاسِ حَمَاقَةً مَنْ يُزَكِّي نَفْسَهُ وَيُثْنِي عَلَيْهَا."]]},{"id":"bi47_18","label":"آدَابُ الْعَلَاقَةِ بِالْمَعَارِفِ · ١٨","segs":[["matn","وَاعْلَمْ أَنَّ اللَّهَ تَعَالَى لَا يُسَلِّطُهُمْ عَلَيْكَ إِلَّا بِذَنْبٍ سَبَقَ مِنْكَ، فَاسْتَغْفِرِ اللَّهَ مِنْ ذَنْبِكَ، وَاعْلَمْ أَنَّ ذَلِكَ عُقُوبَةٌ مِنَ اللَّهِ تَعَالَى."]]},{"id":"bi47_19","label":"آدَابُ الْعَلَاقَةِ بِالْمَعَارِفِ · ١٩","segs":[["matn","وَكُنْ فِيمَا بَيْنَهُمْ سَمِيعًا لِحَقِّهِمْ، أَصَمَّ عَنْ بَاطِلِهِمْ، نَطُوقًا بِمَحَاسِنِهِمْ، صَمُوتًا عَنْ مَسَاوِيهِمْ، وَاحْذَرْ مُخَالَطَةَ مُتَفَقِّهَةِ الزَّمَانِ، لَا سِيَّمَا الْمُشْتَغِلِينَ بِالْخِلَافِ وَالْجِدَالِ."]]},{"id":"bi47_20","label":"آدَابُ الْعَلَاقَةِ بِالْمَعَارِفِ · ٢٠","segs":[["matn","وَاحْذَرْ مِنْهُمْ؛ فَإِنَّهُمْ يَتَرَبَّصُونَ بِكَ - لِحَسَدِهِمْ - رَيْبَ الْمَنُونِ، وَيَقْطَعُونَ عَلَيْكَ بِالظُّنُونِ، وَيَتَغَامَزُونَ وَرَاءَكَ بِالْعُيُونِ، وَيُحْصُونَ عَلَيْكَ عَثَرَاتِكَ فِي عِشْرَتِهِمْ، حَتَّى يَجْبَهُوكَ بِهَا فِي حَالِ غَيْظِهِمْ وَمُنَاظَرَتِهِمْ، لَا يُقِيلُونَ لَكَ عَثْرَةً، وَلَا يَغْفِرُونَ لَكَ زَلَّةً،"]]},{"id":"bi47_21","label":"آدَابُ الْعَلَاقَةِ بِالْمَعَارِفِ · ٢١","segs":[["matn","وَلَا يَسْتُرُونَ لَكَ عَوْرَةً، يُحَاسِبُونَكَ عَلَى النَّقِيرِ وَالْقِطْمِيرِ، وَيَحْسُدُونَكَ عَلَى الْقَلِيلِ وَالْكَثِيرِ، وَيُحَرِّضُونَ عَلَيْكَ الْإِخْوَانَ بِالنَّمِيمَةِ وَالْبَلَاغَاتِ وَالْبُهْتَانِ، إِنْ رَضُوا فَظَاهِرُهُمُ الْمَلَقُ، وَإِنْ سَخِطُوا فَبَاطِنُهُمُ الْحَنَقُ، ظَاهِرُهُمْ ثِيَابٌ وَبَاطِنُهُمْ ذِئَابٌ."]]},{"id":"bi47_22","label":"آدَابُ الْعَلَاقَةِ بِالْمَعَارِفِ · ٢٢","segs":[["matn","هَذَا مَا قَطَعَتْ بِهِ الْمُشَاهَدَةُ عَلَى أَكْثَرِهِمْ، إِلَّا مَنْ عَصَمَهُ اللَّهُ تَعَالَى؛"]]},{"id":"bi47_23","label":"آدَابُ الْعَلَاقَةِ بِالْمَعَارِفِ · ٢٣","segs":[["matn","فَصُحْبَتُهُمْ خُسْرَانٌ، وَمُعَاشَرَتُهُمْ خِذْلَانٌ. هَذَا حُكْمُ مَنْ يُظْهِرُ لَكَ الصَّدَاقَةَ، فَكَيْفَ مَنْ يُجَاهِرُكَ بِالْعَدَاوَةِ؟"]]},{"id":"bi47_24","label":"آدَابُ الْعَلَاقَةِ بِالْمَعَارِفِ · ٢٤","segs":[["matn","قَالَ الْقَاضِي ابْنُ مَعْرُوفٍ رَحِمَهُ اللَّهُ تَعَالَى: فَاحْذَرْ عَدُوَّكَ مَرَّةً ..."]]},{"id":"bi47_25","label":"آدَابُ الْعَلَاقَةِ بِالْمَعَارِفِ · ٢٥","segs":[["matn","وَاحْذَرْ صَدِيقَكَ أَلْفَ مَرَّةْ فَلَرُبَّمَا انْقَلَبَ الصَّدِيقُ ... فَكَانَ أَعْرَفَ بِالْمَضَرَّةْ وَكَذَلِكَ قَالَ أَبُو تَمَّامٍ: عَدُوُّكَ مِنْ صَدِيقِكَ مُسْتَفَادٌ ..."]]},{"id":"bi47_26","label":"آدَابُ الْعَلَاقَةِ بِالْمَعَارِفِ · ٢٦","segs":[["matn","فَلَا تَسْتَكْثِرَنَّ مِنَ الصِّحَابِ فَإِنَّ الدَّاءَ أَكْثَرَ مَا تَرَاهُ ..."]]},{"id":"bi47_27","label":"آدَابُ الْعَلَاقَةِ بِالْمَعَارِفِ · ٢٧","segs":[["matn","يَكُونُ مِنَ الطَّعَامِ أَوِ الشَّرَابِ وَكُنْ كَمَا قَالَ هِلَالُ بْنُ الْعَلَاءِ الرَّقِّيُّ: لَمَّا عَفَوْتُ وَلَمْ أَحْقِدْ عَلَى أَحَدٍ ..."]]},{"id":"bi47_28","label":"آدَابُ الْعَلَاقَةِ بِالْمَعَارِفِ · ٢٨","segs":[["matn","أَرَحْتُ نَفْسِى مِنْ هَمِّ الْعَدَاوَاتِ إِنِّي أُحَيِّى عَدُوِّى عِنْدَ رُؤْيَتِهِ ..."]]},{"id":"bi47_29","label":"آدَابُ الْعَلَاقَةِ بِالْمَعَارِفِ · ٢٩","segs":[["matn","لِأَدْفَعَ الشَّرَّ عَنِّى بِالتَّحِيَّاتِ وَأُظْهِرُ الْبِشْرَ لِلْإِنْسَانِ أُبْغِضُهُ ..."]]},{"id":"bi47_30","label":"آدَابُ الْعَلَاقَةِ بِالْمَعَارِفِ · ٣٠","segs":[["matn","كَأَنْ قَدْ مَلَا قَلْبِى مَرَّاتِ وَلَسْتُ أَسْلَمُ مِمَّنْ لَسْتُ أَعْرِفُهُ ..."]]},{"id":"bi47_31","label":"آدَابُ الْعَلَاقَةِ بِالْمَعَارِفِ · ٣١","segs":[["matn","فَكَيْفَ أَسْلَمُ مِنْ أَهْلِ الْمَوَدَّاتِ النَّاسُ دَاءٌ دَوَاءُ النَّاسِ تَرْكُهُمُ ..."]]},{"id":"bi47_32","label":"آدَابُ الْعَلَاقَةِ بِالْمَعَارِفِ · ٣٢","segs":[["matn","وَفِي الْجَفَاءِ لَهُمْ قَطْعُ الْأُخُوَّاتِ فَسَالِمِ النَّاسَ تَسْلَمْ مِنْ غَوَائِلِهِمْ ..."]]},{"id":"bi47_33","label":"آدَابُ الْعَلَاقَةِ بِالْمَعَارِفِ · ٣٣","segs":[["matn","وَكُنْ حَرِيصًا عَلَى كَسْبِ التَّقِيَّاتِ وَخَالِقِ النَّاسَ وَاصْبِرْ مَا بُلِيتَ بِهِمْ ..."]]},{"id":"bi47_34","label":"آدَابُ الْعَلَاقَةِ بِالْمَعَارِفِ · ٣٤","segs":[["matn","أَصَمَّ أَبْكَمَ أَعْمَى ذَا تَقِيَّاتِ وَكُنْ أَيْضًا كَمَا قَالَ بَعْضُ الْحُكَمَاءِ: الْقَ صَدِيقَكَ وَعَدُوَّكَ بِوَجْهِ الرِّضَا، مِنْ غَيْرِ مَذَلَّةٍ لَهُمَا وَلَا هَيْبَةٍ مِنْهُمَا، وَتَوَقَّرْ مِنْ غَيْرِ كِبْرٍ،"]]},{"id":"bi47_35","label":"آدَابُ الْعَلَاقَةِ بِالْمَعَارِفِ · ٣٥","segs":[["matn","وَتَوَاضَعْ مِنْ غَيْرِ مَذَلَّةٍ، وَكُنْ فِي جَمِيعِ أُمُورِكَ فِي أَوْسَطِهَا، فَكِلَا طَرَفَيْ قَصْدِ الْأُمُورِ ذَمِيمُ، كَمَا قِيلَ: عَلَيْكَ بِأَوْسَاطِ الْأُمُورِ فَإِنَّهَا ..."]]},{"id":"bi47_36","label":"آدَابُ الْعَلَاقَةِ بِالْمَعَارِفِ · ٣٦","segs":[["matn","طَرِيقٌ إِلَى نَهْجِ الصِّرَاطِ قَوِيمُ وَلَا تَكُ فِيهَا مُفْرِطًا أَوْ مُفَرِّطًا ..."]]},{"id":"bi47_37","label":"آدَابُ الْعَلَاقَةِ بِالْمَعَارِفِ · ٣٧","segs":[["matn","فَإِنَّ كِلَا حَالِ الْأُمُورِ ذَمِيمُ وَلَا تَنْظُرْ فِي عِطْفَيْكَ، وَلَا تُكْثِرِ الِالْتِفَاتَ، إِلَى وَرَائِكَ، وَلَا تَقِفْ عَلَى الْجَمَاعَاتِ، وَإِذَا جَلَسْتَ فَلَا تَسْتَوْفِزْ، وَتَحَفَّظْ مِنْ تَشْبِيكِ أَصَابِعِكَ، وَالْعَبَثِ بِلِحْيَتِكَ وَخَاتَمِكَ،"]]},{"id":"bi47_38","label":"آدَابُ الْعَلَاقَةِ بِالْمَعَارِفِ · ٣٨","segs":[["matn","وَتَخْلِيلِ أَسْنَانِكَ، وَإِدْخَالِ إِصْبَعِكَ فِي أَنْفِكَ، وَكَثْرَةِ بُصَاقِكَ وَتَنَخُّمِكَ وَطَرْدِ الذُّبَابِ عَنْ وَجْهِكَ، وَكَثْرَةِ التَّمَطِّي وَالتَّثَاؤُبِ فِي وُجُوهِ النَّاسِ فِي الصَّلَاةِ وَغَيْرِهَا، وَلْيَكُنْ مَجْلِسُكَ هَادِئًا، وَحَدِيثُكَ مَنْظُومًا مُرَتَّبًا،"]]},{"id":"bi47_39","label":"آدَابُ الْعَلَاقَةِ بِالْمَعَارِفِ · ٣٩","segs":[["matn","وَاصْغَ إِلَى الْكَلَامِ الْحَسَنِ مِمَّنْ حَدَّثَكَ مِنْ غَيْرِ إِظْهَارِ تَعَجُّبٍ مُفْرِطٍ، وَلَا تَسْأَلْهُ إِعَادَتَهُ، وَاسْكُتْ عَنِ الْمَضَاحِكِ وَالْحِكَايَاتِ، وَلَا تُحَدِّثْ عَنْ إِعْجَابِكَ بِوَلَدِكَ وَشِعْرِكَ وَكَلَامِكَ وَتَصْنِيفِكَ وَسَائِرِ مَا يَخُصُّكَ، وَلَا تَتَصَنَّعْ تَصَنُّعَ الْمَرْأَةِ فِي التَّزَيُّنِ،"]]},{"id":"bi47_40","label":"آدَابُ الْعَلَاقَةِ بِالْمَعَارِفِ · ٤٠","segs":[["matn","وَلَا تَتَبَذَّلْ تَبَذُّلَ الْعَبْدِ، وَتَوَقَّ كَثْرَةَ الْكُحْلِ وَالْإِسْرَافَ فِي الدُّهْنِ، وَلَا تُلِحَّ فِي الْحَاجَاتِ، وَلَا تُشَجِّعْ أَحَدًا عَلَى الظُّلْمِ، وَلَا تُعْلِمْ أَحَدًا مِنْ أَهْلِكَ وَوَلَدِكَ فَضْلًا عَنْ غَيْرِهِمْ مِقْدَارَ مَالِكَ؛"]]},{"id":"bi47_41","label":"آدَابُ الْعَلَاقَةِ بِالْمَعَارِفِ · ٤١","segs":[["matn","فَإِنَّهُمْ إِنْ رَأَوْهُ قَلِيلًا هُنْتَ عَلَيْهِمْ، إِنْ رَأَوْهُ كَثِيرًا لَمْ تَبْلُغْ قَطُّ رِضَاهُمْ."]]},{"id":"bi47_42","label":"آدَابُ الْعَلَاقَةِ بِالْمَعَارِفِ · ٤٢","segs":[["matn","وَاجْفُهُمْ مِنْ غَيْرِ عُنْفٍ، وَلِنْ لَهُمْ مِنْ غَيْرِ ضَعْفٍ، وَلَا تُهَازِلْ أَمَتَكَ وَلَا عَبْدَكَ، فَيَسْقُطَ وَقَارُكَ مِنْ قُلُوبِهِمْ، وَإِذَا خَاصَمْتَ فَتَوَقَّرْ، وَتَحَفَّظْ مِنْ جَهْلِكَ وَعَجَلَتِكَ،"]]},{"id":"bi47_43","label":"آدَابُ الْعَلَاقَةِ بِالْمَعَارِفِ · ٤٣","segs":[["matn","وَتَفَكَّرْ فِي حُجَّتِكَ، وَلَا تُكْثِرِ الْإِشَارَةَ بِيَدِكَ، وَلَا تُكْثِرِ الِالْتِفَاتَ إِلَى مَنْ وَرَائِكَ وَلَا تَجْثُ عَلَى رُكْبَتَيْكَ، وَإِذَا هَدَأَ غَضَبُكَ فَتَكَلَّمْ."]]},{"id":"bi47_44","label":"آدَابُ الْعَلَاقَةِ بِالْمَعَارِفِ · ٤٤","segs":[["matn","وَإِذَا قَرَّبَكَ السُّلْطَانُ فَكُنْ مِنْهُ عَلَى حَدِّ السِّنَانِ، وَإِيَّاكَ وَصَدِيقَ الْعَافِيَةِ؛"]]},{"id":"bi47_45","label":"آدَابُ الْعَلَاقَةِ بِالْمَعَارِفِ · ٤٥","segs":[["matn","فَإِنَّهُ أَعْدَى الْأَعْدَاءِ، وَلَا تَجْعَلْ مَالَكَ أَكْرَمَ مِنْ عِرْضِكَ."]]},{"id":"bi47_46","label":"آدَابُ الْعَلَاقَةِ بِالْمَعَارِفِ · ٤٦","segs":[["matn","فَهَذَا الْقَدْرُ يَا فَتَى يَكْفِيكَ مِنْ بِدَايَةِ الْهِدَايَةِ، فَجَرِّبْ بِهَا نَفْسَكَ؛"]]},{"id":"bi47_47","label":"آدَابُ الْعَلَاقَةِ بِالْمَعَارِفِ · ٤٧","segs":[["matn","فَإِنَّهَا ثَلَاثَةُ أَقْسَامٍ: قِسْمُ آدَابِ الطَّاعَاتِ، وَقِسْمٌ فِي تَرْكِ الْمَعَاصِي، وَقِسْمٌ فِي مُخَالَطَةِ الْخَلْقِ، وَهِيَ جَامِعَةٌ لِجُمْلَةِ مُعَامَلَةِ الْعَبْدِ مَعَ الْخَالِقِ وَالْخَلْقِ."]]},{"id":"bi47_48","label":"آدَابُ الْعَلَاقَةِ بِالْمَعَارِفِ · ٤٨","segs":[["matn","فَإِنْ رَأَيْتَهَا مُنَاسِبَةً لِنَفْسِكَ، وَرَأَيْتَ قَلْبَكَ مَائِلًا إِلَيْهَا رَاغِبًا فِي الْعَمَلِ بِهَا، فَاعْلَمْ أَنَّكَ عَبْدٌ نَوَّرَ اللَّهُ تَعَالَى بِالْإِيمَانِ قَلْبَكَ، وَشَرَحَ بِهِ صَدْرَكَ، وَتَحَقَّقْ أَنَّ لِهَذِهِ الْبِدَايَةِ نِهَايَةً، وَوَرَاءَهَا أَسْرَارًا وَأَغْوَارًا وَمُكَاشَفَاتٍ، وَقَدْ أَوْدَعْنَاهَا فِي كِتَابِ «إِحْيَاءِ عُلُومِ الدِّينِ»؛"]]},{"id":"bi47_49","label":"آدَابُ الْعَلَاقَةِ بِالْمَعَارِفِ · ٤٩","segs":[["matn","فَاشْتَغِلْ بِتَحْصِيلِهِ. وَإِنْ رَأَيْتَ نَفْسَكَ تَسْتَثْقِلُ الْعَمَلَ بِهَذِهِ الْوَظَائِفِ، وَتُنْكِرُ هَذَا الْفَنَّ مِنَ الْعِلْمِ، وَتَقُولُ لَكَ نَفْسُكَ: أَنَّى يَنْفَعُكَ هَذَا الْعِلْمُ فِي مَحَافِلِ الْعُلَمَاءِ، وَمَتَى يُقَدِّمُكَ هَذَا عَلَى الْأَقْرَانِ وَالنُّظَرَاءِ؟!"]]},{"id":"bi47_50","label":"آدَابُ الْعَلَاقَةِ بِالْمَعَارِفِ · ٥٠","segs":[["matn","وَكَيْفَ يَرْفَعُ مَنْصِبَكَ فِي مَجَالِسِ الْأُمَرَاءِ وَالْوُزَرَاءِ؟ وَكَيْفَ يُوصِلُكَ إِلَى الصِّلَةِ وَالْأَرْزَاقِ وَوِلَايَةِ الْأَوْقَافِ وَالْقَضَاءِ؟"]]},{"id":"bi47_51","label":"آدَابُ الْعَلَاقَةِ بِالْمَعَارِفِ · ٥١","segs":[["matn","فَاعْلَمْ أَنَّ الشَّيْطَانَ قَدْ أَغْوَاكَ وَأَنْسَاكَ مُنْقَلَبَكَ وَمَثْوَاكَ، فَاطْلُبْ لَكَ شَيْطَانًا مِثْلَكَ، لِيُعَلِّمَكَ مَا تَظُنُّ أَنَّهُ يَنْفَعُكَ وَيُوصِلُكَ إِلَى بُغْيَتِكَ."]]},{"id":"bi47_52","label":"آدَابُ الْعَلَاقَةِ بِالْمَعَارِفِ · ٥٢","segs":[["matn","ثُمَّ أَنَّهُ قَطُّ لَا يَصْفُو لَكَ الْمُلْكُ فِي مَحَلَّتِكَ، فَضْلًا عَنْ قَرْيَتِكَ وَبَلْدَتِكَ، ثُمَّ يَفُوتُكَ الْمُلْكُ الْمُقِيمُ وَالنَّعِيمُ الدَّائِمُ فِي جِوَارِ رَبِّ الْعَالَمِينَ."]]},{"id":"bi47_53","label":"آدَابُ الْعَلَاقَةِ بِالْمَعَارِفِ · ٥٣","segs":[["matn","وَالسَّلَامُ عَلَيْكُمْ وَرَحْمَةُ اللَّهِ وَبَرَكَاتُهُ، وَالْحَمْدُ لِلَّهِ أَوَّلًا وَآخِرًا، وَظَاهِرًا وَبَاطِنًا."]]},{"id":"bi47_54","label":"آدَابُ الْعَلَاقَةِ بِالْمَعَارِفِ · ٥٤","segs":[["matn","وَلَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللَّهِ الْعَلِيِّ الْعَظِيمِ."]]},{"id":"bi47_55","label":"آدَابُ الْعَلَاقَةِ بِالْمَعَارِفِ · ٥٥","segs":[["matn","وَصَلَّى اللَّهُ عَلَى سَيِّدِنَا مُحَمَّدٍ وَآلِهِ وَصَحْبِهِ، وَسَلَّمَ تَسْلِيمًا كَثِيرًا."]]}],"group":"الْقِسْمُ الثَّالِثُ الْقَوْلُ فِي آدَابِ الصُّحْبَةِ"}],"sharh":false};
